window.SECTIONS = [{"id":"fund","no":"01","ar":"أساسيات IOS والتنقل","en":"IOS Fundamentals","grp":"basics","count":23},{"id":"basic","no":"02","ar":"الإعداد الأساسي والأمان","en":"Basic Setup & Security","grp":"basics","count":25},{"id":"files","no":"03","ar":"الملفات والنسخ الاحتياطي","en":"Files & Backup","grp":"basics","count":14},{"id":"intf","no":"04","ar":"الواجهات وعناوين IP","en":"Interfaces & IP","grp":"basics","count":18},{"id":"vlan","no":"05","ar":"VLANs وTrunking","en":"VLANs & Trunking","grp":"switching","count":19},{"id":"stp","no":"06","ar":"Spanning Tree وEtherChannel","en":"STP & EtherChannel","grp":"switching","count":22},{"id":"l2sec","no":"07","ar":"أمان الطبقة الثانية","en":"Layer 2 Security","grp":"switching","count":20},{"id":"route","no":"08","ar":"التوجيه الساكن","en":"Static Routing","grp":"routing","count":10},{"id":"ospf","no":"09","ar":"OSPF","en":"OSPF","grp":"routing","count":20},{"id":"eigrp","no":"10","ar":"EIGRP","en":"EIGRP","grp":"routing","count":14},{"id":"rip","no":"11","ar":"RIP وإعادة التوزيع","en":"RIP & Redistribution","grp":"routing","count":10},{"id":"bgp","no":"12","ar":"BGP","en":"BGP","grp":"routing","count":12},{"id":"fhrp","no":"13","ar":"HSRP / VRRP / GLBP","en":"First Hop Redundancy","grp":"routing","count":11},{"id":"acl","no":"14","ar":"قوائم التحكم ACLs","en":"Access Control Lists","grp":"services","count":11},{"id":"nat","no":"15","ar":"ترجمة العناوين NAT","en":"Network Address Translation","grp":"services","count":10},{"id":"dhcp","no":"16","ar":"DHCP","en":"DHCP","grp":"services","count":11},{"id":"svc","no":"17","ar":"NTP / Syslog / SNMP","en":"Network Services","grp":"services","count":15},{"id":"qos","no":"18","ar":"QoS وأدوات المراقبة","en":"QoS & Monitoring","grp":"services","count":14},{"id":"auto","no":"19","ar":"الأتمتة وSDN","en":"Automation & SDN","grp":"modern","count":8},{"id":"wlan","no":"20","ar":"الشبكات اللاسلكية","en":"Wireless","grp":"modern","count":8},{"id":"tshoot","no":"21","ar":"استكشاف الأخطاء","en":"Troubleshooting","grp":"modern","count":28},{"id":"appx","no":"22","ar":"ملاحق ومراجع سريعة","en":"Appendix","grp":"modern","count":0},{"id":"plan","no":"23","ar":"تمارين معملية","en":"Hands-on Labs","grp":"modern","count":10},{"id":"ipv6","no":"24","ar":"IPv6 المتقدم","en":"Advanced IPv6","grp":"modern","count":16}];
window.COMMANDS = [{"i":0,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"enable","synPlain":"enable","mode":"User EXEC → Priv EXEC","modeCls":"m-uexec","ar":"ينقلك من وضع المستخدم المحدود <code>&gt;</code> إلى وضع الصلاحيات الكاملة <code>#</code>. عند وجود <b>enable secret</b> سيطلب كلمة السر. هذا هو المستوى الذي يسمح بـ <code>show running-config</code> و<code>debug</code> و<code>reload</code>.","en":"Moves from User EXEC (>) to Privileged EXEC (#); prompts for the enable secret if one is configured.","ex":"<pre><span class=\"p\">Router&gt;</span> enable\nPassword: ******\n<span class=\"p\">Router#</span></pre>","exPlain":"Router> enable\nPassword: ******\nRouter#","neg":"disable","kind":"cmd"},{"i":1,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"configure terminal","synPlain":"configure terminal","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يدخلك إلى وضع الإعداد العام <code>(config)#</code>. كل تعديل دائم على الجهاز يبدأ من هنا. الاختصار الشائع <code>conf t</code> يعمل لأن IOS يقبل البادئات غير المتشابهة.","en":"Enters Global Configuration mode (config)#, the starting point for every persistent change.","ex":"<pre><span class=\"p\">Router#</span> configure terminal\nEnter configuration commands, one per line. End with CNTL/Z.\n<span class=\"p\">Router(config)#</span></pre>","exPlain":"Router# configure terminal\nEnter configuration commands, one per line. End with CNTL/Z.\nRouter(config)#","neg":"end","kind":"cmd"},{"i":2,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"exit | end","synPlain":"exit | end","mode":"أي Mode","modeCls":"m-any","ar":"<code>exit</code> ينزل مستوى واحداً فقط (من Interface إلى Global مثلاً)، أما <code>end</code> فيقفز مباشرة إلى <code>#</code> من أي عمق. استخدم <code>end</code> دائماً بعد الانتهاء من إعداد واجهة، لأن نسيانك للـ Mode هو السبب الأول لأخطاء المعمل.","en":"exit steps back one mode level; end jumps straight to Privileged EXEC from any configuration depth.","ex":"<pre><span class=\"p\">Router(config-if)#</span> exit\n<span class=\"p\">Router(config)#</span> end\n<span class=\"p\">Router#</span></pre>","exPlain":"Router(config-if)# exit\nRouter(config)# end\nRouter#","neg":"","kind":"cmd"},{"i":3,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"do <i>&lt;exec-command&gt;</i>","synPlain":"do <exec-command>","mode":"أي Config Mode","modeCls":"m-any","ar":"ينفّذ أمر عرض من داخل وضع الإعداد بدون الخروج منه. لا يعمل مع أوامر الإعداد، فقط مع أوامر EXEC مثل <code>show</code> و<code>ping</code>. ميزة عملية ضخمة في المعمل.","en":"Runs any EXEC command (show, debug, clear) from inside a configuration mode without leaving it.","ex":"<pre><span class=\"p\">Router(config-if)#</span> do show ip interface brief\nInterface     IP-Address      OK? Method Status  Protocol\nGi0/0         10.1.1.1        YES manual up      up</pre>","exPlain":"Router(config-if)# do show ip interface brief\nInterface     IP-Address      OK? Method Status  Protocol\nGi0/0         10.1.1.1        YES manual up      up","neg":"","kind":"cmd"},{"i":4,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"? | <i>partial-command</i>?","synPlain":"? | partial-command?","mode":"أي Mode","modeCls":"m-any","ar":"أقوى أداة في IOS. كتابة <code>?</code> وحدها تعرض كل الأوامر المتاحة في المستوى الحالي، وكتابتها ملتصقة بأمر تعرض الكلمات المكمّلة له، وكتابتها بعد مسافة تعرض المعاملات (parameters). في الامتحان، إذا نسيت صيغة أمر، اكتب بدايته ثم <code>?</code>.","en":"Context help: a lone ? lists every command available in the current mode; command? completes the keyword.","ex":"<pre><span class=\"p\">Router(config)#</span> ip ?\n  access-list   Named access-list\n  address       Set IP address\n  dhcp          Configure DHCP server\n  route         Establish static routes\n<span class=\"p\">Router(config)#</span> interface g0/0 ?\n  &lt;cr&gt;</pre>","exPlain":"Router(config)# ip ?\n  access-list   Named access-list\n  address       Set IP address\n  dhcp          Configure DHCP server\n  route         Establish static routes\nRouter(config)# interface g0/0 ?\n  <cr>","neg":"","kind":"cmd"},{"i":5,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show <i>keyword</i> ?","synPlain":"show keyword ?","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض كل الصيغ الفرعية للأمر. مفيد لاكتشاف الخيارات التي لا تحفظها، مثل خيارات <code>show ip ospf</code> أو <code>show interfaces</code>.","en":"Reveals the sub-keywords a show command accepts — the fastest way to discover available options.","ex":"<pre><span class=\"p\">Router#</span> show ip ospf ?\n  border-routers  OSPF border routers\n  database        OSPF database\n  interface       OSPF interface status\n  neighbor        OSPF neighbor list</pre>","exPlain":"Router# show ip ospf ?\n  border-routers  OSPF border routers\n  database        OSPF database\n  interface       OSPF interface status\n  neighbor        OSPF neighbor list","neg":"","kind":"cmd"},{"i":6,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"terminal length <i>lines</i>","synPlain":"terminal length lines","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يوقف تقسيم المخرجات إلى صفحات (<code>--More--</code>). القيمة <code>0</code> تعني بلا حدود. أمر إلزامي عند أتمتة القراءة أو عند نسخ مخرجات طويلة.","en":"Sets how many lines are displayed before --More--; 0 disables paging entirely.","ex":"<pre><span class=\"p\">Router#</span> terminal length 0\n<span class=\"p\">Router#</span> show running-config</pre>","exPlain":"Router# terminal length 0\nRouter# show running-config","neg":"terminal length 24","kind":"cmd"},{"i":7,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"terminal monitor","synPlain":"terminal monitor","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يجعل رسائل السجل و<code>debug</code> تظهر على جلسة Telnet/SSH الحالية. افتراضياً تظهر على الكونسول فقط، لذلك يعتقد كثيرون أن الـ debug «لا يعمل» عن بُعد.","en":"Streams debug and syslog output to the current VTY (Telnet/SSH) session; it has no effect on the console.","ex":"<pre><span class=\"p\">Router#</span> terminal monitor\n<span class=\"p\">Router#</span> debug ip ospf adj</pre>","exPlain":"Router# terminal monitor\nRouter# debug ip ospf adj","neg":"terminal no monitor","kind":"cmd"},{"i":8,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show history","synPlain":"show history","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض آخر 10 أوامر نُفّذت في الجلسة. مع <code>show run</code> يساعدك على تتبّع ما فعلته فعلياً. استخدم <code>show history all</code> لعرض سجل جميع المستخدمين.","en":"Lists the last commands typed in this session (buffer default 10, sized with terminal history size).","ex":"<pre><span class=\"p\">Router#</span> show history\n  show ip route\n  conf t\n  interface g0/0</pre>","exPlain":"Router# show history\n  show ip route\n  conf t\n  interface g0/0","neg":"","kind":"cmd"},{"i":9,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show running-config","synPlain":"show running-config","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الإعداد الفعّال في الذاكرة (RAM). أي تغيير تنفّذه يظهر هنا فوراً، لكنه <b>يُفقد عند إعادة التشغيل</b> إن لم تحفظه. مع <code>| section</code> أو <code>| include</code> يصبح أداة تحقق دقيقة.","en":"Dumps the active configuration held in RAM, including every value changed from its factory default.","ex":"<pre><span class=\"p\">Router#</span> show running-config | section interface\n<span class=\"p\">Router#</span> show running-config | include hostname|enable</pre>","exPlain":"Router# show running-config | section interface\nRouter# show running-config | include hostname|enable","neg":"show startup-config","kind":"cmd"},{"i":10,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show version","synPlain":"show version","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"أول أمر يجب أن تكتبه في أي جهاز جديد أو في أي سؤال تشخيص. يعطيك: إصدار IOS ومجموعة الميزات (IP Base / Advanced IP Services)، موديل الجهاز، كمية RAM و NVRAM، قيمة <b>Configuration register</b> (مهمة في استعادة كلمة السر)، وسبب آخر إعادة تشغيل، ووقت تشغيل الجهاز.","en":"Displays IOS image, uptime, licence level, memory, and the configuration register value.","ex":"<pre><span class=\"p\">Router#</span> show version\nCisco IOS Software, C2900 Software ... Version 15.7(3)M\nRouter uptime is 3 hours, 12 minutes\nSystem image file is \"flash0:c2900-universalk9-mz.SPA.157-3.M.bin\"\nConfiguration register is 0x2102</pre>","exPlain":"Router# show version\nCisco IOS Software, C2900 Software ... Version 15.7(3)M\nRouter uptime is 3 hours, 12 minutes\nSystem image file is \"flash0:c2900-universalk9-mz.SPA.157-3.M.bin\"\nConfiguration register is 0x2102","neg":"","kind":"cmd"},{"i":11,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show ip interface brief","synPlain":"show ip interface brief","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"الجدول الأسرع لتشخيص حالة الواجهات. الأعمدة: العنوان، طريقة التعلم (manual/DHCP/unset)، <b>Status</b> (حالة الطبقة الثانية: up/down/admin down)، و<b>Protocol</b> (حالة الطبقة الثالثة). <code>up/down</code> = مشكلة في الطبقة الثانية (كابل، سرعة، encapsulation)، و<code>administratively down</code> = <code>shutdown</code>.","en":"One-line status per interface: IP address, assignment method, link state, and protocol state.","ex":"<pre><span class=\"p\">Router#</span> show ip interface brief\nInterface   IP-Address    OK? Method Status              Protocol\nGi0/0       10.1.1.1      YES manual up                  up\nGi0/1       unassigned    YES unset  administratively down down\nSe0/0/0     unassigned    YES unset  down                down</pre>","exPlain":"Router# show ip interface brief\nInterface   IP-Address    OK? Method Status              Protocol\nGi0/0       10.1.1.1      YES manual up                  up\nGi0/1       unassigned    YES unset  administratively down down\nSe0/0/0     unassigned    YES unset  down                down","neg":"","kind":"cmd"},{"i":12,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show interfaces <i>[interface]</i>","synPlain":"show interfaces [interface]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"التقرير التفصيلي الكامل: MAC، السرعة والـ duplex، MTU، bandwidth، حالة الخط، الأخطاء (CRC, input errors, collisions)، الحمل (load)، والـ queue drops. الأخطاء المتزايدة على جهة واحدة تعني غالباً كابلًا أو سرعة غير متطابقة.","en":"Deep per-interface counters: duplex, speed, CRC/input errors, collisions, and traffic rates.","ex":"<pre><span class=\"p\">Router#</span> show interfaces g0/0\nGigabitEthernet0/0 is up, line protocol is up\n  Hardware is iGbE, address is 00e0.8f57.1234\n  MTU 1500 bytes, BW 1000000 Kbit/sec\n  Full-duplex, 1000Mb/s, media type is RJ45\n  5 minute input rate 2000 bits/sec, 3 packets/sec</pre>","exPlain":"Router# show interfaces g0/0\nGigabitEthernet0/0 is up, line protocol is up\n  Hardware is iGbE, address is 00e0.8f57.1234\n  MTU 1500 bytes, BW 1000000 Kbit/sec\n  Full-duplex, 1000Mb/s, media type is RJ45\n  5 minute input rate 2000 bits/sec, 3 packets/sec","neg":"show interfaces g0/0 | include error|drops|duplex","kind":"cmd"},{"i":13,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show interfaces status","synPlain":"show interfaces status","mode":"Privileged EXEC (Switch)","modeCls":"m-pexec","ar":"خاص بالسويتش: يعرض لكل منفذ الحالة، الـ VLAN، السرعة، الـ duplex، ونوع الكابل. أسرع طريقة لمعرفة هل المنفذ <code>connected</code> أم <code>notconnect</code> أم <code>err-disabled</code> — والأخير مؤشر قوي على Port Security أو BPDU Guard.","en":"Switch-only table of port state, VLAN, duplex, speed, and media type.","ex":"<pre><span class=\"p\">SW1#</span> show interfaces status\nPort   Name      Status       Vlan  Duplex Speed Type\nGi0/1  Uplink    connected    trunk a-full a-1000 10/100/1000BaseTX\nGi0/2  PC-A      notconnect   10    auto   auto   10/100/1000BaseTX\nGi0/3  PC-B      err-disabled 10    auto   auto   10/100/1000BaseTX</pre>","exPlain":"SW1# show interfaces status\nPort   Name      Status       Vlan  Duplex Speed Type\nGi0/1  Uplink    connected    trunk a-full a-1000 10/100/1000BaseTX\nGi0/2  PC-A      notconnect   10    auto   auto   10/100/1000BaseTX\nGi0/3  PC-B      err-disabled 10    auto   auto   10/100/1000BaseTX","neg":"","kind":"cmd"},{"i":14,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show clock","synPlain":"show clock","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض ساعة الجهاز ومنطقة الوقت ومصدر التوقيت. إن ظهر <code>*</code> قبل الوقت فالساعة غير مُزامنة. توقيت دقيق ضروري لقراءة السجلات وربط الأحداث.","en":"Shows the software clock, its timezone, and whether the time is authoritative (period marker).","ex":"<pre><span class=\"p\">Router#</span> show clock\n*18:42:10.115 UTC Sun Oct 25 2026</pre>","exPlain":"Router# show clock\n*18:42:10.115 UTC Sun Oct 25 2026","neg":"clock set 18:42:00 25 Oct 2026","kind":"cmd"},{"i":15,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show protocols","synPlain":"show protocols","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض حالة الطبقة الثالثة لكل واجهة (up/down) مع عنوان IP. مختصر مفيد جداً في معامل التوجيه لأنه يركز على الـ protocol state فقط.","en":"Compact view of which routing protocols are running and which interfaces they are enabled on.","ex":"<pre><span class=\"p\">Router#</span> show protocols\nGlobal values:\n  Internet Protocol routing is enabled\nGigabitEthernet0/0 is up, line protocol is up\n  Internet address is 10.1.1.1/24</pre>","exPlain":"Router# show protocols\nGlobal values:\n  Internet Protocol routing is enabled\nGigabitEthernet0/0 is up, line protocol is up\n  Internet address is 10.1.1.1/24","neg":"","kind":"cmd"},{"i":16,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show users | show sessions","synPlain":"show users | show sessions","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"<code>show users</code> يعرض من هم متصلون <b>بهذا</b> الجهاز، و<code>show sessions</code> يعرض الجلسات الصادرة التي فتحتها <b>من</b> هذا الجهاز إلى أجهزة أخرى. للعودة لجلسة معلّقة اضغط <span class=\"kbd\">Enter</span> ثم رقم الجلسة، أو <span class=\"kbd\">Ctrl+Shift+6</span> ثم <span class=\"kbd\">x</span> للتنقل.","en":"Lists who is logged in locally (users) and outbound Telnet sessions (sessions).","ex":"<pre><span class=\"p\">Router#</span> show users\n    Line       User       Host(s)              Idle       Location\n   0 con 0                idle                 00:00:00\n*  2 vty 0     admin      idle                 00:00:12   10.1.1.50</pre>","exPlain":"Router# show users\n    Line       User       Host(s)              Idle       Location\n   0 con 0                idle                 00:00:00\n*  2 vty 0     admin      idle                 00:00:12   10.1.1.50","neg":"clear line vty 0","kind":"cmd"},{"i":17,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"ping <i>ip</i> [source <i>intf</i>] [repeat <i>n</i>] [size <i>bytes</i>]","synPlain":"ping ip [source intf] [repeat n] [size bytes]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"اختبار الوصولية عبر ICMP. الحروف في المخرجات هي مفتاح التشخيص: <code>!</code> نجاح، <code>.</code> انتهت المهلة (timeout)، <code>U</code> Destination Unreachable، <code>M</code> تحتاج تجزئة (MTU). الخيار <code>source</code> يختبر من عنوان محدد — ضروري عند اختبار ACLs لأن ACL قد تسمح بعنوان وتمنع آخر.","en":"Tests reachability with ICMP echo; source forces a specific interface, size probes MTU and fragmentation.","ex":"<pre><span class=\"p\">Router#</span> ping 192.168.20.10 source g0/0 repeat 100 size 1500\n!!!!!\nSuccess rate is 100 percent (5/5)</pre>","exPlain":"Router# ping 192.168.20.10 source g0/0 repeat 100 size 1500\n!!!!!\nSuccess rate is 100 percent (5/5)","neg":"ping","kind":"cmd"},{"i":18,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"traceroute <i>ip</i> [probe <i>n</i>] [numeric]","synPlain":"traceroute ip [probe n] [numeric]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يكشف المسار قفزة بقفزة. النجمات <code>*</code> تعني أن راوتراً في المسار لا يرد على ICMP أو أن ACL يمنع الرد — وهذا لا يعني بالضرورة انقطاع المسار. <code>numeric</code> يمنع ترجمة الأسماء ويسرّع النتيجة.","en":"Maps the path hop by hop; numeric skips DNS lookups, probe sets probes sent per hop.","ex":"<pre><span class=\"p\">Router#</span> traceroute 8.8.8.8 numeric\n 1  10.1.1.2    1 msec\n 2  200.1.1.1   4 msec\n 3  *  *  *</pre>","exPlain":"Router# traceroute 8.8.8.8 numeric\n 1  10.1.1.2    1 msec\n 2  200.1.1.1   4 msec\n 3  *  *  *","neg":"","kind":"cmd"},{"i":19,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"debug <i>feature</i> | undebug all","synPlain":"debug feature | undebug all","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الأحداث الحيّة بالتفصيل. <b>لا تستخدمه على جهاز إنتاج</b> بدون ACL لتقييده، لأن مخرجاته تستهلك CPU وقد تُسقط الجهاز. القاعدة: <code>debug</code> واحد فقط في كل مرة، وأنههِ فوراً بـ <code>undebug all</code> (أو <code>u all</code>).","en":"Turns on real-time event debugging for one feature; always stop it with undebug all to protect the CPU.","ex":"<pre><span class=\"p\">Router#</span> debug ip ospf adj\nOSPF: Interface GigabitEthernet0/0 going Up\n<span class=\"p\">Router#</span> undebug all\nAll possible debugging has been turned off</pre>","exPlain":"Router# debug ip ospf adj\nOSPF: Interface GigabitEthernet0/0 going Up\nRouter# undebug all\nAll possible debugging has been turned off","neg":"show logging","kind":"cmd"},{"i":20,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show logging","synPlain":"show logging","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض محتوى الـ buffer الداخلي للسجلات: انخفاض/ارتفاع الواجهات، تغيّر جيران OSPF، أحداث Port Security، فشل تسجيل الدخول. أسرع طريق لمعرفة «ماذا حدث قبل دقيقة».","en":"Shows the syslog buffer plus a tally of messages by severity since boot.","ex":"<pre><span class=\"p\">Router#</span> show logging\nSyslog logging: enabled (11 messages dropped)\n    Console logging: level debugging\n*Oct 25 18:30:11: %LINK-3-UPDOWN: Interface Gi0/1, changed state to up\n*Oct 25 18:30:14: %LINEPROTO-5-UPDOWN: Line protocol on Gi0/1, changed to up</pre>","exPlain":"Router# show logging\nSyslog logging: enabled (11 messages dropped)\n    Console logging: level debugging\n*Oct 25 18:30:11: %LINK-3-UPDOWN: Interface Gi0/1, changed state to up\n*Oct 25 18:30:14: %LINEPROTO-5-UPDOWN: Line protocol on Gi0/1, changed to up","neg":"","kind":"cmd"},{"i":21,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"telnet <i>ip</i> | ssh -l <i>user</i> <i>ip</i>","synPlain":"telnet ip | ssh -l user ip","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"فتح جلسة إدارة عن بُعد. Telnet يرسل كلمة السر كنص واضح (غير آمن)، وSSH مشفّر ويفضّل دائماً. إن فشل SSH تحقق من: <code>ip domain-name</code>، مفاتيح RSA مولّدة، <code>transport input ssh</code>، ومستخدم محلي.","en":"Opens an outbound management session; SSH is the encrypted, production-safe choice.","ex":"<pre><span class=\"p\">PC&gt;</span> ssh -l admin 10.1.1.1\nPassword: ******\n<span class=\"p\">Router#</span></pre>","exPlain":"PC> ssh -l admin 10.1.1.1\nPassword: ******\nRouter#","neg":"exit","kind":"cmd"},{"i":22,"sec":"fund","no":"01","secAr":"أساسيات IOS والتنقل","secEn":"IOS Fundamentals","grp":"basics","syn":"show tech-support","synPlain":"show tech-support","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يجمع مئات أسطر التشخيص في مخرج واحد (version، run-config، interfaces، logging، processes، memory) لتقديمه للدعم الفني. لا تشغّله على جهاز مزدحم وقت الذروة لأنه يستهلك CPU ويستغرق دقائق.","en":"Bundles hundreds of show outputs into one report for TAC cases; CPU-heavy, so run it with care.","ex":"<pre><span class=\"p\">Router#</span> show tech-support | redirect flash:tech.txt</pre>","exPlain":"Router# show tech-support | redirect flash:tech.txt","neg":"","kind":"cmd"},{"i":23,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"hostname <i>name</i>","synPlain":"hostname name","mode":"Global Config","modeCls":"m-gconf","ar":"يحدد اسم الجهاز الذي يظهر في الـ prompt وفي تقارير <code>show cdp neighbors</code> و<code>show ip ospf neighbor</code> ورسائل السجل. الاسم مهم عملياً: أخطاء التوجيه تُشخّص أسرع بكثير عندما تعرف أي راوتر أرسل الرسالة.","en":"Sets the device name, which also becomes the prompt and the default source for SSH, OSPF, and BGP identifiers.","ex":"<pre><span class=\"p\">Router(config)#</span> hostname R1-Core\n<span class=\"p\">R1-Core(config)#</span></pre>","exPlain":"Router(config)# hostname R1-Core\nR1-Core(config)#","neg":"no hostname","kind":"cmd"},{"i":24,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"ip domain-name <i>domain</i>","synPlain":"ip domain-name domain","mode":"Global Config","modeCls":"m-gconf","ar":"يحدد اسم النطاق. ليس ترفاً: توليد مفاتيح RSA <b>يرفض</b> العمل بدونه، لأنه يبني الاسم الكامل <code>hostname.domain</code> كمعرّف للمفتاح. يُستخدم أيضاً لإكمال أسماء الاستعلامات في DNS.","en":"Defines the DNS domain used to build the FQDN required for RSA key generation.","ex":"<pre><span class=\"p\">R1(config)#</span> ip domain-name lab.local\n<span class=\"p\">R1(config)#</span> ip domain-lookup</pre>","exPlain":"R1(config)# ip domain-name lab.local\nR1(config)# ip domain-lookup","neg":"no ip domain-name","kind":"cmd"},{"i":25,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"no ip domain-lookup","synPlain":"no ip domain-lookup","mode":"Global Config","modeCls":"m-gconf","ar":"يمنع الجهاز من محاولة ترجمة الأخطاء المطبعية إلى أسماء DNS. بدونها، أي أمر خاطئ يجعلك تنتظر <span class=\"num\">30–60</span> ثانية قبل عودة الـ prompt. أمر إلزامي في كل معمل.","en":"Stops IOS from resolving mistyped commands through DNS, eliminating the classic 30-60 second hang.","ex":"<pre><span class=\"p\">R1(config)#</span> no ip domain-lookup</pre>","exPlain":"R1(config)# no ip domain-lookup","neg":"ip domain-lookup","kind":"cmd"},{"i":26,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"enable secret <i>password</i>","synPlain":"enable secret password","mode":"Global Config","modeCls":"m-gconf","ar":"كلمة سر الوصول إلى Privileged EXEC، مخزّنة بتشفير <b>MD5</b> (أو scrypt في الإصدارات الحديثة). لها <b>أولوية على</b> <code>enable password</code>: إذا وُجد الاثنان فالأول هو المعتمد والثاني يُتجاهل تماماً. هذا سؤال امتحاني متكرر.","en":"Sets the Privileged EXEC password stored as a one-way hash; it overrides enable password.","ex":"<pre><span class=\"p\">R1(config)#</span> enable secret Cisco@123\n<span class=\"p\">R1(config)#</span> enable algorithm-type scrypt secret Cisco@123</pre>","exPlain":"R1(config)# enable secret Cisco@123\nR1(config)# enable algorithm-type scrypt secret Cisco@123","neg":"no enable secret","kind":"cmd"},{"i":27,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"enable password <i>password</i>","synPlain":"enable password password","mode":"Global Config","modeCls":"m-gconf","ar":"الطريقة القديمة، تُخزّن كنص واضح (أو تشفير ضعيف جداً نوع 7 مع <code>service password-encryption</code>). موجودة للتوافق القديم فقط. <b>لا تستخدمها</b> — استخدم <code>enable secret</code>.","en":"Legacy clear-text or type-7 privileged password; kept only for very old images.","ex":"<pre><span class=\"p\">R1(config)#</span> enable password cisco</pre>","exPlain":"R1(config)# enable password cisco","neg":"no enable password","kind":"cmd"},{"i":28,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"service password-encryption","synPlain":"service password-encryption","mode":"Global Config","modeCls":"m-gconf","ar":"يشفّر كلمات السر المخزّنة كنص واضح (line passwords, username password, enable password) بنوع <b>7</b>. التشفير نوع 7 <b>قابل للفك</b> بسهولة، فهو يمنع النظر العابر فقط وليس الاختراق. مع ذلك يطلبه الامتحان كخطوة أساسية في تأمين الجهاز.","en":"Applies weak type-7 encryption to every clear-text password in the configuration.","ex":"<pre><span class=\"p\">R1(config)#</span> service password-encryption\n<span class=\"p\">R1(config)#</span> do show run | include password\nenable secret 5 $1$mERr$9cTjUIEqNGurQiFU.ZeCi1\npassword 7 0822455D0A16</pre>","exPlain":"R1(config)# service password-encryption\nR1(config)# do show run | include password\nenable secret 5 $1$mERr$9cTjUIEqNGurQiFU.ZeCi1\npassword 7 0822455D0A16","neg":"no service password-encryption","kind":"cmd"},{"i":29,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"username <i>name</i> privilege <i>level</i> secret <i>password</i>","synPlain":"username name privilege level secret password","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ مستخدماً محلياً لقاعدة البيانات المحلية. <code>secret</code> يشفّر بكلمة مرور قوية (MD5/scrypt)، أما <code>password</code> فيخزّنها بشكل ضعيف. الـ privilege من 0 إلى 15؛ المستوى 15 يعطي صلاحيات كاملة تعادل <code>enable</code>.","en":"Creates a local user with a privilege level and hashed secret for login local or AAA.","ex":"<pre><span class=\"p\">R1(config)#</span> username admin privilege 15 secret Adm1n@2026\n<span class=\"p\">R1(config)#</span> username helpdesk privilege 1 secret Help@123</pre>","exPlain":"R1(config)# username admin privilege 15 secret Adm1n@2026\nR1(config)# username helpdesk privilege 1 secret Help@123","neg":"no username admin","kind":"cmd"},{"i":30,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"security passwords min-length <i>n</i>","synPlain":"security passwords min-length n","mode":"Global Config","modeCls":"m-gconf","ar":"يفرض حداً أدنى لطول كلمات السر الجديدة (<span class=\"num\">6–8</span> افتراضياً). أي كلمة أقصر تُرفض عند إنشائها. لا يؤثر على الكلمات الموجودة مسبقاً.","en":"Rejects any new password shorter than n characters (default 0, 8+ recommended).","ex":"<pre><span class=\"p\">R1(config)#</span> security passwords min-length 10</pre>","exPlain":"R1(config)# security passwords min-length 10","neg":"no security passwords min-length","kind":"cmd"},{"i":31,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"line console 0","synPlain":"line console 0","mode":"Global Config","modeCls":"m-gconf","ar":"يدخلك إلى إعداد منفذ الكونسول الفيزيائي. هذا هو خط الدفاع الأول: من يصل إلى الكابل يستطيع إعادة تشغيل الجهاز وتجاوز الإعدادات، لذا يجب أن يكون محمياً بكلمة سر و<code>exec-timeout</code>.","en":"Enters Line Configuration for the physical console port.","ex":"<pre><span class=\"p\">R1(config)#</span> line console 0\n<span class=\"p\">R1(config-line)#</span> password Con@123\n<span class=\"p\">R1(config-line)#</span> login\n<span class=\"p\">R1(config-line)#</span> exec-timeout 5 0\n<span class=\"p\">R1(config-line)#</span> logging synchronous</pre>","exPlain":"R1(config)# line console 0\nR1(config-line)# password Con@123\nR1(config-line)# login\nR1(config-line)# exec-timeout 5 0\nR1(config-line)# logging synchronous","neg":"no password","kind":"cmd"},{"i":32,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"line vty <i>start</i> <i>end</i>","synPlain":"line vty start end","mode":"Global Config","modeCls":"m-gconf","ar":"يدخلك إلى خطوط الطرفية الافتراضية (Virtual Teletype) المستخدمة في Telnet وSSH. العدد يختلف حسب المنصة: 5 خطوط (0 4) على الأجهزة القديمة، و16 (0 15) على الأجهزة الحديثة — إذا حددت 0 4 فقط فقد يُرفض اتصال SSH الخامس عشر بلا سبب واضح.","en":"Enters Line Configuration for the virtual terminal lines used by Telnet and SSH.","ex":"<pre><span class=\"p\">R1(config)#</span> line vty 0 15\n<span class=\"p\">R1(config-line)#</span> login local\n<span class=\"p\">R1(config-line)#</span> transport input ssh\n<span class=\"p\">R1(config-line)#</span> exec-timeout 10 0</pre>","exPlain":"R1(config)# line vty 0 15\nR1(config-line)# login local\nR1(config-line)# transport input ssh\nR1(config-line)# exec-timeout 10 0","neg":"no transport input","kind":"cmd"},{"i":33,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"password <i>pass</i> | login | login local","synPlain":"password pass | login | login local","mode":"Line Config","modeCls":"m-lconf","ar":"<code>password</code> يحدد كلمة سر الخط. <code>login</code> يجعل الجهاز يطلبها. <code>login local</code> يجعل الجهاز يطلب <b>اسم مستخدم وكلمة سر</b> من قاعدة <code>username</code> المحلية — وهو المطلوب لـ SSH. بدون أي منهما، الدخول يكون بلا مصادقة (خطر أمني).","en":"Sets the line password and chooses whether login uses the line password or the local user database.","ex":"<pre><span class=\"p\">R1(config-line)#</span> login local\n<span class=\"p\">R1(config-line)#</span> no password</pre>","exPlain":"R1(config-line)# login local\nR1(config-line)# no password","neg":"no login","kind":"cmd"},{"i":34,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"exec-timeout <i>minutes</i> <i>seconds</i>","synPlain":"exec-timeout minutes seconds","mode":"Line Config","modeCls":"m-lconf","ar":"يقطع الجلسة تلقائياً بعد فترة خمول. الافتراضي 10 دقائق. القيمة <code>0 0</code> تعطّل المهلة نهائياً (ممنوع أمنياً على أجهزة الإنتاج، لكنه مريح في المعمل). أمر أساسي في كل قائمة تأمين.","en":"Idle timeout for a line; 0 0 disables it completely (lab use only).","ex":"<pre><span class=\"p\">R1(config-line)#</span> exec-timeout 5 30</pre>","exPlain":"R1(config-line)# exec-timeout 5 30","neg":"no exec-timeout","kind":"cmd"},{"i":35,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"logging synchronous","synPlain":"logging synchronous","mode":"Line Config","modeCls":"m-lconf","ar":"يمنع رسائل السجل من قطع ما تكتبه: بعد ظهور رسالة، يعيد IOS طباعة السطر الذي كنت تكتبه. جمالي وعملي معاً، خصوصاً عند ظهور رسائل <code>%LINEPROTO</code> أثناء الإعداد.","en":"Re-prints the command line after asynchronous log messages so typing is never interrupted.","ex":"<pre><span class=\"p\">R1(config-line)#</span> logging synchronous</pre>","exPlain":"R1(config-line)# logging synchronous","neg":"no logging synchronous","kind":"cmd"},{"i":36,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"line aux 0","synPlain":"line aux 0","mode":"Global Config","modeCls":"m-gconf","ar":"خط المودم المساعد. في أغلب الشبكات الحديثة غير مستخدم ويُترك مغلقاً لأسباب أمنية — أفضل ممارسة: <code>no exec</code> و<code>transport input none</code>.","en":"Enters Line Configuration for the auxiliary (modem) port.","ex":"<pre><span class=\"p\">R1(config)#</span> line aux 0\n<span class=\"p\">R1(config-line)#</span> no exec\n<span class=\"p\">R1(config-line)#</span> transport input none</pre>","exPlain":"R1(config)# line aux 0\nR1(config-line)# no exec\nR1(config-line)# transport input none","neg":"exec","kind":"cmd"},{"i":37,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"banner motd <i>#text#</i>","synPlain":"banner motd #text#","mode":"Global Config","modeCls":"m-gconf","ar":"رسالة تُعرض قبل تسجيل الدخول (Message of the Day). قانونياً يجب أن تحتوي على تحذير صريح بعدم السماح بالدخول غير المصرّح — بدونها قد لا يُعتدّ بالتحذير في الملاحقة القانونية. استخدم فاصلاً لا يظهر في النص (مثل <code>#</code> أو <code>^</code>).","en":"Message shown before login; use it for legal warnings, never for sensitive information.","ex":"<pre><span class=\"p\">R1(config)#</span> banner motd #Authorized access only. All activity is logged.#</pre>","exPlain":"R1(config)# banner motd #Authorized access only. All activity is logged.#","neg":"no banner motd","kind":"cmd"},{"i":38,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"banner login <i>#text#</i>","synPlain":"banner login #text#","mode":"Global Config","modeCls":"m-gconf","ar":"رسالة تظهر <b>بعد</b> رسالة MOTD وقبل طلب اسم المستخدم. الفرق بينها وبين <code>motd</code> سؤال شائع: <code>motd</code> قبل أي مصادقة، و<code>login</code> بين العرض وطلب بيانات الدخول.","en":"Message shown after the MOTD but before authentication.","ex":"<pre><span class=\"p\">R1(config)#</span> banner login #Unauthorized access prohibited.#</pre>","exPlain":"R1(config)# banner login #Unauthorized access prohibited.#","neg":"no banner login","kind":"cmd"},{"i":39,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"crypto key generate rsa [modulus <i>size</i>]","synPlain":"crypto key generate rsa [modulus size]","mode":"Global Config","modeCls":"m-gconf","ar":"يولّد زوج مفاتيح RSA (عام/خاص) اللازم لتشفير جلسة SSH. كلما زاد الحجم زادت الأمان وزاد زمن التوليد. <b>حجم 2048</b> هو المعيار الحالي؛ وأقل من 768 يمنع SSHv2. لحذف المفاتيح: <code>crypto key zeroize rsa</code>.","en":"Generates the RSA key pair that enables SSH; 2048 bits is the modern minimum.","ex":"<pre><span class=\"p\">R1(config)#</span> crypto key generate rsa modulus 2048\nThe name for the keys will be: R1.lab.local\n% Generating 2048 bit RSA keys, keys will be non-exportable...[OK]</pre>","exPlain":"R1(config)# crypto key generate rsa modulus 2048\nThe name for the keys will be: R1.lab.local\n% Generating 2048 bit RSA keys, keys will be non-exportable...[OK]","neg":"crypto key zeroize rsa","kind":"cmd"},{"i":40,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"ip ssh version 2","synPlain":"ip ssh version 2","mode":"Global Config","modeCls":"m-gconf","ar":"يجبر استخدام SSHv2 فقط (الأكثر أماناً، والمدعوم في كل الأجهزة الحديثة). SSHv1 به ثغرات معروفة ويجب تعطيله. تحقق بـ <code>show ip ssh</code>.","en":"Restricts SSH to protocol version 2 and disables the weaker version 1.","ex":"<pre><span class=\"p\">R1(config)#</span> ip ssh version 2\n<span class=\"p\">R1(config)#</span> ip ssh time-out 60\n<span class=\"p\">R1(config)#</span> ip ssh authentication-retries 3</pre>","exPlain":"R1(config)# ip ssh version 2\nR1(config)# ip ssh time-out 60\nR1(config)# ip ssh authentication-retries 3","neg":"no ip ssh version","kind":"cmd"},{"i":41,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"show ip ssh","synPlain":"show ip ssh","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يتحقق من أن SSH مفعّل ويعرض الإصدار والمهلة وعدد المحاولات. إذا ظهر <code>SSH Disabled</code> فالمفاتيح لم تُولّد أو أن الإصدار غير مدعوم.","en":"Confirms SSH is enabled and shows its version, timeouts, and retry limits.","ex":"<pre><span class=\"p\">R1#</span> show ip ssh\nSSH Enabled - version 2.0\nAuthentication timeout: 60 secs; Authentication retries: 3</pre>","exPlain":"R1# show ip ssh\nSSH Enabled - version 2.0\nAuthentication timeout: 60 secs; Authentication retries: 3","neg":"","kind":"cmd"},{"i":42,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"login block-for <i>seconds</i> attempts <i>n</i> within <i>seconds</i>","synPlain":"login block-for seconds attempts n within seconds","mode":"Global Config","modeCls":"m-gconf","ar":"حماية ضد هجوم التخمين (Brute Force): يمنع كل محاولات الدخول لمدة محددة بعد عدد معيّن من المحاولات الفاشلة. ميزة أمنية متقدمة تُذكر في CCNP SEC/ENCOR.","en":"Blocks logins for the given window after n failures — basic brute-force protection.","ex":"<pre><span class=\"p\">R1(config)#</span> login block-for 120 attempts 3 within 60\n<span class=\"p\">R1(config)#</span> login delay 2\n<span class=\"p\">R1(config)#</span> login on-failure log</pre>","exPlain":"R1(config)# login block-for 120 attempts 3 within 60\nR1(config)# login delay 2\nR1(config)# login on-failure log","neg":"no login block-for","kind":"cmd"},{"i":43,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"aaa new-model","synPlain":"aaa new-model","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل إطار AAA (Authentication, Authorization, Accounting). بعد تفعيله تتغيّر طريقة تسجيل الدخول بالكامل وتصبح <code>line password</code> غير كافية. <b>تحذير:</b> قد يقفل عليك الجهاز إن لم تُعدّ طريقة مصادقة قبل الخروج — جهّز <code>aaa authentication login default local</code> فوراً بعده.","en":"Enables the AAA framework (authentication, authorization, accounting) and hides local line passwords.","ex":"<pre><span class=\"p\">R1(config)#</span> aaa new-model\n<span class=\"p\">R1(config)#</span> aaa authentication login default local\n<span class=\"p\">R1(config)#</span> aaa authorization exec default local</pre>","exPlain":"R1(config)# aaa new-model\nR1(config)# aaa authentication login default local\nR1(config)# aaa authorization exec default local","neg":"no aaa new-model","kind":"cmd"},{"i":44,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"privilege exec level <i>level</i> <i>command</i>","synPlain":"privilege exec level level command","mode":"Global Config","modeCls":"m-gconf","ar":"يخصّص مستوى صلاحية لأمر معيّن، لتمنح فريق الدعم أوامر عرض محددة دون إعطائه مستوى 15. مثال: رفع <code>show running-config</code> إلى المستوى 5 ليستخدمه مشرف بصلاحية 5.","en":"Moves a specific command to a custom privilege level for role-based access control.","ex":"<pre><span class=\"p\">R1(config)#</span> privilege exec level 5 show running-config\n<span class=\"p\">R1(config)#</span> username ops privilege 5 secret Ops@123</pre>","exPlain":"R1(config)# privilege exec level 5 show running-config\nR1(config)# username ops privilege 5 secret Ops@123","neg":"no privilege exec level 5 show running-config","kind":"cmd"},{"i":45,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"service timestamps <i>log|debug</i> datetime [localtime]","synPlain":"service timestamps log|debug datetime [localtime]","mode":"Global Config","modeCls":"m-gconf","ar":"يضيف التاريخ والوقت لكل رسالة سجل بدلاً من زمن التشغيل فقط. ضروري لربط الأحداث وتحليلها، ويكمل إعداد NTP.","en":"Prefixes log and debug messages with a date/time stamp; localtime uses the configured timezone.","ex":"<pre><span class=\"p\">R1(config)#</span> service timestamps log datetime msec localtime\n<span class=\"p\">R1(config)#</span> service timestamps debug datetime msec localtime</pre>","exPlain":"R1(config)# service timestamps log datetime msec localtime\nR1(config)# service timestamps debug datetime msec localtime","neg":"no service timestamps log","kind":"cmd"},{"i":46,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"no ip http server | no ip http secure-server","synPlain":"no ip http server | no ip http secure-server","mode":"Global Config","modeCls":"m-gconf","ar":"يعطّل خادم الويب المدمج (HTTP/HTTPS) غير المستخدم. كل خدمة تعمل بلا حاجة هي سطح هجوم إضافي — قاعدة أساسية في تصليب الأجهزة (Hardening).","en":"Disables the HTTP/HTTPS management GUI — a standard hardening step.","ex":"<pre><span class=\"p\">R1(config)#</span> no ip http server\n<span class=\"p\">R1(config)#</span> no ip http secure-server\n<span class=\"p\">R1(config)#</span> no cdp run</pre>","exPlain":"R1(config)# no ip http server\nR1(config)# no ip http secure-server\nR1(config)# no cdp run","neg":"ip http server","kind":"cmd"},{"i":47,"sec":"basic","no":"02","secAr":"الإعداد الأساسي والأمان","secEn":"Basic Setup & Security","grp":"basics","syn":"transport input {ssh | telnet | none}","synPlain":"transport input {ssh | telnet | none}","mode":"Line Config","modeCls":"m-line","ar":"يحدد <b>طريقة الوصول</b> إلى خط VTY. القيمة الافتراضية على IOS القديم <code>transport input all</code> أي Telnet وSSH معاً — وهذا يهدم فائدة SSH. اضبطها على <code>ssh</code> فقط لتُغلق Telnet نهائياً، أو <code>none</code> لتعطيل الخط. التحقق: <code>show line vty 0 4</code> ثم انظر عمود <code>Roty</code>.","en":"Restricts how a VTY line can be reached. The default `all` keeps Telnet open even after you enable SSH, so setting `transport input ssh` is what actually closes the plaintext door.","ex":"<pre><span class=\"p\">R1(config)#</span> line vty 0 4\n<span class=\"p\">R1(config-line)#</span> transport input ssh\n<span class=\"p\">R1(config-line)#</span> login local\n<span class=\"p\">R1#</span> show line vty 0 4\n    Tty Line Typ     Tx/Rx    A Modem  Roty AccO AccI  Uses  Noise Overruns\n      2    2 VTY   9600/9600  -    -      -    -    -     1      0    0/0</pre>","exPlain":"R1(config)# line vty 0 4\nR1(config-line)# transport input ssh\nR1(config-line)# login local\nR1# show line vty 0 4\n    Tty Line Typ     Tx/Rx    A Modem  Roty AccO AccI  Uses  Noise Overruns\n      2    2 VTY   9600/9600  -    -      -    -    -     1      0    0/0","neg":"transport input all","kind":"cmd"},{"i":48,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"copy running-config startup-config","synPlain":"copy running-config startup-config","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"ينسخ الإعداد من RAM إلى NVRAM، فيصبح دائماً بعد إعادة التشغيل. هذا هو الأمر الذي تنساه في نهاية المعمل فتخسر كل شيء. الاختصار القديم <code>write memory</code> (أو <code>wr</code>) يعمل على معظم الإصدارات لكن الصيغة الحديثة هي <code>copy run start</code>.","en":"Saves the RAM configuration to NVRAM so it survives a reload.","ex":"<pre><span class=\"p\">R1#</span> copy running-config startup-config\nDestination filename [startup-config]? <span class=\"p\">[Enter]</span>\nBuilding configuration...\n[OK]</pre>","exPlain":"R1# copy running-config startup-config\nDestination filename [startup-config]? [Enter]\nBuilding configuration...\n[OK]","neg":"تحذير لا يوجد «no» لهذا الأمر — الحفظ لا يُلغى، بل يُستبدل بحفظ جديد","kind":"cmd"},{"i":49,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"copy startup-config running-config","synPlain":"copy startup-config running-config","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"<b>دمج وليس استبدال!</b> يضيف إعدادات NVRAM إلى الإعداد الحالي دون حذف ما هو موجود. لذلك لا يُستخدم للرجوع إلى نسخة قديمة (لأن التغييرات الحالية تبقى). للرجوع الحقيقي: أعد التشغيل أو استخدم <code>configure replace</code>.","en":"Merges NVRAM into RAM; it adds and overwrites but never removes, so it cannot restore an older config.","ex":"<pre><span class=\"p\">R1#</span> copy startup-config running-config\nDestination filename [running-config]? <span class=\"p\">[Enter]</span></pre>","exPlain":"R1# copy startup-config running-config\nDestination filename [running-config]? [Enter]","neg":"#","kind":"cmd"},{"i":50,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"show startup-config","synPlain":"show startup-config","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض ما سيُطبَّق عند التشغيل. إذا كان مختلفاً عن <code>show run</code> فأنت لم تحفظ. شائع جداً في الامتحان: يُطلب منك التحقق من أن الإعداد «دائم».","en":"Shows the configuration that will be loaded at the next boot.","ex":"<pre><span class=\"p\">R1#</span> show startup-config | include hostname\nhostname R1-Core</pre>","exPlain":"R1# show startup-config | include hostname\nhostname R1-Core","neg":"","kind":"cmd"},{"i":51,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"erase startup-config","synPlain":"erase startup-config","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يحذف ملف الإعداد من NVRAM. الجهاز يعود إلى إعداد المصنع بعد إعادة التشغيل (لكن <b>لا</b> قبلها — الإعداد الحالي في RAM يبقى فعّالاً). البديل القديم <code>write erase</code>.","en":"Deletes the saved configuration from NVRAM (it does not touch vlan.dat on switches).","ex":"<pre><span class=\"p\">R1#</span> erase startup-config\nErasing the nvram filesystem will remove all configuration files!\n[confirm] <span class=\"p\">[Enter]</span>\n[OK]\n<span class=\"p\">R1#</span> reload</pre>","exPlain":"R1# erase startup-config\nErasing the nvram filesystem will remove all configuration files!\n[confirm] [Enter]\n[OK]\nR1# reload","neg":"delete vlan.dat","kind":"cmd"},{"i":52,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"reload [in <i>hh:mm</i>] [cancel]","synPlain":"reload [in hh:mm] [cancel]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعيد تشغيل الجهاز. إن لم تحفظ، سيسألك عن الحفظ — وهذا هو التحذير الأخير. <code>reload in 10</code> يعيد التشغيل بعد 10 دقائق (مفيد كشبكة أمان أثناء إعداد عن بُعد)، و<code>reload cancel</code> يلغي المؤقّت.","en":"Reboots the device, optionally scheduled; cancel aborts a pending reload.","ex":"<pre><span class=\"p\">R1#</span> reload in 10\nReload scheduled in 10 minutes\n<span class=\"p\">R1#</span> reload cancel</pre>","exPlain":"R1# reload in 10\nReload scheduled in 10 minutes\nR1# reload cancel","neg":"reload cancel","kind":"cmd"},{"i":53,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"show flash: | dir flash:","synPlain":"show flash: | dir flash:","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض محتوى الفلاش: صور IOS، ملفات الإعداد الاحتياطية، الـ vlan.dat. <code>dir</code> يعرض المساحة الحرة أيضاً، و<code>show flash:</code> يعرض ملخصاً بالمساحة المستخدمة.","en":"Lists the IOS images and files stored in flash with their sizes and free space.","ex":"<pre><span class=\"p\">R1#</span> dir flash:\nDirectory of flash:/\n    1  -rw-  68839252   c2900-universalk9-mz.SPA.157-3.M.bin\n  2  -rw-      1024   vlan.dat\n  3  -rw-      3072   private-config.text\n63832064 bytes available (68843520 bytes used)</pre>","exPlain":"R1# dir flash:\nDirectory of flash:/\n    1  -rw-  68839252   c2900-universalk9-mz.SPA.157-3.M.bin\n  2  -rw-      1024   vlan.dat\n  3  -rw-      3072   private-config.text\n63832064 bytes available (68843520 bytes used)","neg":"","kind":"cmd"},{"i":54,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"delete <i>flash:filename</i>","synPlain":"delete flash:filename","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يحذف ملفاً من الفلاش. على السويتشات القديمة يُستخدم <code>delete vlan.dat</code> لإعادة ضبط قاعدة VLAN كاملة — خطوة لازمة عند إعادة تهيئة سويتش مستعمل.","en":"Deletes a file from flash (some platforms need squeeze afterwards to reclaim the space).","ex":"<pre><span class=\"p\">SW1#</span> delete vlan.dat\nDelete filename [vlan.dat]? <span class=\"p\">[Enter]</span>\nDelete flash:vlan.dat? [confirm] <span class=\"p\">[Enter]</span></pre>","exPlain":"SW1# delete vlan.dat\nDelete filename [vlan.dat]? [Enter]\nDelete flash:vlan.dat? [confirm] [Enter]","neg":"تحذير الحذف نهائي — لا يوجد Recycle Bin في IOS","kind":"cmd"},{"i":55,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"copy <i>source</i> <i>destination</i>","synPlain":"copy source destination","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"الأمر العام لنقل الملفات بين أي وسيطين: <code>flash:</code>، <code>nvram:</code>، <code>running-config</code>، <code>startup-config</code>، <code>tftp:</code>، <code>ftp:</code>، <code>usbflash0:</code>. صيغة TFTP تطلب عنوان الخادم واسم الملف.","en":"Generic file transfer between flash, NVRAM, TFTP, FTP, SCP, and USB.","ex":"<pre><span class=\"p\">R1#</span> copy running-config tftp:\nAddress or name of remote host []? 10.1.1.100\nDestination filename [r1-confg]? R1-backup.cfg\n!! 2103 bytes copied in 0.9 secs\n<span class=\"p\">R1#</span> copy tftp: running-config</pre>","exPlain":"R1# copy running-config tftp:\nAddress or name of remote host []? 10.1.1.100\nDestination filename [r1-confg]? R1-backup.cfg\n!! 2103 bytes copied in 0.9 secs\nR1# copy tftp: running-config","neg":"","kind":"cmd"},{"i":56,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"boot system flash:<i>image</i>","synPlain":"boot system flash:image","mode":"Global Config","modeCls":"m-gconf","ar":"يحدد صورة IOS التي يُقلع منها الجهاز عندما توجد أكثر من صورة في الفلاش. بدون هذا الأمر، يقلع الجهاز من أول صورة صالحة يجدها — وقد تكون نسخة قديمة. تحقق بـ <code>show boot</code>.","en":"Pins the exact IOS image to load, overriding the first-image-in-flash default.","ex":"<pre><span class=\"p\">R1(config)#</span> boot system flash:c2900-universalk9-mz.SPA.157-3.M.bin\n<span class=\"p\">R1#</span> show boot</pre>","exPlain":"R1(config)# boot system flash:c2900-universalk9-mz.SPA.157-3.M.bin\nR1# show boot","neg":"no boot system","kind":"cmd"},{"i":57,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"config-register <i>0xNNNN</i>","synPlain":"config-register 0xNNNN","mode":"Global Config","modeCls":"m-gconf","ar":"يتحكم في سلوك الإقلاع عبر قيمة سداسية عشرية. القيم التي يجب حفظها:","en":"Sets the boot behaviour bitmask; 0x2102 is normal, 0x2142 ignores startup-config.","ex":"<pre><span class=\"p\">R1(config)#</span> config-register 0x2102\n<span class=\"p\">R1#</span> show version | include register\nConfiguration register is 0x2102</pre>","exPlain":"R1(config)# config-register 0x2102\nR1# show version | include register\nConfiguration register is 0x2102","neg":"0x2102","kind":"cmd"},{"i":58,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"show license | show license feature","synPlain":"show license | show license feature","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض حالة الترخيص على منصات IOS-XE (ISR 4K، Catalyst 9K). المستويات: <b>ipbase</b> → <b>appxk9</b> (تطبيقات) → <b>securityk9</b> (VPN/جدار ناري) → <b>uck9</b> (تعاون). الميزات المتقدمة لا تعمل بدون ترخيص صالح.","en":"Shows the installed technology package and the feature set it unlocks.","ex":"<pre><span class=\"p\">R1#</span> show license\nIndex 1 Feature: ipbasek9   Period left: Life time\nIndex 2 Feature: securityk9 Period left: 8 weeks 0 day</pre>","exPlain":"R1# show license\nIndex 1 Feature: ipbasek9   Period left: Life time\nIndex 2 Feature: securityk9 Period left: 8 weeks 0 day","neg":"","kind":"cmd"},{"i":59,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"license boot level <i>level</i>","synPlain":"license boot level level","mode":"Global Config","modeCls":"m-gconf","ar":"يغيّر مستوى الترخيص (يتطلب إعادة تشغيل). على سويتشات Catalyst 2960/3560 القديمة كان يُستخدم <code>license boot module c2960s universalk9</code>، وعلى 9K يُدار عبر Smart Licensing.","en":"Selects the licence level (ipbase, ipservices, adventerprise) applied at the next reload.","ex":"<pre><span class=\"p\">R1(config)#</span> license boot level securityk9\n<span class=\"p\">R1(config)#</span> end\n<span class=\"p\">R1#</span> reload</pre>","exPlain":"R1(config)# license boot level securityk9\nR1(config)# end\nR1# reload","neg":"no license boot level","kind":"cmd"},{"i":60,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"show file systems","synPlain":"show file systems","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يسرد كل أنظمة الملفات المتاحة وأحجامها وحريتها مع رموزها (<code>*</code> = الافتراضي، <code>#</code> = للقراءة فقط). أول أمر تكتبه عند محاولة نسخ صورة IOS وحصولك على خطأ مسار.","en":"Lists every mounted file system with its size, free space, and read/write flags.","ex":"<pre><span class=\"p\">R1#</span> show file systems\nFile Systems:\n     Size(b)  Free(b)  Type  Flags  Prefixes\n*  68843520  63832064  disk  rw     flash:  # 262136  200000  nvram rw     nvram:</pre>","exPlain":"R1# show file systems\nFile Systems:\n     Size(b)  Free(b)  Type  Flags  Prefixes\n*  68843520  63832064  disk  rw     flash:  # 262136  200000  nvram rw     nvram:","neg":"","kind":"cmd"},{"i":61,"sec":"files","no":"03","secAr":"الملفات والنسخ الاحتياطي","secEn":"Files & Backup","grp":"basics","syn":"archive | configure replace <i>file</i>","synPlain":"archive | configure replace file","mode":"Global Config","modeCls":"m-gconf","ar":"ميزة أرشفة تلقائية للإعدادات كل فترة أو عند كل حفظ، مع إمكانية الرجوع لنسخة سابقة بالكامل. <code>configure replace</code> يستبدل الإعداد الحالي بالملف المحدد (بديل صحيح لـ <code>copy startup run</code>) ويستطيع التراجع بـ <code>configure revert</code>.","en":"Creates configuration snapshots and restores them atomically, replacing the whole running-config.","ex":"<pre><span class=\"p\">R1(config)#</span> archive\n<span class=\"p\">R1(config-archive)#</span> path flash:backup\n<span class=\"p\">R1(config-archive)#</span> maximum 5\n<span class=\"p\">R1(config-archive)#</span> time-period 1440\n<span class=\"p\">R1#</span> configure replace flash:backup/r1.cfg</pre>","exPlain":"R1(config)# archive\nR1(config-archive)# path flash:backup\nR1(config-archive)# maximum 5\nR1(config-archive)# time-period 1440\nR1# configure replace flash:backup/r1.cfg","neg":"no archive","kind":"cmd"},{"i":62,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"interface <i>type</i> <i>number</i>","synPlain":"interface type number","mode":"Global Config","modeCls":"m-gconf","ar":"يدخلك إلى وضع إعداد واجهة محددة. الأنواع: <code>GigabitEthernet</code> (g)، <code>FastEthernet</code> (f)، <code>Serial</code> (s)، <code>Loopback</code> (lo)، <code>Vlan</code>، <code>Port-channel</code>، <code>Tunnel</code>. الترقيم يختلف: الراوترات <code>g0/0</code> أو <code>g0/0/0</code>، والسويتشات <code>g0/1</code> أو <code>g1/0/1</code>.","en":"Enters Interface Configuration for the named port (GigabitEthernet0/1, Serial0/0/0, ...).","ex":"<pre><span class=\"p\">R1(config)#</span> interface gigabitEthernet 0/0\n<span class=\"p\">R1(config-if)#</span>\n<span class=\"p\">R1(config)#</span> interface range g0/1 - 12 , g0/20</pre>","exPlain":"R1(config)# interface gigabitEthernet 0/0\nR1(config-if)#\nR1(config)# interface range g0/1 - 12 , g0/20","neg":"no interface g0/0","kind":"cmd"},{"i":63,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ip address <i>ip-address</i> <i>subnet-mask</i>","synPlain":"ip address ip-address subnet-mask","mode":"Interface Config","modeCls":"m-iconf","ar":"يعيّن عنوان IPv4 وقناع الشبكة (بصيغة dotted decimal، وليس CIDR — الأمر <code>ip address 10.1.1.1 255.255.255.0</code> وليس <code>/24</code>). الواجهة لا تصبح فعّالة إلا مع <code>no shutdown</code>. يمكن إضافة عنوان ثانوي بـ <code>secondary</code> على نفس الواجهة.","en":"Assigns a static IPv4 address and subnet mask to an interface.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip address 10.1.1.1 255.255.255.0\n<span class=\"p\">R1(config-if)#</span> ip address 10.1.2.1 255.255.255.0 secondary\n<span class=\"p\">R1(config-if)#</span> no shutdown</pre>","exPlain":"R1(config-if)# ip address 10.1.1.1 255.255.255.0\nR1(config-if)# ip address 10.1.2.1 255.255.255.0 secondary\nR1(config-if)# no shutdown","neg":"no ip address","kind":"cmd"},{"i":64,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ip address dhcp","synPlain":"ip address dhcp","mode":"Interface Config","modeCls":"m-iconf","ar":"يجعل الواجهة عميل DHCP تحصل على عنوانها تلقائياً — وهو الحال الطبيعي لواجهة WAN متصلة بمودم مزوّد الخدمة. تحقق بـ <code>show dhcp lease</code>.","en":"Makes the interface a DHCP client for its IPv4 address.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip address dhcp\n<span class=\"p\">R1(config-if)#</span> no shutdown\n<span class=\"p\">R1#</span> show dhcp lease</pre>","exPlain":"R1(config-if)# ip address dhcp\nR1(config-if)# no shutdown\nR1# show dhcp lease","neg":"no ip address dhcp","kind":"cmd"},{"i":65,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"shutdown | no shutdown","synPlain":"shutdown | no shutdown","mode":"Interface Config","modeCls":"m-iconf","ar":"يفتح أو يغلق الواجهة إدارياً. الواجهات على الراوترات تبدأ <code>administratively down</code> افتراضياً، بينما منافذ السويتش تبدأ مفتوحة. هذا الفرق هو سبب 90% من حالات «الواجهة لا تعمل» عند المبتدئين.","en":"Administratively disables (shutdown) or enables (no shutdown) the interface.","ex":"<pre><span class=\"p\">R1(config-if)#</span> shutdown\n<span class=\"p\">R1(config-if)#</span> no shutdown\n<span class=\"p\">R1#</span> show ip int brief\nGi0/0   10.1.1.1   YES manual up   up</pre>","exPlain":"R1(config-if)# shutdown\nR1(config-if)# no shutdown\nR1# show ip int brief\nGi0/0   10.1.1.1   YES manual up   up","neg":"no shutdown","kind":"cmd"},{"i":66,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"description <i>text</i>","synPlain":"description text","mode":"Interface Config","modeCls":"m-iconf","ar":"تعليق وصفي يظهر في <code>show interfaces</code> و<code>show interfaces description</code>. عادة مهنية لا تُقدَّر بثمن: اكتب الجهة المقابلة والدور (<code>Link-to-ISP-Core</code>). في الامتحان العملي تساعدك على عدم الخلط بين الواجهات.","en":"Attaches a free-text label shown in show run and show interfaces.","ex":"<pre><span class=\"p\">R1(config-if)#</span> description Uplink to SW1 Gi0/24 | VLAN 10\n<span class=\"p\">R1#</span> show interfaces description</pre>","exPlain":"R1(config-if)# description Uplink to SW1 Gi0/24 | VLAN 10\nR1# show interfaces description","neg":"no description","kind":"cmd"},{"i":67,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"speed <i>{10|100|1000|auto}</i> | duplex <i>{full|half|auto}</i>","synPlain":"speed {10|100|1000|auto} | duplex {full|half|auto}","mode":"Interface Config","modeCls":"m-iconf","ar":"يثبّت السرعة والـ duplex بدلاً من التفاوض التلقائي. القاعدة الذهبية: <b>إما auto على الطرفين، أو مثبّت على الطرفين</b>. خلط auto مع مثبّت يؤدي إلى <b>Duplex Mismatch</b> — رابط يعمل لكن بأخطاء collision وتأخير عالٍ. لا تُثبّت السرعة على منفذ Gigabit (المعيار يفرض auto).","en":"Hard-codes or negotiates link speed and duplex; a mismatch is the classic cause of late collisions.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> speed 100\n<span class=\"p\">SW1(config-if)#</span> duplex full\n<span class=\"p\">SW1#</span> show interfaces g0/1 | include duplex|collision</pre>","exPlain":"SW1(config-if)# speed 100\nSW1(config-if)# duplex full\nSW1# show interfaces g0/1 | include duplex|collision","neg":"no speed","kind":"cmd"},{"i":68,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"bandwidth <i>kbps</i> | delay <i>tens-of-microseconds</i>","synPlain":"bandwidth kbps | delay tens-of-microseconds","mode":"Interface Config","modeCls":"m-iconf","ar":"<b>لا يغيّر السرعة الفيزيائية!</b> يضبط القيمة المنطقية التي تستخدمها بروتوكولات التوجيه في حساب الـ metric (OSPF يستخدم bandwidth، وEIGRP يستخدم bandwidth وdelay). على منفذ Serial بسرعة 1544 kbps القيمة الافتراضية 1544؛ لتوحيد حساب OSPF عبر روابط مختلفة السرعة يجب ضبط bandwidth بشكل صحيح.","en":"Sets logical values used only by routing metrics (bandwidth) and EIGRP (delay), not real throughput.","ex":"<pre><span class=\"p\">R1(config-if)#</span> bandwidth 10000\n<span class=\"p\">R1(config-if)#</span> delay 100\n<span class=\"p\">R1#</span> show interfaces s0/0/0 | include BW|DLY</pre>","exPlain":"R1(config-if)# bandwidth 10000\nR1(config-if)# delay 100\nR1# show interfaces s0/0/0 | include BW|DLY","neg":"no bandwidth","kind":"cmd"},{"i":69,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"mtu <i>bytes</i> | ip mtu <i>bytes</i>","synPlain":"mtu bytes | ip mtu bytes","mode":"Interface Config","modeCls":"m-iconf","ar":"<code>mtu</code> يضبط أقصى حجم إطار للطبقة الثانية، و<code>ip mtu</code> يضبط أقصى حجم حزمة IP (وهو الذي يؤثر على التجزئة). الافتراضي 1500. تقليله مفيد في الأنفاق (Tunnels) أو عند مشاكل PMTUD.","en":"Sets the Layer 2 or Layer 3 maximum transmission unit; mismatches break OSPF adjacency and tunnels.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip mtu 1400\n<span class=\"p\">R1#</span> show interfaces g0/0 | include MTU</pre>","exPlain":"R1(config-if)# ip mtu 1400\nR1# show interfaces g0/0 | include MTU","neg":"no ip mtu","kind":"cmd"},{"i":70,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"interface loopback <i>number</i>","synPlain":"interface loopback number","mode":"Global Config","modeCls":"m-gconf","ar":"واجهة افتراضية منطقية تبقى <code>up/up</code> دائماً ما دام الجهاز يعمل. تُستخدم كـ <b>Router-ID</b> لبروتوكولات التوجيه، وكعنوان إدارة مستقر، وكعنوان مصدر لجلسات BGP. ميزتها الكبرى: لا تنهار إذا سقط رابط فيزيائي.","en":"Creates a virtual always-up interface, ideal for router-ids, management access, and BGP peering.","ex":"<pre><span class=\"p\">R1(config)#</span> interface loopback 0\n<span class=\"p\">R1(config-if)#</span> ip address 1.1.1.1 255.255.255.255\n<span class=\"p\">R1(config-if)#</span> description Router-ID</pre>","exPlain":"R1(config)# interface loopback 0\nR1(config-if)# ip address 1.1.1.1 255.255.255.255\nR1(config-if)# description Router-ID","neg":"no interface loopback 0","kind":"cmd"},{"i":71,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ip routing","synPlain":"ip routing","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"يفعّل وظيفة التوجيه داخل سويتش متعدد الطبقات. <b>بدونه</b> يمكنك إنشاء SVIs وعناوين IP لكن السويتش لن يوجّه أي حزمة بينها — وهذا أشهر خطأ في معامل Inter-VLAN Routing على سويتشات 3560/3650/9300.","en":"Enables IPv4 routing on a multilayer switch, where it is off by default.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip routing\n<span class=\"p\">SW1#</span> show ip route\nCodes: C - connected, S - static\nC    10.1.1.0/24 is directly connected, Vlan10</pre>","exPlain":"SW1(config)# ip routing\nSW1# show ip route\nCodes: C - connected, S - static\nC    10.1.1.0/24 is directly connected, Vlan10","neg":"no ip routing","kind":"cmd"},{"i":72,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"no switchport","synPlain":"no switchport","mode":"Interface Config (Switch)","modeCls":"m-iconf","ar":"يحوّل منفذ السويتش من Layer 2 إلى <b>Routed Port</b> في الطبقة الثالثة، فيصبح قابلاً لاستقبال <code>ip address</code> مباشرة. يُستخدم في روابط OSPF/EIGRP بين سويتشات الطبقة الثالثة (Point-to-Point routed links) بدلاً من SVIs. للعودة: <code>switchport</code>.","en":"Converts a switch port into a routed Layer 3 port.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface g1/0/24\n<span class=\"p\">SW1(config-if)#</span> no switchport\n<span class=\"p\">SW1(config-if)#</span> ip address 10.0.0.1 255.255.255.252\n<span class=\"p\">SW1(config-if)#</span> no shutdown</pre>","exPlain":"SW1(config)# interface g1/0/24\nSW1(config-if)# no switchport\nSW1(config-if)# ip address 10.0.0.1 255.255.255.252\nSW1(config-if)# no shutdown","neg":"switchport","kind":"cmd"},{"i":73,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"interface vlan <i>id</i>","synPlain":"interface vlan id","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"ينشئ واجهة SVI (Switch Virtual Interface) — واجهة منطقية مرتبطة بـ VLAN. تُستخدم كـ <b>Default Gateway</b> لأجهزة الـ VLAN، أو كعنوان إدارة للسويتش. تبقى <code>down</code> حتى يوجد منفذ واحد على الأقل في ذلك الـ VLAN بحالة up (أو منفذ trunk يسمح به).","en":"Creates the switched virtual interface (SVI) that provides Layer 3 for a VLAN.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface vlan 10\n<span class=\"p\">SW1(config-if)#</span> ip address 192.168.10.1 255.255.255.0\n<span class=\"p\">SW1(config-if)#</span> no shutdown</pre>","exPlain":"SW1(config)# interface vlan 10\nSW1(config-if)# ip address 192.168.10.1 255.255.255.0\nSW1(config-if)# no shutdown","neg":"no interface vlan 10","kind":"cmd"},{"i":74,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ip default-gateway <i>ip</i>","synPlain":"ip default-gateway ip","mode":"Global Config (L2 Switch)","modeCls":"m-gconf","ar":"يحدد البوابة الافتراضية لسويتش طبقة ثانية (غير قادر على التوجيه). يُستخدم فقط للإدارة عن بُعد من شبكة أخرى. <b>لا تستخدمه على سويتش Layer 3</b> — هناك تستخدم <code>ip route 0.0.0.0 0.0.0.0</code>.","en":"Sets the default gateway on a Layer 2 switch that has no routing enabled.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip default-gateway 192.168.10.1</pre>","exPlain":"SW1(config)# ip default-gateway 192.168.10.1","neg":"no ip default-gateway","kind":"cmd"},{"i":75,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ipv6 unicast-routing","synPlain":"ipv6 unicast-routing","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل التوجيه لبروتوكول IPv6 على الجهاز. بدونه يمكن للراوتر أن يحمل عنوان IPv6 لكنه لن يوجّه حزم IPv6 ولن يرسل Router Advertisements — وبالتالي لن تحصل الأجهزة على عناوين SLAAC.","en":"Enables IPv6 routing and Router Advertisement generation; without it the device is an IPv6 host only.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 unicast-routing\n<span class=\"p\">R1(config)#</span> ipv6 cef</pre>","exPlain":"R1(config)# ipv6 unicast-routing\nR1(config)# ipv6 cef","neg":"no ipv6 unicast-routing","kind":"cmd"},{"i":76,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ipv6 address <i>prefix/len</i> [eui-64]","synPlain":"ipv6 address prefix/len [eui-64]","mode":"Interface Config","modeCls":"m-iconf","ar":"يعيّن عنوان IPv6 كاملاً أو بادئة مع <code>eui-64</code> لاستكمال 64 بت الأخيرة من MAC الواجهة. لتوليد link-local تلقائياً يكفي <code>ipv6 enable</code>. ملاحظة: يمكن أن تحمل الواجهة عدة عناوين IPv6 في الوقت نفسه (وهذا طبيعي في IPv6).","en":"Assigns an IPv6 address, optionally deriving the interface ID from the MAC address with EUI-64.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 address 2001:db8:10::1/64\n<span class=\"p\">R1(config-if)#</span> ipv6 address 2001:db8:10::/64 eui-64\n<span class=\"p\">R1(config-if)#</span> ipv6 enable</pre>","exPlain":"R1(config-if)# ipv6 address 2001:db8:10::1/64\nR1(config-if)# ipv6 address 2001:db8:10::/64 eui-64\nR1(config-if)# ipv6 enable","neg":"no ipv6 address 2001:db8:10::1/64","kind":"cmd"},{"i":77,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ipv6 address autoconfig | ipv6 address dhcp","synPlain":"ipv6 address autoconfig | ipv6 address dhcp","mode":"Interface Config","modeCls":"m-iconf","ar":"<code>autoconfig</code> يبني عنواناً بطريقة SLAAC اعتماداً على Router Advertisement، و<code>dhcp</code> يطلب عنواناً من خادم DHCPv6 (Stateful). الفرق بينهما سؤال متكرر في منهج CCNA.","en":"Builds the address from SLAAC Router Advertisements, or requests one from DHCPv6.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 address autoconfig default\n<span class=\"p\">R1(config-if)#</span> ipv6 address dhcp</pre>","exPlain":"R1(config-if)# ipv6 address autoconfig default\nR1(config-if)# ipv6 address dhcp","neg":"no ipv6 address autoconfig","kind":"cmd"},{"i":78,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"ipv6 nd ra suppress","synPlain":"ipv6 nd ra suppress","mode":"Interface Config","modeCls":"m-iconf","ar":"يمنع إرسال Router Advertisements على الواجهة. يُستخدم على الواجهات المتجهة نحو مزوّد الخدمة أو نحو أجهزة لا يجب أن تتعلّم منها مساراً افتراضياً.","en":"Stops sending Router Advertisements out of the interface, typical on WAN and uplink ports.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 nd ra suppress all</pre>","exPlain":"R1(config-if)# ipv6 nd ra suppress all","neg":"no ipv6 nd ra suppress","kind":"cmd"},{"i":79,"sec":"intf","no":"04","secAr":"الواجهات وعناوين IP","secEn":"Interfaces & IP","grp":"basics","syn":"interface range <i>type</i> <i>start</i> - <i>end</i> [, <i>type</i> <i>n</i>]","synPlain":"interface range type start - end [, type n]","mode":"Global Config","modeCls":"m-glob","ar":"يفتح عدة واجهات دفعة واحدة فتُطبَّق الأوامر التالية عليها كلها. المسافات حول الشرطة <b>إلزامية</b>، وتُفصل المداخل المختلفة بفاصلة. يوفر وقتاً هائلاً في المعمل ويقلل الأخطاء، لكن احذر: أمر خاطئ واحد يُطبَّق على كل المنافذ في المدى.","en":"Opens several interfaces at once so the following commands apply to all of them. Spaces around the hyphen are required; separate non-contiguous ranges with commas.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface range GigabitEthernet0/1 - 12\n<span class=\"p\">SW1(config-if-range)#</span> switchport mode access\n<span class=\"p\">SW1(config-if-range)#</span> switchport access vlan 10\n<span class=\"p\">SW1(config-if-range)#</span> spanning-tree portfast\n<span class=\"p\">SW1(config)#</span> interface range Gi0/1 - 4, Gi0/7, Gi0/9 - 12</pre>","exPlain":"SW1(config)# interface range GigabitEthernet0/1 - 12\nSW1(config-if-range)# switchport mode access\nSW1(config-if-range)# switchport access vlan 10\nSW1(config-if-range)# spanning-tree portfast\nSW1(config)# interface range Gi0/1 - 4, Gi0/7, Gi0/9 - 12","neg":"","kind":"cmd"},{"i":80,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"vlan <i>vlan-id</i>","synPlain":"vlan vlan-id","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"ينشئ VLAN ويُدخلك إلى وضع إعدادها. المدى الطبيعي <b><span class=\"num\">1–1005</span></b> (منها <span class=\"num\">1002–1005</span> افتراضية لـ Token Ring/FDDI ولا تُستخدم)، والمدى الموسّع <b><span class=\"num\">1006–4094</span></b>. الـ VLAN 1 افتراضي ولا يمكن حذفه. الـ VLANs <span class=\"num\">1002–1005</span> لا تُحذف أيضاً.","en":"Creates a VLAN and enters VLAN Configuration so it can be named.","ex":"<pre><span class=\"p\">SW1(config)#</span> vlan 10\n<span class=\"p\">SW1(config-vlan)#</span> name SALES\n<span class=\"p\">SW1(config-vlan)#</span> state active\n<span class=\"p\">SW1(config)#</span> vlan 20,30\n<span class=\"p\">SW1(config-vlan)#</span> name ENG</pre>","exPlain":"SW1(config)# vlan 10\nSW1(config-vlan)# name SALES\nSW1(config-vlan)# state active\nSW1(config)# vlan 20,30\nSW1(config-vlan)# name ENG","neg":"no vlan 10","kind":"cmd"},{"i":81,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"name <i>vlan-name</i>","synPlain":"name vlan-name","mode":"VLAN Config","modeCls":"m-vlan","ar":"اسم وصفي للـ VLAN (حتى 32 حرفاً). الاسم محلي ولا يُنقل عبر VTP بشكل موثوق بين إصدارات مختلفة، لكنه مهم للتوثيق وللقراءة السريعة في <code>show vlan brief</code>.","en":"Assigns a descriptive name to the VLAN.","ex":"<pre><span class=\"p\">SW1(config-vlan)#</span> name SALES\n<span class=\"p\">SW1#</span> show vlan brief\n10   SALES   active    Gi0/1, Gi0/2</pre>","exPlain":"SW1(config-vlan)# name SALES\nSW1# show vlan brief\n10   SALES   active    Gi0/1, Gi0/2","neg":"no name","kind":"cmd"},{"i":82,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport mode access","synPlain":"switchport mode access","mode":"Interface Config","modeCls":"m-iconf","ar":"يجبر المنفذ على العمل كمنفذ وصول (Access) ينتمي إلى VLAN واحد، ويوقف تفاوض DTP. أي جهاز طرفي (PC، طابعة، كاميرا، نقطة وصول) يجب أن يكون منفذه Access. أمر أمني وإداري في الوقت نفسه.","en":"Forces the port into untagged single-VLAN access mode.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface g0/1\n<span class=\"p\">SW1(config-if)#</span> switchport mode access\n<span class=\"p\">SW1(config-if)#</span> switchport access vlan 10</pre>","exPlain":"SW1(config)# interface g0/1\nSW1(config-if)# switchport mode access\nSW1(config-if)# switchport access vlan 10","neg":"no switchport mode","kind":"cmd"},{"i":83,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport access vlan <i>vlan-id</i>","synPlain":"switchport access vlan vlan-id","mode":"Interface Config","modeCls":"m-iconf","ar":"يضع المنفذ داخل VLAN محدد. إن لم يكن الـ VLAN موجوداً، ينشئه السويتش تلقائياً في بعض الإصدارات (سلوك يُربك المبتدئ). تحقق دائماً بـ <code>show vlan brief</code>.","en":"Sets which VLAN the access port belongs to.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport access vlan 20\n<span class=\"p\">SW1#</span> show vlan id 20</pre>","exPlain":"SW1(config-if)# switchport access vlan 20\nSW1# show vlan id 20","neg":"no switchport access vlan","kind":"cmd"},{"i":84,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport host","synPlain":"switchport host","mode":"Interface Config","modeCls":"m-iconf","ar":"ماكرو يجمع ثلاثة أوامر بضربة واحدة: <code>switchport mode access</code> + <code>spanning-tree portfast</code> + <code>spanning-tree bpduguard enable</code>. أسرع طريقة لتأمين منفذ طرفي في المعمل وفي الإنتاج.","en":"One-shot macro: access mode, PortFast enabled, and EtherChannel negotiation disabled.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport host\nswitchport mode will be set to access\nspanning-tree portfast will be enabled\nspanning-tree bpduguard will be enabled</pre>","exPlain":"SW1(config-if)# switchport host\nswitchport mode will be set to access\nspanning-tree portfast will be enabled\nspanning-tree bpduguard will be enabled","neg":"no switchport host","kind":"cmd"},{"i":85,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport trunk encapsulation dot1q","synPlain":"switchport trunk encapsulation dot1q","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد طريقة الوسم على الرابط كـ <b>802.1Q</b> (المعيار المفتوح، وهو الوحيد المدعوم عالمياً). بعض السويتشات القديمة تدعم <code>isl</code> أيضاً، والسويتشات الحديثة لا تدعم إلا dot1q فتُهمل هذا الأمر. <b>يجب كتابته قبل</b> <code>switchport mode trunk</code> على السويتشات التي تدعم الاثنين.","en":"Selects 802.1Q as the trunk encapsulation (required on older switches before mode trunk).","ex":"<pre><span class=\"p\">SW1(config)#</span> interface g0/24\n<span class=\"p\">SW1(config-if)#</span> switchport trunk encapsulation dot1q\n<span class=\"p\">SW1(config-if)#</span> switchport mode trunk</pre>","exPlain":"SW1(config)# interface g0/24\nSW1(config-if)# switchport trunk encapsulation dot1q\nSW1(config-if)# switchport mode trunk","neg":"no switchport trunk encapsulation","kind":"cmd"},{"i":86,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport mode trunk","synPlain":"switchport mode trunk","mode":"Interface Config","modeCls":"m-iconf","ar":"يفرض وضع Trunk بشكل دائم (لا تفاوض). يُستخدم بين السويتشات وبين السويتش والراوتر (Router-on-a-Stick). الطرف المقابل يجب أن يكون trunk أيضاً (أو dynamic desirable/auto).","en":"Forces the port to trunk, carrying multiple VLANs with 802.1Q tags.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport mode trunk\n<span class=\"p\">SW1#</span> show interfaces trunk\nPort    Mode  Encapsulation Status  Native vlan\nGi0/24  on    802.1q        trunking 1</pre>","exPlain":"SW1(config-if)# switchport mode trunk\nSW1# show interfaces trunk\nPort    Mode  Encapsulation Status  Native vlan\nGi0/24  on    802.1q        trunking 1","neg":"no switchport mode","kind":"cmd"},{"i":87,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport trunk allowed vlan <i>list</i> | add | remove | except | all | none","synPlain":"switchport trunk allowed vlan list | add | remove | except | all | none","mode":"Interface Config","modeCls":"m-iconf","ar":"يتحكم في أي VLANs يُسمح بمرورها على الـ Trunk. الافتراضي هو <code>all</code> (<span class=\"num\">1–4094</span>). <b>تحذير عملي:</b> كتابة الأمر بدون <code>add</code> تستبدل القائمة بالكامل — لذلك نستخدم <code>add</code> و<code>remove</code> دائماً بعد الإعداد الأولي.","en":"Restricts the VLANs carried on the trunk; the plain list replaces, add and remove edit incrementally.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport trunk allowed vlan 10,20,30\n<span class=\"p\">SW1(config-if)#</span> switchport trunk allowed vlan add 40\n<span class=\"p\">SW1(config-if)#</span> switchport trunk allowed vlan remove 30\n<span class=\"p\">SW1(config-if)#</span> switchport trunk allowed vlan except 1-9</pre>","exPlain":"SW1(config-if)# switchport trunk allowed vlan 10,20,30\nSW1(config-if)# switchport trunk allowed vlan add 40\nSW1(config-if)# switchport trunk allowed vlan remove 30\nSW1(config-if)# switchport trunk allowed vlan except 1-9","neg":"no switchport trunk allowed vlan","kind":"cmd"},{"i":88,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport trunk native vlan <i>vlan-id</i>","synPlain":"switchport trunk native vlan vlan-id","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد الـ VLAN الذي يمر <b>بدون وسم</b> على الرابط. الافتراضي VLAN 1. يجب أن يتطابق على طرفي الـ Trunk وإلا ظهرت رسالة <code>%CDP-4-NATIVE_VLAN_MISMATCH</code> ولن يمر الترافيك غير الموسوم. أفضل ممارسة أمنية: تغييره إلى VLAN غير مستخدم (مثل 999).","en":"Sets the untagged VLAN on the trunk; it must match on both ends.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport trunk native vlan 999\n<span class=\"p\">SW1#</span> show interfaces trunk | include Native</pre>","exPlain":"SW1(config-if)# switchport trunk native vlan 999\nSW1# show interfaces trunk | include Native","neg":"no switchport trunk native vlan","kind":"cmd"},{"i":89,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport nonegotiate","synPlain":"switchport nonegotiate","mode":"Interface Config","modeCls":"m-iconf","ar":"يوقف إرسال إطارات DTP على المنفذ. إجراء أمني يمنع أي جهاز من محاولة التفاوض على trunk، ويُطبّق عادة على منافذ الوصول وعلى روابط الـ Trunk المُعدّة يدوياً.","en":"Stops DTP frames from being sent, closing the VLAN-hopping door.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport nonegotiate\n<span class=\"p\">SW1#</span> show dtp interface g0/24</pre>","exPlain":"SW1(config-if)# switchport nonegotiate\nSW1# show dtp interface g0/24","neg":"switchport negotiate","kind":"cmd"},{"i":90,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport voice vlan <i>vlan-id</i>","synPlain":"switchport voice vlan vlan-id","mode":"Interface Config","modeCls":"m-iconf","ar":"يُعدّ المنفذ لدعم هاتف IP مع تمرير ترافيك الصوت في VLAN منفصل عن بيانات الحاسوب المتصل بالهاتف. المنفذ يبقى Access للبيانات ويحمل Voice VLAN إضافية عبر CDP/LLDP. ميزة أساسية في شبكات المؤسسات.","en":"Puts an IP phone in a separate voice VLAN while the attached PC stays in the data VLAN.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport mode access\n<span class=\"p\">SW1(config-if)#</span> switchport access vlan 10\n<span class=\"p\">SW1(config-if)#</span> switchport voice vlan 150\n<span class=\"p\">SW1(config-if)#</span> mls qos trust cos</pre>","exPlain":"SW1(config-if)# switchport mode access\nSW1(config-if)# switchport access vlan 10\nSW1(config-if)# switchport voice vlan 150\nSW1(config-if)# mls qos trust cos","neg":"no switchport voice vlan","kind":"cmd"},{"i":91,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"switchport trunk pruning vlan <i>list</i>","synPlain":"switchport trunk pruning vlan list","mode":"Interface Config","modeCls":"m-iconf","ar":"يمنع بث ترافيك VLANs غير المستخدمة عبر الـ Trunk (VLAN Pruning) لتوفير النطاق. يعمل تلقائياً مع VTP، أو يدوياً بهذا الأمر. في الشبكات الحديثة يُفضّل التحكم بـ <code>allowed vlan</code> بدلاً منه لأنه أوضح.","en":"Enables VTP pruning eligibility for the listed VLANs on this trunk.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport trunk pruning vlan 10,20</pre>","exPlain":"SW1(config-if)# switchport trunk pruning vlan 10,20","neg":"no switchport trunk pruning vlan","kind":"cmd"},{"i":92,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"vtp mode <i>{server|client|transparent|off}</i>","synPlain":"vtp mode {server|client|transparent|off}","mode":"Global Config","modeCls":"m-gconf","ar":"يحدد دور الجهاز في نطاق VTP. الافتراضي على معظم السويتشات هو <b>server</b> — وهذا خطر: سويتش جديد بإعداد مصنع قد يمحو قاعدة VLANs للشبكة كلها إذا كان رقم Revision أعلى. في الإنتاج يُفضّل <code>transparent</code> أو <code>off</code>.","en":"Selects the VTP role: server and client synchronise the VLAN database, transparent and off do not.","ex":"<pre><span class=\"p\">SW1(config)#</span> vtp mode server\n<span class=\"p\">SW2(config)#</span> vtp mode client\n<span class=\"p\">SW3(config)#</span> vtp mode transparent</pre>","exPlain":"SW1(config)# vtp mode server\nSW2(config)# vtp mode client\nSW3(config)# vtp mode transparent","neg":"no vtp mode","kind":"cmd"},{"i":93,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"vtp domain <i>name</i> | vtp password <i>pass</i>","synPlain":"vtp domain name | vtp password pass","mode":"Global Config","modeCls":"m-gconf","ar":"اسم النطاق يجب أن يتطابق تماماً (حساس لحالة الأحرف) على كل الأجهزة، وإلا لن تتزامن. كلمة السر تُشفّر إعلانات VTP. جهاز بلا نطاق ينتظر أول إعلان ليتبنّى النطاق تلقائياً — سلوك خطير في الشبكات الكبيرة.","en":"Sets the VTP domain name and optional MD5 password; both must match for updates to be accepted.","ex":"<pre><span class=\"p\">SW1(config)#</span> vtp domain CORP\n<span class=\"p\">SW1(config)#</span> vtp password Vtp@123\n<span class=\"p\">SW1(config)#</span> vtp version 2\n<span class=\"p\">SW1#</span> show vtp status</pre>","exPlain":"SW1(config)# vtp domain CORP\nSW1(config)# vtp password Vtp@123\nSW1(config)# vtp version 2\nSW1# show vtp status","neg":"no vtp domain","kind":"cmd"},{"i":94,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"show vtp status","synPlain":"show vtp status","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"أهم أمر في تشخيص VTP: يعرض الوضع، النطاق، رقم <b>Configuration Revision</b>، وعدد VLANs. إن لم تتزامن الأجهزة فقارن النطاق وكلمة السر ورقم الإصدار. لحلّ مشكلة تزامن مزمنة: غيّر النطاق ثم أرجعه، أو ارفع رقم الإصدار يدوياً.","en":"Shows VTP mode, domain, revision number, and VLAN count — the first check for VLAN drift.","ex":"<pre><span class=\"p\">SW1#</span> show vtp status\nVTP Version capable      : 1 to 3\nVTP Operating Mode       : Server\nVTP Domain Name          : CORP\nConfiguration Revision   : 12\nNumber of existing VLANs : 8</pre>","exPlain":"SW1# show vtp status\nVTP Version capable      : 1 to 3\nVTP Operating Mode       : Server\nVTP Domain Name          : CORP\nConfiguration Revision   : 12\nNumber of existing VLANs : 8","neg":"","kind":"cmd"},{"i":95,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"vtp pruning","synPlain":"vtp pruning","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل تقليم VLANs تلقائياً على مستوى النطاق: السويتشات لا ترسل ترافيك VLAN عبر trunk إذا لم يكن هناك منفذ نشط يستخدمه. توفير نطاق مجاني في الشبكات الكبيرة.","en":"Enables VTP pruning globally so broadcast traffic is not flooded to switches without the VLAN.","ex":"<pre><span class=\"p\">SW1(config)#</span> vtp pruning\n<span class=\"p\">SW1#</span> show vtp status | include Pruning</pre>","exPlain":"SW1(config)# vtp pruning\nSW1# show vtp status | include Pruning","neg":"no vtp pruning","kind":"cmd"},{"i":96,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"interface <i>g0/0</i>.<i>subif</i>","synPlain":"interface g0/0.subif","mode":"Global Config (Router)","modeCls":"m-gconf","ar":"ينشئ واجهة فرعية منطقية على واجهة فيزيائية واحدة، كل واحدة تمثل VLAN. الرابط الفيزيائي يجب أن يكون Trunk على السويتش. القيد: كل الترافيك يمر عبر رابط واحد (ومن هنا اسم on-a-stick) — وهو عنق زجاجة في الشبكات الكبيرة.","en":"Creates a sub-interface for Router-on-a-Stick inter-VLAN routing.","ex":"<pre><span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> no shutdown\n<span class=\"p\">R1(config)#</span> interface g0/0.10\n<span class=\"p\">R1(config-subif)#</span> encapsulation dot1Q 10\n<span class=\"p\">R1(config-subif)#</span> ip address 192.168.10.1 255.255.255.0</pre>","exPlain":"R1(config)# interface g0/0\nR1(config-if)# no shutdown\nR1(config)# interface g0/0.10\nR1(config-subif)# encapsulation dot1Q 10\nR1(config-subif)# ip address 192.168.10.1 255.255.255.0","neg":"no interface g0/0.10","kind":"cmd"},{"i":97,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"encapsulation dot1Q <i>vlan-id</i> [native]","synPlain":"encapsulation dot1Q vlan-id [native]","mode":"Sub-interface Config","modeCls":"m-iconf","ar":"يربط الواجهة الفرعية بـ VLAN ويحدد الوسم. كلمة <code>native</code> تُستخدم فقط مع الـ VLAN الأصلي (غير الموسوم) — وإن نسيتها على الـ VLAN الأصلي فلن يمر الترافيك. أمر إلزامي لكل واجهة فرعية.","en":"Binds the sub-interface to one VLAN tag, or to untagged native traffic.","ex":"<pre><span class=\"p\">R1(config-subif)#</span> encapsulation dot1Q 10\n<span class=\"p\">R1(config-subif)#</span> encapsulation dot1Q 99 native\n<span class=\"p\">R1(config-subif)#</span> ip address 192.168.99.1 255.255.255.0</pre>","exPlain":"R1(config-subif)# encapsulation dot1Q 10\nR1(config-subif)# encapsulation dot1Q 99 native\nR1(config-subif)# ip address 192.168.99.1 255.255.255.0","neg":"no encapsulation dot1Q 10","kind":"cmd"},{"i":98,"sec":"vlan","no":"05","secAr":"VLANs وTrunking","secEn":"VLANs & Trunking","grp":"switching","syn":"interface vlan <i>id</i> | ip routing","synPlain":"interface vlan id | ip routing","mode":"Global Config (L3 Switch)","modeCls":"m-gconf","ar":"الطريقة الحديثة والأسرع: كل VLAN له SVI بعنوان IP يعمل كبوابة، والتوجيه يتم داخل السويتش بسرعة الأجهزة (ASIC) بدلاً من المرور إلى راوتر خارجي. تتطلب <code>ip routing</code> وإلا لن يعمل التوجيه.","en":"The multilayer-switch alternative to Router-on-a-Stick: build SVIs and enable routing.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip routing\n<span class=\"p\">SW1(config)#</span> interface vlan 10\n<span class=\"p\">SW1(config-if)#</span> ip address 192.168.10.1 255.255.255.0\n<span class=\"p\">SW1(config)#</span> interface vlan 20\n<span class=\"p\">SW1(config-if)#</span> ip address 192.168.20.1 255.255.255.0\n<span class=\"p\">SW1#</span> show ip route connected</pre>","exPlain":"SW1(config)# ip routing\nSW1(config)# interface vlan 10\nSW1(config-if)# ip address 192.168.10.1 255.255.255.0\nSW1(config)# interface vlan 20\nSW1(config-if)# ip address 192.168.20.1 255.255.255.0\nSW1# show ip route connected","neg":"no interface vlan 10","kind":"cmd"},{"i":99,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree mode rapid-pvst","synPlain":"spanning-tree mode rapid-pvst","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل Rapid PVST+ — نسخة RSTP مع شجرة مستقلة لكل VLAN. هذا هو الوضع الموصى به في كل الشبكات الحديثة: تحوّل بالثواني بدلاً من الدقائق، مع دعم per-VLAN load balancing. تحقق بـ <code>show spanning-tree summary</code>.","en":"Switches to Rapid PVST+ (per-VLAN 802.1w), giving sub-second convergence.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree mode rapid-pvst\n<span class=\"p\">SW1#</span> show spanning-tree summary\nSwitch is in rapid-pvst mode</pre>","exPlain":"SW1(config)# spanning-tree mode rapid-pvst\nSW1# show spanning-tree summary\nSwitch is in rapid-pvst mode","neg":"no spanning-tree mode","kind":"cmd"},{"i":100,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree vlan <i>id</i> root primary | secondary","synPlain":"spanning-tree vlan id root primary | secondary","mode":"Global Config","modeCls":"m-gconf","ar":"ماكرو يضبط أولوية الجسر لتصبح الجذر. <code>primary</code> يضبط الأولوية على <b>24576</b> (أو أقل من الجذر الحالي بـ 4096)، و<code>secondary</code> على <b>28672</b>. الطريقة اليدوية أدق في التحكم لكن الماكرو أسرع وأقل خطأً.","en":"Sets the bridge priority so this switch becomes root (primary) or backup root (secondary).","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree vlan 10 root primary\n<span class=\"p\">SW2(config)#</span> spanning-tree vlan 10 root secondary\n<span class=\"p\">SW1#</span> show spanning-tree vlan 10 | include root</pre>","exPlain":"SW1(config)# spanning-tree vlan 10 root primary\nSW2(config)# spanning-tree vlan 10 root secondary\nSW1# show spanning-tree vlan 10 | include root","neg":"no spanning-tree vlan 10 root","kind":"cmd"},{"i":101,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree vlan <i>id</i> priority <i>value</i>","synPlain":"spanning-tree vlan id priority value","mode":"Global Config","modeCls":"m-gconf","ar":"يضبط أولوية الجسر يدوياً. القيم مضاعفات 4096 فقط: <span class=\"num\">0, 4096, 8192</span>, 12288, 16384, 20480, 24576, 28672, 32768 (افتراضي), … 61440. <b>الأقل يفوز</b>. تُستخدم مع load balancing: SW1 جذر لـ VLAN <span class=\"num\">10-20</span> وSW2 جذر لـ VLAN 30-40.","en":"Manually sets the bridge priority in 4096 increments; lower wins.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree vlan 10 priority 4096\n<span class=\"p\">SW2(config)#</span> spanning-tree vlan 30 priority 4096\n<span class=\"p\">SW1#</span> show spanning-tree vlan 10</pre>","exPlain":"SW1(config)# spanning-tree vlan 10 priority 4096\nSW2(config)# spanning-tree vlan 30 priority 4096\nSW1# show spanning-tree vlan 10","neg":"no spanning-tree vlan 10 priority","kind":"cmd"},{"i":102,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree vlan <i>id</i> hello-time | forward-time | max-age <i>sec</i>","synPlain":"spanning-tree vlan id hello-time | forward-time | max-age sec","mode":"Global Config","modeCls":"m-gconf","ar":"يضبط مؤقّتات STP. الافتراضيات: hello = 2s، forward-delay = 15s، max-age = 20s. <b>لا تغيّرها إلا على كل السويتشات في النطاق</b> — اختلاف المؤقّتات يسبب عدم استقرار الشجرة. القاعدة: max-age ≥ 2×(hello) و forward-delay = max-age/2 تقريباً.","en":"Tunes the STP timers; change them only when you fully understand the diameter implications.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree vlan 10 hello-time 2\n<span class=\"p\">SW1(config)#</span> spanning-tree vlan 10 forward-time 15\n<span class=\"p\">SW1(config)#</span> spanning-tree vlan 10 max-age 20</pre>","exPlain":"SW1(config)# spanning-tree vlan 10 hello-time 2\nSW1(config)# spanning-tree vlan 10 forward-time 15\nSW1(config)# spanning-tree vlan 10 max-age 20","neg":"no spanning-tree vlan 10 hello-time","kind":"cmd"},{"i":103,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree pathcost method long","synPlain":"spanning-tree pathcost method long","mode":"Global Config","modeCls":"m-gconf","ar":"يستخدم طريقة حساب التكلفة 32-بت (long) بدلاً من 16-بت (short) القديمة. ضروري في الشبكات ذات السرعات العالية (10G/40G/100G) لأن الطريقة القديمة لا تفرّق بينها بشكل صحيح. <b>يجب أن يكون موحّداً على كل السويتشات.</b>","en":"Uses 32-bit path costs, required for 10G and faster links to be distinguished correctly.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree pathcost method long</pre>","exPlain":"SW1(config)# spanning-tree pathcost method long","neg":"no spanning-tree pathcost method","kind":"cmd"},{"i":104,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree portfast","synPlain":"spanning-tree portfast","mode":"Interface Config","modeCls":"m-iconf","ar":"يجعل المنفذ ينتقل فوراً إلى Forwarding متجاوزاً Listening/Learning. يُستخدم <b>فقط</b> على منافذ متصلة بأجهزة طرفية نهائية. تطبيقه على منفذ متصل بسويتش آخر يسبب حلقة شبكية — لذلك يُقرن دائماً بـ BPDU Guard.","en":"Skips listening and learning on an edge port so it forwards immediately.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> spanning-tree portfast\n<span class=\"p\">SW1(config-if)#</span> spanning-tree portfast trunk</pre>","exPlain":"SW1(config-if)# spanning-tree portfast\nSW1(config-if)# spanning-tree portfast trunk","neg":"spanning-tree portfast disable","kind":"cmd"},{"i":105,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree portfast default","synPlain":"spanning-tree portfast default","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل PortFast تلقائياً على <b>كل منافذ الوصول</b> (access ports) في السويتش. مريح في شبكات الوصول الكبيرة، لكنه يحتاج BPDU Guard افتراضياً أيضاً ليكون آمناً.","en":"Applies PortFast to every access port globally.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree portfast default\n<span class=\"p\">SW1(config)#</span> spanning-tree portfast bpduguard default</pre>","exPlain":"SW1(config)# spanning-tree portfast default\nSW1(config)# spanning-tree portfast bpduguard default","neg":"no spanning-tree portfast default","kind":"cmd"},{"i":106,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree bpduguard enable","synPlain":"spanning-tree bpduguard enable","mode":"Interface Config","modeCls":"m-iconf","ar":"يضع المنفذ في حالة <b>err-disabled</b> فور استقباله أي BPDU — أي أن جهازاً غير مصرّح به حاول أن يصبح جزءاً من الشجرة. هذا هو الدرع الأساسي ضد هجمات توصيل سويتش غير مصرّح به. الاستعادة تحتاج <code>shutdown</code> ثم <code>no shutdown</code> أو <code>errdisable recovery</code>.","en":"Err-disables a PortFast port the moment it receives a BPDU, blocking rogue switches.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> spanning-tree bpduguard enable\n<span class=\"p\">SW1#</span> show interfaces status\nGi0/3  err-disabled\n<span class=\"p\">SW1#</span> show spanning-tree interface g0/3</pre>","exPlain":"SW1(config-if)# spanning-tree bpduguard enable\nSW1# show interfaces status\nGi0/3  err-disabled\nSW1# show spanning-tree interface g0/3","neg":"no spanning-tree bpduguard enable","kind":"cmd"},{"i":107,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree bpdufilter enable","synPlain":"spanning-tree bpdufilter enable","mode":"Interface Config","modeCls":"m-iconf","ar":"يمنع إرسال واستقبال BPDUs على المنفذ كلياً. <b>خطر:</b> قد يخلق حلقة لأنه يخفي معلومات الطوبولوجيا. يُستخدم فقط على منافذ لا يجب أن تشارك في STP إطلاقاً (مثل رابط إلى مزوّد خدمة). لا تخلطه مع BPDU Guard.","en":"Silently drops BPDUs in both directions, effectively hiding the port from STP — risky.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> spanning-tree bpdufilter enable</pre>","exPlain":"SW1(config-if)# spanning-tree bpdufilter enable","neg":"no spanning-tree bpdufilter enable","kind":"cmd"},{"i":108,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree guard root","synPlain":"spanning-tree guard root","mode":"Interface Config","modeCls":"m-iconf","ar":"يجعل المنفذ في حالة <b>root-inconsistent</b> (محجوب فعلياً) إذا استقبل BPDU أفضل من BPDU السويتش الحالي — أي إذا حاول جار أن يصبح الجذر. يحمي مكان الجذر المخطط له في الشبكة.","en":"Blocks superior BPDUs so the port can never become root, protecting the root bridge position.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> spanning-tree guard root\n<span class=\"p\">SW1#</span> show spanning-tree inconsistentports</pre>","exPlain":"SW1(config-if)# spanning-tree guard root\nSW1# show spanning-tree inconsistentports","neg":"no spanning-tree guard root","kind":"cmd"},{"i":109,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree vlan <i>id</i> cost <i>value</i>","synPlain":"spanning-tree vlan id cost value","mode":"Interface Config","modeCls":"m-iconf","ar":"يضبط تكلفة المسار للمنفذ في VLAN محدد، للتأثير على اختيار المنفذ الجذر (Root Port). قيمة أقل = مسار أفضل. تُستخدم للتحكم اليدوي في مسار الترافيك عند وجود عدة روابط.","en":"Overrides the port cost to steer the root-port and designated-port election.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> spanning-tree vlan 10 cost 1000\n<span class=\"p\">SW1#</span> show spanning-tree vlan 10 | include Cost</pre>","exPlain":"SW1(config-if)# spanning-tree vlan 10 cost 1000\nSW1# show spanning-tree vlan 10 | include Cost","neg":"no spanning-tree vlan 10 cost","kind":"cmd"},{"i":110,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree vlan <i>id</i> port-priority <i>value</i>","synPlain":"spanning-tree vlan id port-priority value","mode":"Interface Config","modeCls":"m-iconf","ar":"يكسر التعادل بين منفذين لهما نفس التكلفة عند اختيار Root Port. القيم مضاعفات 16 (<span class=\"num\">0–240</span>)، والأقل أفضل. نادراً ما تُستخدم لكنها تظهر في أسئلة CCNP.","en":"Breaks ties between equal-cost ports (lower wins), useful for choosing the forwarding link.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> spanning-tree vlan 10 port-priority 16</pre>","exPlain":"SW1(config-if)# spanning-tree vlan 10 port-priority 16","neg":"no spanning-tree vlan 10 port-priority","kind":"cmd"},{"i":111,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree mst configuration","synPlain":"spanning-tree mst configuration","mode":"Global Config","modeCls":"m-gconf","ar":"يدخلك إلى وضع إعداد MST. الفكرة: بدلاً من شجرة لكل VLAN (مئات الأشجار)، تُجمَّع VLANs في <b>instances</b> قليلة. الشرط الحاسم: <b>اسم المنطقة ورقم الإصدار وربط الـ VLANs يجب أن تتطابق على كل السويتشات</b> وإلا فلن تتحد كمنطقة واحدة.","en":"Enters MST configuration to define instances and map VLANs to them.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree mst configuration\n<span class=\"p\">SW1(config-mst)#</span> name REGION1\n<span class=\"p\">SW1(config-mst)#</span> revision 1\n<span class=\"p\">SW1(config-mst)#</span> instance 1 vlan 10-20\n<span class=\"p\">SW1(config-mst)#</span> instance 2 vlan 30-40\n<span class=\"p\">SW1(config-mst)#</span> end\n<span class=\"p\">SW1(config)#</span> spanning-tree mode mst\n<span class=\"p\">SW1(config)#</span> spanning-tree mst 1 root primary</pre>","exPlain":"SW1(config)# spanning-tree mst configuration\nSW1(config-mst)# name REGION1\nSW1(config-mst)# revision 1\nSW1(config-mst)# instance 1 vlan 10-20\nSW1(config-mst)# instance 2 vlan 30-40\nSW1(config-mst)# end\nSW1(config)# spanning-tree mode mst\nSW1(config)# spanning-tree mst 1 root primary","neg":"no spanning-tree mst configuration","kind":"cmd"},{"i":112,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"show spanning-tree mst configuration","synPlain":"show spanning-tree mst configuration","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض ملخص إعداد MST مع <b>digest</b> — بصمة تُحسب من الاسم والإصدار والـ instances. إن اختلفت البصمة بين سويتشين فهما في منطقتين مختلفتين، وهنا يقع أغلب أخطاء MST.","en":"Verifies the MST region name, revision, and VLAN-to-instance mapping, which must match on all switches.","ex":"<pre><span class=\"p\">SW1#</span> show spanning-tree mst configuration\nName      [REGION1]\nRevision  1     Instances configured 3\nInstance  Vlans mapped\n1         10-20\n2         30-40</pre>","exPlain":"SW1# show spanning-tree mst configuration\nName      [REGION1]\nRevision  1     Instances configured 3\nInstance  Vlans mapped\n1         10-20\n2         30-40","neg":"","kind":"cmd"},{"i":113,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"channel-group <i>n</i> mode <i>{active|passive|desirable|auto|on}</i>","synPlain":"channel-group n mode {active|passive|desirable|auto|on}","mode":"Interface Config","modeCls":"m-iconf","ar":"يضيف المنفذ إلى قناة EtherChannel. يجب تطبيقه على <b>كل</b> المنافذ المشاركة بنفس الرقم والوضع. الشروط الإلزامية: نفس السرعة، نفس الـ duplex، نفس الـ VLAN/وضع الـ trunk، ونفس Native VLAN — أي اختلاف يمنع تكوين القناة.","en":"Binds physical ports into a port-channel; active/passive use LACP, desirable/auto use PAgP, on is static.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface range g0/1 - 2\n<span class=\"p\">SW1(config-if-range)#</span> channel-group 1 mode active\n<span class=\"p\">SW1(config-if-range)#</span> switchport mode trunk\n<span class=\"p\">SW1(config)#</span> interface port-channel 1\n<span class=\"p\">SW1(config-if)#</span> switchport mode trunk</pre>","exPlain":"SW1(config)# interface range g0/1 - 2\nSW1(config-if-range)# channel-group 1 mode active\nSW1(config-if-range)# switchport mode trunk\nSW1(config)# interface port-channel 1\nSW1(config-if)# switchport mode trunk","neg":"no channel-group 1","kind":"cmd"},{"i":114,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"channel-protocol lacp | pagp","synPlain":"channel-protocol lacp | pagp","mode":"Interface Config","modeCls":"m-iconf","ar":"يثبّت البروتوكول المستخدم على المنفذ قبل إنشاء القناة، ويمنع استخدام البروتوكول الآخر بالخطأ. اختياري لكنه يوضّح النية ويقلل الأخطاء في معامل الامتحان.","en":"Locks the negotiation protocol before assigning the channel group.","ex":"<pre><span class=\"p\">SW1(config-if-range)#</span> channel-protocol lacp\n<span class=\"p\">SW1(config-if-range)#</span> channel-group 1 mode active</pre>","exPlain":"SW1(config-if-range)# channel-protocol lacp\nSW1(config-if-range)# channel-group 1 mode active","neg":"no channel-protocol","kind":"cmd"},{"i":115,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"interface port-channel <i>n</i>","synPlain":"interface port-channel n","mode":"Global Config","modeCls":"m-gconf","ar":"الواجهة المنطقية للقناة. <b>القاعدة الذهبية:</b> إعدادات الطبقة الثانية (trunk، allowed vlan، STP) تُطبَّق على واجهة port-channel، لا على المنافذ الأعضاء — لأنها المرجع الذي يفرض إعداداته على الأعضاء. تطبيق الإعداد على الأعضاء وحدها يسبب سلوكاً غير متوقع.","en":"Enters the logical port-channel interface where trunk, ACL, and QoS settings are applied.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface port-channel 1\n<span class=\"p\">SW1(config-if)#</span> switchport trunk allowed vlan 10,20,30\n<span class=\"p\">SW1(config-if)#</span> description EtherChannel to SW2</pre>","exPlain":"SW1(config)# interface port-channel 1\nSW1(config-if)# switchport trunk allowed vlan 10,20,30\nSW1(config-if)# description EtherChannel to SW2","neg":"no interface port-channel 1","kind":"cmd"},{"i":116,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"port-channel load-balance <i>method</i>","synPlain":"port-channel load-balance method","mode":"Global Config","modeCls":"m-gconf","ar":"يحدد خوارزمية توزيع الترافيك على روابط القناة. الخيارات الشائعة: <code>src-mac</code>، <code>dst-mac</code>، <code>src-dst-mac</code>، <code>src-ip</code>، <code>dst-ip</code>، <code>src-dst-ip</code>، <code>src-dst-port</code>. <b>مهم:</b> التوزيع يتم لكل تدفق (flow) وليس لكل حزمة، لذلك لا يمكن لأي تدفق واحد أن يتجاوز سرعة رابط واحد.","en":"Chooses the hash used to spread traffic across member links (src-dst-ip, src-dst-mac, ...).","ex":"<pre><span class=\"p\">SW1(config)#</span> port-channel load-balance src-dst-ip\n<span class=\"p\">SW1#</span> show etherchannel load-balance</pre>","exPlain":"SW1(config)# port-channel load-balance src-dst-ip\nSW1# show etherchannel load-balance","neg":"no port-channel load-balance","kind":"cmd"},{"i":117,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"lacp system-priority <i>n</i> | lacp port-priority <i>n</i>","synPlain":"lacp system-priority n | lacp port-priority n","mode":"Global / Interface","modeCls":"m-gconf","ar":"يتحكمان في اختيار المنافذ النشطة (Active) داخل قناة LACP عندما يكون عدد المنافذ أكبر من الحد المسموح. الأقل أفضل. مفيد في CCNP لضبط سلوك LACP Fallback.","en":"Influences which side becomes the LACP actor and which links are placed in standby.","ex":"<pre><span class=\"p\">SW1(config)#</span> lacp system-priority 100\n<span class=\"p\">SW1(config-if)#</span> lacp port-priority 10</pre>","exPlain":"SW1(config)# lacp system-priority 100\nSW1(config-if)# lacp port-priority 10","neg":"no lacp system-priority","kind":"cmd"},{"i":118,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"show etherchannel summary","synPlain":"show etherchannel summary","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"أهم أمر لتشخيص EtherChannel. اقرأ الرموز: <b>SU</b> = Switchport + Up (ممتاز)، <b>RU</b> = Routed + Up، <b>P</b> = bundled in port-channel، <b>D</b> = down، <b>I</b> = stand-alone (فشل الانضمام)، <b>s</b> = suspended. أي حرف غير <code>P</code> بجانب منفذ يعني مشكلة تطابق إعدادات.","en":"Shows each bundle, its protocol, and member-port flags (P = bundled, I = standalone).","ex":"<pre><span class=\"p\">SW1#</span> show etherchannel summary\nGroup  Port-channel  Protocol   Ports\n1      Po1(SU)         LACP       Gi0/1(P)  Gi0/2(P)</pre>","exPlain":"SW1# show etherchannel summary\nGroup  Port-channel  Protocol   Ports\n1      Po1(SU)         LACP       Gi0/1(P)  Gi0/2(P)","neg":"","kind":"cmd"},{"i":119,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"show lacp neighbor | show pagp neighbor","synPlain":"show lacp neighbor | show pagp neighbor","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض ما يراه الجار من جهتك والعكس: معرّفات النظام، أعلام الحالة (flags)، وأرقام المنافذ. مفيد جداً عندما يكون أحد الطرفين <code>active</code> والآخر <code>passive</code> ولا تتكون القناة.","en":"Displays the partner's LACP or PAgP identifiers to confirm negotiation succeeded.","ex":"<pre><span class=\"p\">SW1#</span> show lacp neighbor\nFlags:  S - Device is requesting Slow LACPDUs\nPort      Flags   State     System ID\nGi0/1     SA      bndl      32768,00e0.8f57.1111</pre>","exPlain":"SW1# show lacp neighbor\nFlags:  S - Device is requesting Slow LACPDUs\nPort      Flags   State     System ID\nGi0/1     SA      bndl      32768,00e0.8f57.1111","neg":"","kind":"cmd"},{"i":120,"sec":"stp","no":"06","secAr":"Spanning Tree وEtherChannel","secEn":"STP & EtherChannel","grp":"switching","syn":"spanning-tree portfast bpduguard default","synPlain":"spanning-tree portfast bpduguard default","mode":"Global Config","modeCls":"m-glob","ar":"يفعّل BPDU Guard على <b>كل</b> منفذ PortFast في الجهاز بأمر واحد، بدل تكراره منفذاً منفذاً. هو الأسلوب الموصى به على منافذ الوصول: أي BPDU يصل يعني أن مستخدماً وصّل سويتشاً أو موزّعاً، فيدخل المنفذ <code>err-disabled</code> فوراً ويحمي الـ Root Bridge من الانحراف. تذكّر أن PortFast وحده لا يحمي شيئاً — الحماية تأتي من BPDU Guard.","en":"Enables BPDU Guard on every PortFast port in one shot. A BPDU arriving on an access port means somebody plugged in a switch, so the port goes err-disabled and the root bridge stays put.","ex":"<pre><span class=\"p\">SW1(config)#</span> spanning-tree portfast default\n<span class=\"p\">SW1(config)#</span> spanning-tree portfast bpduguard default\n<span class=\"p\">SW1#</span> show spanning-tree summary\nSwitch is in rapid-pvst mode\nPortFast BPDU Guard is enabled\nPortfast Default is enabled</pre>","exPlain":"SW1(config)# spanning-tree portfast default\nSW1(config)# spanning-tree portfast bpduguard default\nSW1# show spanning-tree summary\nSwitch is in rapid-pvst mode\nPortFast BPDU Guard is enabled\nPortfast Default is enabled","neg":"no spanning-tree portfast bpduguard default","kind":"cmd"},{"i":121,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"switchport port-security","synPlain":"switchport port-security","mode":"Interface Config","modeCls":"m-iconf","ar":"يفعّل ميزة Port Security على المنفذ. <b>شرطان مسبقان:</b> المنفذ يجب أن يكون <code>switchport mode access</code> (أو trunk مع إعداد خاص)، والمنفذ يجب ألا يكون ضمن EtherChannel. بعد التفعيل يُسمح افتراضياً بعنوان MAC واحد فقط.","en":"Enables port security on an access port; it cannot run on a trunk or dynamic port.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface g0/1\n<span class=\"p\">SW1(config-if)#</span> switchport mode access\n<span class=\"p\">SW1(config-if)#</span> switchport port-security\n<span class=\"p\">SW1(config-if)#</span> switchport port-security maximum 2\n<span class=\"p\">SW1(config-if)#</span> switchport port-security mac-address sticky</pre>","exPlain":"SW1(config)# interface g0/1\nSW1(config-if)# switchport mode access\nSW1(config-if)# switchport port-security\nSW1(config-if)# switchport port-security maximum 2\nSW1(config-if)# switchport port-security mac-address sticky","neg":"no switchport port-security","kind":"cmd"},{"i":122,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"switchport port-security maximum <i>n</i> [vlan <i>id</i>]","synPlain":"switchport port-security maximum n [vlan id]","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد أقصى عدد عناوين MAC مسموح بها على المنفذ (<span class=\"num\">1–3072</span>، الافتراضي 1). في منفذ Voice يُرفع إلى 2 أو 3 (هاتف + حاسوب). زيادة العدد عن الحاجة تُضعف الحماية، وتقليله عن الحاجة يسبب تعطيلاً مفاجئاً للمستخدمين.","en":"Caps how many MAC addresses may be learned on the port.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport port-security maximum 3\n<span class=\"p\">SW1(config-if)#</span> switchport port-security maximum 2 vlan access</pre>","exPlain":"SW1(config-if)# switchport port-security maximum 3\nSW1(config-if)# switchport port-security maximum 2 vlan access","neg":"no switchport port-security maximum","kind":"cmd"},{"i":123,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"switchport port-security mac-address <i>mac</i> | sticky","synPlain":"switchport port-security mac-address mac | sticky","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد العناوين المسموح بها. <b>الطريقة اليدوية</b> (<code>mac-address aaaa.bbbb.cccc</code>) أكثر أماناً لأنها صريحة. <b>sticky</b> يتعلّم أول MAC يظهر ويحفظه في الإعداد — مريح لكنه يفقد الحماية إذا استُبدل الجهاز. يمكن الجمع بينهما.","en":"Pins allowed MACs manually, or learns them and writes them into the running-config with sticky.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport port-security mac-address 0050.7966.6800\n<span class=\"p\">SW1(config-if)#</span> switchport port-security mac-address sticky\n<span class=\"p\">SW1#</span> show port-security interface g0/1\nSecureStickyMacAddresses : 1</pre>","exPlain":"SW1(config-if)# switchport port-security mac-address 0050.7966.6800\nSW1(config-if)# switchport port-security mac-address sticky\nSW1# show port-security interface g0/1\nSecureStickyMacAddresses : 1","neg":"no switchport port-security mac-address sticky","kind":"cmd"},{"i":124,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"switchport port-security violation <i>{protect|restrict|shutdown}</i>","synPlain":"switchport port-security violation {protect|restrict|shutdown}","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد ردة الفعل عند مخالفة القاعدة. الافتراضي <b>shutdown</b>:","en":"Chooses the action on violation: drop silently, drop and log, or err-disable the port.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport port-security violation restrict\n<span class=\"p\">SW1#</span> show port-security interface g0/1\nSecurity Violation Mode : Restrict\nTotal violations        : 4</pre>","exPlain":"SW1(config-if)# switchport port-security violation restrict\nSW1# show port-security interface g0/1\nSecurity Violation Mode : Restrict\nTotal violations        : 4","neg":"no switchport port-security violation","kind":"cmd"},{"i":125,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"switchport port-security aging time <i>min</i> | aging type <i>{absolute|inactivity}</i>","synPlain":"switchport port-security aging time min | aging type {absolute|inactivity}","mode":"Interface Config","modeCls":"m-iconf","ar":"يجعل العناوين المتعلّمة تنتهي صلاحيتها بعد فترة. <code>absolute</code> = بعد الوقت المحدد من التعلّم، <code>inactivity</code> = بعد فترة عدم استخدام. يُستخدم في بيئات تتغير فيها الأجهزة (قاعات، مختبرات).","en":"Ages out secure MACs after a timer (absolute) or after a period of inactivity.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport port-security aging time 30\n<span class=\"p\">SW1(config-if)#</span> switchport port-security aging type inactivity\n<span class=\"p\">SW1(config-if)#</span> switchport port-security aging static</pre>","exPlain":"SW1(config-if)# switchport port-security aging time 30\nSW1(config-if)# switchport port-security aging type inactivity\nSW1(config-if)# switchport port-security aging static","neg":"no switchport port-security aging time","kind":"cmd"},{"i":126,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"show port-security | show port-security interface <i>intf</i> | show port-security address","synPlain":"show port-security | show port-security interface intf | show port-security address","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"الثلاثة معاً يعطون الصورة الكاملة: ملخص كل المنافذ المحمية، تفاصيل منفذ واحد (الحد الأقصى، عدد العناوين، عدد المخالفات، وضع المخالفة)، وجدول العناوين الآمنة. ابدأ دائماً بـ <code>show port-security</code>.","en":"Shows the global or per-interface policy and the secure MAC address table.","ex":"<pre><span class=\"p\">SW1#</span> show port-security\nSecure Port  MaxSecureAddr  CurrentAddr  SecurityViolation  State\nGi0/1        2               1            0                  Secure-up\n<span class=\"p\">SW1#</span> show port-security address\nMacAddress         Type       Ports\n0050.7966.6800     SecureSticky Gi0/1</pre>","exPlain":"SW1# show port-security\nSecure Port  MaxSecureAddr  CurrentAddr  SecurityViolation  State\nGi0/1        2               1            0                  Secure-up\nSW1# show port-security address\nMacAddress         Type       Ports\n0050.7966.6800     SecureSticky Gi0/1","neg":"","kind":"cmd"},{"i":127,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"mac address-table static <i>mac</i> vlan <i>id</i> interface <i>intf</i>","synPlain":"mac address-table static mac vlan id interface intf","mode":"Global Config","modeCls":"m-gconf","ar":"يضيف إدخالاً ثابتاً في جدول CAM. مفيد للأجهزة التي لا ترسل ترافيكاً (فلا يتعلّم السويتش عنوانها)، أو لمنع انتحال MAC لبوابة معيّنة. يختلف عن Port Security: هذا يحدد «أين يوجد العنوان»، وذاك يحدد «من يُسمح له بالاتصال».","en":"Adds a permanent CAM entry that will never age out.","ex":"<pre><span class=\"p\">SW1(config)#</span> mac address-table static 0050.7966.6800 vlan 10 interface g0/5\n<span class=\"p\">SW1#</span> show mac address-table static</pre>","exPlain":"SW1(config)# mac address-table static 0050.7966.6800 vlan 10 interface g0/5\nSW1# show mac address-table static","neg":"no mac address-table static 0050.7966.6800 vlan 10","kind":"cmd"},{"i":128,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"mac address-table aging-time <i>sec</i>","synPlain":"mac address-table aging-time sec","mode":"Global Config","modeCls":"m-gconf","ar":"مدة بقاء إدخال MAC في الجدول قبل حذفه (افتراضي 300 ثانية). تقليلها يزيد حركة إعادة التعلّم؛ زيادتها تُبقي إدخالات قديمة. لا تُغيّرها إلا لسبب.","en":"Sets how long a dynamically learned MAC address stays in the CAM table.","ex":"<pre><span class=\"p\">SW1(config)#</span> mac address-table aging-time 600</pre>","exPlain":"SW1(config)# mac address-table aging-time 600","neg":"no mac address-table aging-time","kind":"cmd"},{"i":129,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip dhcp snooping","synPlain":"ip dhcp snooping","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل الميزة عالمياً على السويتش. الفكرة: السويتش يبني جدول <b>bindings</b> (MAC + IP + VLAN + المنفذ) من رسائل DHCP الصادرة عن خادم موثوق، ثم يستخدمه لفلترة رسائل DHCP الخبيثة ولحماية ARP. <b>لا تعمل الميزة قبل تفعيلها لكل VLAN.</b>","en":"Enables DHCP snooping globally; every port is untrusted until explicitly trusted.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip dhcp snooping\n<span class=\"p\">SW1(config)#</span> ip dhcp snooping vlan 10,20\n<span class=\"p\">SW1(config)#</span> no ip dhcp snooping information option</pre>","exPlain":"SW1(config)# ip dhcp snooping\nSW1(config)# ip dhcp snooping vlan 10,20\nSW1(config)# no ip dhcp snooping information option","neg":"no ip dhcp snooping","kind":"cmd"},{"i":130,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip dhcp snooping trust","synPlain":"ip dhcp snooping trust","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد المنافذ الموثوقة التي يُسمح لها بإرسال ردود DHCP (Offer/ACK) — وهي المنافذ المتجهة إلى خادم DHCP الحقيقي أو إلى الراوتر (Relay). كل المنافذ الأخرى تصبح <b>untrusted</b> وتُسقط أي رد DHCP. <b>هذا هو جوهر الحماية من Rogue DHCP.</b>","en":"Marks the uplink toward the real DHCP server as trusted so its offers are accepted.","ex":"<pre><span class=\"p\">SW1(config)#</span> interface g0/24\n<span class=\"p\">SW1(config-if)#</span> ip dhcp snooping trust\n<span class=\"p\">SW1(config)#</span> interface range g0/1 - 20\n<span class=\"p\">SW1(config-if-range)#</span> ip dhcp snooping limit rate 10</pre>","exPlain":"SW1(config)# interface g0/24\nSW1(config-if)# ip dhcp snooping trust\nSW1(config)# interface range g0/1 - 20\nSW1(config-if-range)# ip dhcp snooping limit rate 10","neg":"no ip dhcp snooping trust","kind":"cmd"},{"i":131,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip dhcp snooping limit rate <i>pps</i>","synPlain":"ip dhcp snooping limit rate pps","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد أقصى معدل لحزم DHCP على المنفذ (حزم/ثانية). يحمي من هجوم إغراق DHCP (DHCP Starvation) الذي يستهلك كل العناوين. عند التجاوز يدخل المنفذ في err-disabled.","en":"Rate-limits DHCP messages on an untrusted port to stop starvation attacks.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> ip dhcp snooping limit rate 10</pre>","exPlain":"SW1(config-if)# ip dhcp snooping limit rate 10","neg":"no ip dhcp snooping limit rate","kind":"cmd"},{"i":132,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"show ip dhcp snooping binding","synPlain":"show ip dhcp snooping binding","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض جدول الربط: MAC، IP، مدة الإيجار، VLAN، والمنفذ. هذا الجدول هو الأساس الذي تعتمد عليه DAI وIP Source Guard — إن كان فارغاً فالميزات الثلاث لا تعمل.","en":"Shows the trusted bindings (MAC, IP, VLAN, port, lease) that DAI and IP Source Guard rely on.","ex":"<pre><span class=\"p\">SW1#</span> show ip dhcp snooping binding\nMacAddress     IpAddress     Lease(sec)  Type   VLAN  Interface\n00:50:79:66:68:00  192.168.10.50  86400  dhcp-snooping 10  Gi0/1</pre>","exPlain":"SW1# show ip dhcp snooping binding\nMacAddress     IpAddress     Lease(sec)  Type   VLAN  Interface\n00:50:79:66:68:00  192.168.10.50  86400  dhcp-snooping 10  Gi0/1","neg":"","kind":"cmd"},{"i":133,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip arp inspection vlan <i>list</i>","synPlain":"ip arp inspection vlan list","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل Dynamic ARP Inspection: يتحقق من كل حزمة ARP مقابل جدول DHCP Snooping ويرفض أي ربط غير مطابق. هكذا يُمنع ARP Spoofing الذي يسمح باعتراض الترافيك (MITM). <b>يعتمد كلياً على DHCP Snooping</b> — أو على إدخالات ARP ACL يدوية للأجهزة ذات IP ثابت.","en":"Enables Dynamic ARP Inspection for the listed VLANs.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip arp inspection vlan 10,20\n<span class=\"p\">SW1(config)#</span> interface g0/24\n<span class=\"p\">SW1(config-if)#</span> ip arp inspection trust</pre>","exPlain":"SW1(config)# ip arp inspection vlan 10,20\nSW1(config)# interface g0/24\nSW1(config-if)# ip arp inspection trust","neg":"no ip arp inspection vlan 10,20","kind":"cmd"},{"i":134,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip arp inspection validate <i>{src-mac|dst-mac|ip}</i>","synPlain":"ip arp inspection validate {src-mac|dst-mac|ip}","mode":"Global Config","modeCls":"m-gconf","ar":"يضيف فحوصاً إضافية لحزم ARP: تطابق MAC المصدر مع الإطار، تطابق MAC الهدف، وصحة عناوين IP (لا 0.0.0.0 ولا Multicast). كلها معاً تعطي أقصى حماية.","en":"Adds extra checks (source MAC, destination MAC, IP) before an ARP packet is forwarded.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip arp inspection validate src-mac dst-mac ip\n<span class=\"p\">SW1#</span> show ip arp inspection statistics</pre>","exPlain":"SW1(config)# ip arp inspection validate src-mac dst-mac ip\nSW1# show ip arp inspection statistics","neg":"no ip arp inspection validate","kind":"cmd"},{"i":135,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip verify source","synPlain":"ip verify source","mode":"Interface Config","modeCls":"m-iconf","ar":"يفعّل IP Source Guard: يمنع أي جهاز من استخدام عنوان IP غير مخصص له (منع IP Spoofing) بالاعتماد على جدول Snooping. الصيغة <code>ip verify source port-security</code> تضيف التحقق من MAC أيضاً.","en":"Enables IP Source Guard, dropping traffic whose source IP or MAC is not in the snooping table.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> ip verify source\n<span class=\"p\">SW1#</span> show ip verify source</pre>","exPlain":"SW1(config-if)# ip verify source\nSW1# show ip verify source","neg":"no ip verify source","kind":"cmd"},{"i":136,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"switchport protected","synPlain":"switchport protected","mode":"Interface Config","modeCls":"m-iconf","ar":"يمنع الترافيك بين المنافذ المحمية في نفس السويتش (Private VLAN مبسّط). مثال: منفذان في نفس VLAN لا يستطيع أحدهما الوصول للآخر، لكن كليهما يصل إلى البوابة. تُستخدم في شبكات الفنادق والمختبرات.","en":"Isolates the port from other protected ports in the same VLAN — private-VLAN-lite.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> switchport protected</pre>","exPlain":"SW1(config-if)# switchport protected","neg":"no switchport protected","kind":"cmd"},{"i":137,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"storm-control <i>{broadcast|multicast|unicast}</i> level <i>pps|%</i>","synPlain":"storm-control {broadcast|multicast|unicast} level pps|%","mode":"Interface Config","modeCls":"m-iconf","ar":"يحد من معدل ترافيك معيّن لمنع عواصف البث (Broadcast Storm) التي تُشلّ الشبكة. عند تجاوز الحد، السلوك الافتراضي هو إسقاط الزائد (filter). يمكن استخدام <code>action shutdown</code> أو <code>trap</code>.","en":"Caps the rate of one traffic type and drops the excess to protect the switch.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> storm-control broadcast level 20\n<span class=\"p\">SW1(config-if)#</span> storm-control multicast level 20\n<span class=\"p\">SW1(config-if)#</span> storm-control action trap\n<span class=\"p\">SW1#</span> show storm-control broadcast</pre>","exPlain":"SW1(config-if)# storm-control broadcast level 20\nSW1(config-if)# storm-control multicast level 20\nSW1(config-if)# storm-control action trap\nSW1# show storm-control broadcast","neg":"no storm-control broadcast level","kind":"cmd"},{"i":138,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"errdisable recovery cause <i>cause</i> | errdisable recovery interval <i>sec</i>","synPlain":"errdisable recovery cause cause | errdisable recovery interval sec","mode":"Global Config","modeCls":"m-gconf","ar":"يجعل السويتش يعيد تشغيل المنافذ المعطّلة تلقائياً بعد فترة بدلاً من تدخّل يدوي. الأسباب الشائعة: <code>psecure-violation</code>، <code>bpduguard</code>، <code>link-flap</code>، <code>dhcp-rate-limit</code>. الافتراضي للفترة 300 ثانية.","en":"Automatically re-enables err-disabled ports after a timer instead of a manual shutdown / no shutdown.","ex":"<pre><span class=\"p\">SW1(config)#</span> errdisable recovery cause psecure-violation\n<span class=\"p\">SW1(config)#</span> errdisable recovery cause bpduguard\n<span class=\"p\">SW1(config)#</span> errdisable recovery interval 300\n<span class=\"p\">SW1#</span> show errdisable recovery</pre>","exPlain":"SW1(config)# errdisable recovery cause psecure-violation\nSW1(config)# errdisable recovery cause bpduguard\nSW1(config)# errdisable recovery interval 300\nSW1# show errdisable recovery","neg":"no errdisable recovery cause psecure-violation","kind":"cmd"},{"i":139,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"show errdisable detect | show interfaces status err-disabled","synPlain":"show errdisable detect | show interfaces status err-disabled","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض أسباب تعطيل المنافذ وسبب التعطيل الحالي لكل منفذ. أول أمر تكتبه عندما تجد منفذاً <code>err-disabled</code> ولا تعرف لماذا.","en":"Lists which err-disable causes are enabled and which ports are currently err-disabled.","ex":"<pre><span class=\"p\">SW1#</span> show interfaces status err-disabled\nPort  Name  Status        Reason\nGi0/3       err-disabled  psecure-violation</pre>","exPlain":"SW1# show interfaces status err-disabled\nPort  Name  Status        Reason\nGi0/3       err-disabled  psecure-violation","neg":"","kind":"cmd"},{"i":140,"sec":"l2sec","no":"07","secAr":"أمان الطبقة الثانية","secEn":"Layer 2 Security","grp":"switching","syn":"ip arp inspection trust","synPlain":"ip arp inspection trust","mode":"Interface Config","modeCls":"m-iconf","ar":"يستثني المنفذ من فحص DAI. <b>إلزامي</b> على الواجهات المتجهة إلى سويتشات أخرى أو إلى الراوتر، لأن ARP الشرعي القادم من هناك لن يكون في جدول DHCP Snooping فيُسقَط ويُقطع الاتصال. منافذ المستخدمين تبقى <b>غير موثوقة</b> (الافتراضي) هي المقصودة بالحماية. قاعدة عامة: الثقة على الأبلكنك فقط، أبداً على منفذ مستخدم.","en":"Exempts an uplink from Dynamic ARP Inspection. Legitimate ARP from another switch or the router is not in the DHCP snooping table, so an untrusted uplink would drop it and break the network.","ex":"<pre><span class=\"p\">SW1(config)#</span> ip arp inspection vlan 10,20\n<span class=\"p\">SW1(config)#</span> interface GigabitEthernet0/24\n<span class=\"p\">SW1(config-if)#</span> ip arp inspection trust\n<span class=\"p\">SW1(config-if)#</span> ip dhcp snooping trust\n<span class=\"p\">SW1#</span> show ip arp inspection interfaces Gi0/24\n Interface        Trust State     Rate (pps)    Burst Interval\n ---------------  -----------     ----------    --------------\n Gi0/24           Trusted                 None                 1</pre>","exPlain":"SW1(config)# ip arp inspection vlan 10,20\nSW1(config)# interface GigabitEthernet0/24\nSW1(config-if)# ip arp inspection trust\nSW1(config-if)# ip dhcp snooping trust\nSW1# show ip arp inspection interfaces Gi0/24\n Interface        Trust State     Rate (pps)    Burst Interval\n ---------------  -----------     ----------    --------------\n Gi0/24           Trusted                 None                 1","neg":"no ip arp inspection trust","kind":"cmd"},{"i":141,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ip route <i>network</i> <i>mask</i> <i>{next-hop | exit-interface}</i> [<i>distance</i>]","synPlain":"ip route network mask {next-hop | exit-interface} [distance]","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ مساراً ساكناً. <b>next-hop</b> (عنوان IP للجار) هو الأسلوب المفضّل على روابط Ethernet لأنه يمنع مشكلة الـ Proxy ARP ويجبر الراوتر على التحقق من قابلية الوصول. <b>exit-interface</b> يُستخدم عادة على روابط Point-to-Point. ويمكن الجمع بينهما.","en":"Adds a static route through a next hop or a point-to-point exit interface.","ex":"<pre><span class=\"p\">R1(config)#</span> ip route 192.168.20.0 255.255.255.0 10.1.1.2\n<span class=\"p\">R1(config)#</span> ip route 192.168.30.0 255.255.255.0 s0/0/0\n<span class=\"p\">R1(config)#</span> ip route 172.16.0.0 255.255.0.0 10.1.1.2 name TO-DC\n<span class=\"p\">R1#</span> show ip route static</pre>","exPlain":"R1(config)# ip route 192.168.20.0 255.255.255.0 10.1.1.2\nR1(config)# ip route 192.168.30.0 255.255.255.0 s0/0/0\nR1(config)# ip route 172.16.0.0 255.255.0.0 10.1.1.2 name TO-DC\nR1# show ip route static","neg":"no ip route 192.168.20.0 255.255.255.0 10.1.1.2","kind":"cmd"},{"i":142,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ip route 0.0.0.0 0.0.0.0 <i>{next-hop | exit-interface}</i>","synPlain":"ip route 0.0.0.0 0.0.0.0 {next-hop | exit-interface}","mode":"Global Config","modeCls":"m-gconf","ar":"المسار الافتراضي (Default Route). يُستخدم عندما لا توجد بادئة أكثر تحديداً في الجدول — وهو الحال الطبيعي لراوتر متصل بالإنترنت. في الشبكات الطرفية (Stub) يكفي مسار افتراضي بدلاً من بروتوكول توجيه كامل.","en":"Installs the default route (quad-zero) used when no more specific prefix matches.","ex":"<pre><span class=\"p\">R1(config)#</span> ip route 0.0.0.0 0.0.0.0 200.1.1.1\n<span class=\"p\">R1#</span> show ip route\nS*   0.0.0.0/0 [1/0] via 200.1.1.1</pre>","exPlain":"R1(config)# ip route 0.0.0.0 0.0.0.0 200.1.1.1\nR1# show ip route\nS*   0.0.0.0/0 [1/0] via 200.1.1.1","neg":"no ip route 0.0.0.0 0.0.0.0","kind":"cmd"},{"i":143,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ip route <i>network mask next-hop</i> <i>distance</i>","synPlain":"ip route network mask next-hop distance","mode":"Global Config","modeCls":"m-gconf","ar":"<b>Floating Static Route:</b> مسار احتياطي برقم AD أعلى من المسار الأساسي. يبقى مخفياً في الجدول حتى يسقط المسار الأساسي، فيظهر ويأخذ دوره. مثال: مسار أساسي عبر OSPF (AD 110) ومسار احتياطي ساكن بـ AD 130.","en":"Floating static route: a higher administrative distance makes it a backup only.","ex":"<pre><span class=\"p\">R1(config)#</span> ip route 0.0.0.0 0.0.0.0 200.1.1.1 1\n<span class=\"p\">R1(config)#</span> ip route 0.0.0.0 0.0.0.0 201.1.1.1 130\n<span class=\"p\">R1#</span> show ip route 0.0.0.0</pre>","exPlain":"R1(config)# ip route 0.0.0.0 0.0.0.0 200.1.1.1 1\nR1(config)# ip route 0.0.0.0 0.0.0.0 201.1.1.1 130\nR1# show ip route 0.0.0.0","neg":"no ip route 0.0.0.0 0.0.0.0 201.1.1.1 130","kind":"cmd"},{"i":144,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ip route <i>network mask</i> <i>next-hop</i> track <i>object-number</i>","synPlain":"ip route network mask next-hop track object-number","mode":"Global Config","modeCls":"m-gconf","ar":"يربط المسار الساكن بكائن تتبّع (IP SLA) فيُحذف من الجدول تلقائياً عند فشل الاختبار — حتى لو بقيت الواجهة <code>up</code>. هذا هو الحل الاحترافي لمشكلة «الواجهة مفتوحة لكن المسار ميت».","en":"Ties the static route to an IP SLA object so the route is withdrawn when the probe fails.","ex":"<pre><span class=\"p\">R1(config)#</span> ip sla 1\n<span class=\"p\">R1(config-ip-sla)#</span> icmp-echo 8.8.8.8 source-interface g0/0\n<span class=\"p\">R1(config-ip-sla)#</span> frequency 5\n<span class=\"p\">R1(config)#</span> ip sla schedule 1 life forever start-time now\n<span class=\"p\">R1(config)#</span> track 1 ip sla 1 reachability\n<span class=\"p\">R1(config)#</span> ip route 0.0.0.0 0.0.0.0 200.1.1.1 track 1</pre>","exPlain":"R1(config)# ip sla 1\nR1(config-ip-sla)# icmp-echo 8.8.8.8 source-interface g0/0\nR1(config-ip-sla)# frequency 5\nR1(config)# ip sla schedule 1 life forever start-time now\nR1(config)# track 1 ip sla 1 reachability\nR1(config)# ip route 0.0.0.0 0.0.0.0 200.1.1.1 track 1","neg":"no ip route 0.0.0.0 0.0.0.0 200.1.1.1 track 1","kind":"cmd"},{"i":145,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ipv6 route <i>prefix/len</i> <i>{next-hop | exit-interface}</i> [<i>distance</i>]","synPlain":"ipv6 route prefix/len {next-hop | exit-interface} [distance]","mode":"Global Config","modeCls":"m-gconf","ar":"المكافئ السادس للمسار الساكن. لاحظ أن القناع يُكتب بصيغة CIDR دائماً. المسار الافتراضي هو <code>::/0</code>. يتطلب <code>ipv6 unicast-routing</code> ليعمل التوجيه فعلياً.","en":"Adds a static IPv6 route; the next hop is usually a link-local address.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 unicast-routing\n<span class=\"p\">R1(config)#</span> ipv6 route 2001:db8:20::/64 2001:db8:10::2\n<span class=\"p\">R1(config)#</span> ipv6 route ::/0 2001:db8:99::1\n<span class=\"p\">R1#</span> show ipv6 route static</pre>","exPlain":"R1(config)# ipv6 unicast-routing\nR1(config)# ipv6 route 2001:db8:20::/64 2001:db8:10::2\nR1(config)# ipv6 route ::/0 2001:db8:99::1\nR1# show ipv6 route static","neg":"no ipv6 route ::/0 2001:db8:99::1","kind":"cmd"},{"i":146,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ip classless","synPlain":"ip classless","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل البحث بأطول بادئة بدلاً من التوجيه الطبقي القديم (Classful). <b>مفعّل افتراضياً</b> في كل الإصدارات الحديثة ولا يجب تعطيله. يظهر في الامتحان كسؤال مفهومي فقط.","en":"Allows the default route to be used for unknown subnets — the default behaviour in modern IOS.","ex":"<pre><span class=\"p\">R1(config)#</span> ip classless</pre>","exPlain":"R1(config)# ip classless","neg":"no ip classless","kind":"cmd"},{"i":147,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"show ip route [<i>network</i>] [<i>protocol</i>]","synPlain":"show ip route [network] [protocol]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض جدول التوجيه. القوسان <code>[AD/Metric]</code> بعد كل مسار هما مفتاح التشخيص: الأول المسافة الإدارية (مصدر المعلومة)، والثاني المترية (جودة المسار داخل نفس المصدر).","en":"Displays the routing table with route codes, administrative distance, metric, and next hop.","ex":"<pre><span class=\"p\">R1#</span> show ip route\nGateway of last resort is 200.1.1.1 to network 0.0.0.0\nS*  0.0.0.0/0 [1/0] via 200.1.1.1\n     10.0.0.0/8 is variably subnetted, 2 subnets\nC       10.1.1.0/24 is directly connected, GigabitEthernet0/0\nL       10.1.1.1/32 is directly connected, GigabitEthernet0/0\nO    192.168.20.0/24 [110/2] via 10.1.1.2, 00:12:44, GigabitEthernet0/0</pre>","exPlain":"R1# show ip route\nGateway of last resort is 200.1.1.1 to network 0.0.0.0\nS*  0.0.0.0/0 [1/0] via 200.1.1.1\n     10.0.0.0/8 is variably subnetted, 2 subnets\nC       10.1.1.0/24 is directly connected, GigabitEthernet0/0\nL       10.1.1.1/32 is directly connected, GigabitEthernet0/0\nO    192.168.20.0/24 [110/2] via 10.1.1.2, 00:12:44, GigabitEthernet0/0","neg":"","kind":"cmd"},{"i":148,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"show ip route <i>ip</i> | show ip route summary","synPlain":"show ip route ip | show ip route summary","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"<code>show ip route 192.168.20.5</code> يجيب على سؤال «كيف سيصل الراوتر إلى هذا العنوان تحديداً؟» — وهذا أدق من النظر إلى الجدول كاملاً. و<code>summary</code> يعطي إحصاءات لكل بروتوكول.","en":"Shows the longest-prefix match for one destination, or a per-protocol route count.","ex":"<pre><span class=\"p\">R1#</span> show ip route 192.168.20.5\nRouting entry for 192.168.20.0/24\n  Known via \"ospf 1\", distance 110, metric 2</pre>","exPlain":"R1# show ip route 192.168.20.5\nRouting entry for 192.168.20.0/24\n  Known via \"ospf 1\", distance 110, metric 2","neg":"","kind":"cmd"},{"i":149,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"show ip cef <i>ip</i>","synPlain":"show ip cef ip","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض إدخال CEF (Cisco Express Forwarding) — وهو الجدول الفعلي الذي يستخدمه الـ hardware في تمرير الحزم. مفيد عندما يُظهر <code>show ip route</code> مساراً لكن الترافيك لا يمر (عدم تطابق بين RIB وFIB).","en":"Shows the CEF forwarding entry and adjacency actually used to switch the packet.","ex":"<pre><span class=\"p\">R1#</span> show ip cef 192.168.20.5\n192.168.20.0/24, version 12, epoch 0\n  next hop 10.1.1.2 GigabitEthernet0/0</pre>","exPlain":"R1# show ip cef 192.168.20.5\n192.168.20.0/24, version 12, epoch 0\n  next hop 10.1.1.2 GigabitEthernet0/0","neg":"","kind":"cmd"},{"i":150,"sec":"route","no":"08","secAr":"التوجيه الساكن","secEn":"Static Routing","grp":"routing","syn":"ip route <i>network mask</i> null0","synPlain":"ip route network mask null0","mode":"Global Config","modeCls":"m-gconf","ar":"يُنشئ مساراً إلى واجهة <code>Null0</code> — أي «أُسقط الحزم بصمت». يُستخدم لعمل Summary Route يمنع الحلقات (خصوصاً في BGP/EIGRP) أو لفلترة نطاق غير مستخدم. AD له 1 لكنه لا يمرّر شيئاً.","en":"Blackholes a prefix by routing it to the null interface — a common summarisation guard.","ex":"<pre><span class=\"p\">R1(config)#</span> ip route 172.16.0.0 255.255.0.0 null0</pre>","exPlain":"R1(config)# ip route 172.16.0.0 255.255.0.0 null0","neg":"no ip route 172.16.0.0 255.255.0.0 null0","kind":"cmd"},{"i":151,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"router ospf <i>process-id</i>","synPlain":"router ospf process-id","mode":"Global Config","modeCls":"m-gconf","ar":"يشغّل عملية OSPF ويعطيك وضع إعدادها. <b>رقم العملية محلي</b> ولا يجب أن يتطابق بين الراوترات (على عكس رقم AS في EIGRP أو رقم المنطقة). يمكن تشغيل أكثر من عملية على نفس الراوتر لكن ذلك غير مستحسن.","en":"Starts an OSPFv2 process (locally significant) and enters Router Configuration.","ex":"<pre><span class=\"p\">R1(config)#</span> router ospf 1\n<span class=\"p\">R1(config-router)#</span> router-id 1.1.1.1\n<span class=\"p\">R1(config-router)#</span> network 10.1.1.0 0.0.0.255 area 0\n<span class=\"p\">R1(config-router)#</span> network 192.168.10.0 0.0.0.255 area 0</pre>","exPlain":"R1(config)# router ospf 1\nR1(config-router)# router-id 1.1.1.1\nR1(config-router)# network 10.1.1.0 0.0.0.255 area 0\nR1(config-router)# network 192.168.10.0 0.0.0.255 area 0","neg":"no router ospf 1","kind":"cmd"},{"i":152,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"router-id <i>ip-address</i>","synPlain":"router-id ip-address","mode":"Router Config","modeCls":"m-rconf","ar":"يحدد معرّف الراوتر في OSPF بصيغة IPv4. ترتيب الاختيار: ① الأمر الصريح <code>router-id</code>، ② أعلى عنوان IP على أي Loopback، ③ أعلى عنوان IP على أي واجهة فيزيائية. <b>يجب تغييره يدوياً</b> في الإنتاج لضمان الثبات — تغييره يتطلب <code>clear ip ospf process</code>.","en":"Pins the OSPF router-id; without it IOS picks the highest loopback or IP and may change.","ex":"<pre><span class=\"p\">R1(config-router)#</span> router-id 1.1.1.1\n<span class=\"p\">R1#</span> show ip ospf | include ID\nRouting Process \"ospf 1\" with ID 1.1.1.1</pre>","exPlain":"R1(config-router)# router-id 1.1.1.1\nR1# show ip ospf | include ID\nRouting Process \"ospf 1\" with ID 1.1.1.1","neg":"no router-id","kind":"cmd"},{"i":153,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"network <i>network</i> <i>wildcard-mask</i> area <i>area-id</i>","synPlain":"network network wildcard-mask area area-id","mode":"Router Config","modeCls":"m-rconf","ar":"يحدد الواجهات التي تشارك في OSPF والمنطقة التابعة لها. <b>مهم جداً:</b> الأمر لا «يعلن شبكة» كما في RIP، بل يفعّل OSPF على <b>كل واجهة يطابق عنوانها</b> النطاق المحدد. لذلك <code>network 0.0.0.0 255.255.255.255 area 0</code> يفعّل OSPF على كل الواجهات. الـ Wildcard هو مقلوب القناع.","en":"Enables OSPF on every interface matching the network and wildcard, and places it in an area.","ex":"<pre><span class=\"p\">R1(config-router)#</span> network 10.1.1.0 0.0.0.255 area 0\n<span class=\"p\">R1(config-router)#</span> network 192.168.0.0 0.0.255.255 area 1\n<span class=\"p\">R1#</span> show ip ospf interface brief\nInterface  PID  Area  IP Address/Mask  Cost  State\nGi0/0      1    0     10.1.1.1/24      1     DR</pre>","exPlain":"R1(config-router)# network 10.1.1.0 0.0.0.255 area 0\nR1(config-router)# network 192.168.0.0 0.0.255.255 area 1\nR1# show ip ospf interface brief\nInterface  PID  Area  IP Address/Mask  Cost  State\nGi0/0      1    0     10.1.1.1/24      1     DR","neg":"no network 10.1.1.0 0.0.0.255 area 0","kind":"cmd"},{"i":154,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf <i>process-id</i> area <i>area-id</i>","synPlain":"ip ospf process-id area area-id","mode":"Interface Config","modeCls":"m-iconf","ar":"الطريقة الحديثة (Interface-based) لتفعيل OSPF مباشرة على الواجهة دون <code>network</code>. أنظف وأقل خطأً، وهي المفضّلة في التصاميم الجديدة وفي CCNP. لا يمكن الجمع بين الطريقتين على نفس الواجهة.","en":"Enables OSPF directly on the interface — the modern, precise alternative to network statements.","ex":"<pre><span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> ip ospf 1 area 0\n<span class=\"p\">R1(config)#</span> interface g0/1\n<span class=\"p\">R1(config-if)#</span> ip ospf 1 area 1</pre>","exPlain":"R1(config)# interface g0/0\nR1(config-if)# ip ospf 1 area 0\nR1(config)# interface g0/1\nR1(config-if)# ip ospf 1 area 1","neg":"no ip ospf 1 area 0","kind":"cmd"},{"i":155,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"passive-interface <i>{interface | default}</i>","synPlain":"passive-interface {interface | default}","mode":"Router Config","modeCls":"m-rconf","ar":"يمنع إرسال Hello على الواجهة (فتوقف تكوين الجيران) لكنه <b>يُبقي الشبكة معلنة</b> في LSA. يُستخدم على الواجهات المتجهة إلى المستخدمين والـ Loopbacks: أمان + توفير موارد. <code>default</code> يجعل كل الواجهات passive ثم تستثني ما تريد بـ <code>no passive-interface</code>.","en":"Stops Hello packets on an interface while still advertising its subnet.","ex":"<pre><span class=\"p\">R1(config-router)#</span> passive-interface g0/2\n<span class=\"p\">R1(config-router)#</span> passive-interface default\n<span class=\"p\">R1(config-router)#</span> no passive-interface g0/0\n<span class=\"p\">R1#</span> show ip protocols | include passive</pre>","exPlain":"R1(config-router)# passive-interface g0/2\nR1(config-router)# passive-interface default\nR1(config-router)# no passive-interface g0/0\nR1# show ip protocols | include passive","neg":"no passive-interface g0/2","kind":"cmd"},{"i":156,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"auto-cost reference-bandwidth <i>mbps</i>","synPlain":"auto-cost reference-bandwidth mbps","mode":"Router Config","modeCls":"m-rconf","ar":"يغيّر النطاق المرجعي لحساب التكلفة (افتراضي 100 Mbps). المشكلة: كل الروابط أسرع من 100M تحصل على cost = 1، فلا يستطيع OSPF التمييز بين FastEthernet و10Gigabit. الحل: رفعه إلى <b>10000</b> (10G) أو <b>100000</b> (100G). <b>يجب أن يكون موحّداً على كل راوترات النطاق.</b>","en":"Changes the reference bandwidth so costs still differentiate links faster than 100 Mbps.","ex":"<pre><span class=\"p\">R1(config-router)#</span> auto-cost reference-bandwidth 10000\n<span class=\"p\">R1#</span> show ip ospf | include Reference\nReference bandwidth unit is 10000 mbps</pre>","exPlain":"R1(config-router)# auto-cost reference-bandwidth 10000\nR1# show ip ospf | include Reference\nReference bandwidth unit is 10000 mbps","neg":"no auto-cost reference-bandwidth","kind":"cmd"},{"i":157,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf cost <i>value</i>","synPlain":"ip ospf cost value","mode":"Interface Config","modeCls":"m-iconf","ar":"يضبط تكلفة الواجهة يدوياً (<span class=\"num\">1–65535</span>) متجاوزاً الحساب التلقائي. المعادلة الأصلية: cost = reference bandwidth ÷ interface bandwidth. القيمة الأقل تعني مساراً مفضّلاً. تُستخدم للتحكم في مسار الترافيك أو لمحاكاة روابط بطيئة.","en":"Overrides the computed interface cost to steer the SPF tree.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip ospf cost 50\n<span class=\"p\">R1#</span> show ip ospf interface g0/0 | include Cost</pre>","exPlain":"R1(config-if)# ip ospf cost 50\nR1# show ip ospf interface g0/0 | include Cost","neg":"no ip ospf cost","kind":"cmd"},{"i":158,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf hello-interval <i>sec</i> | ip ospf dead-interval <i>sec</i>","synPlain":"ip ospf hello-interval sec | ip ospf dead-interval sec","mode":"Interface Config","modeCls":"m-iconf","ar":"يضبطان توقيتات Hello والموت. <b>يجب أن يتطابقا على طرفي الرابط وإلا لن تتكون الجيرة.</b> الافتراضيات: Broadcast 10/40، Point-to-Point 10/40، NBMA 30/120. قاعدة سريعة: dead = 4 × hello.","en":"Tunes OSPF timers; hello and dead must match on both neighbours (dead defaults to 4x hello).","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip ospf hello-interval 5\n<span class=\"p\">R1(config-if)#</span> ip ospf dead-interval 20\n<span class=\"p\">R1#</span> show ip ospf interface g0/0 | include Hello|Dead</pre>","exPlain":"R1(config-if)# ip ospf hello-interval 5\nR1(config-if)# ip ospf dead-interval 20\nR1# show ip ospf interface g0/0 | include Hello|Dead","neg":"no ip ospf hello-interval","kind":"cmd"},{"i":159,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf priority <i>0-255</i>","synPlain":"ip ospf priority 0-255","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد أولوية انتخاب DR/BDR (افتراضي 1، الأعلى يفوز، والتعادل يُحسم بأعلى Router-ID). القيمة <b>0</b> تعني أن الواجهة لا تشارك في الانتخاب أبداً — تُستخدم على الواجهات المتصلة بالمستخدمين لتجنّب انتخابها DR. الانتخاب <b>غير قسري</b>: تغيير الأولوية لا يطرد DR الحالي.","en":"Sets DR/BDR election priority; 0 makes the interface ineligible to become DR.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip ospf priority 100\n<span class=\"p\">R1#</span> show ip ospf neighbor\nNeighbor ID  Pri  State     Dead Time  Address    Interface\n2.2.2.2      1    FULL/BDR  00:00:35   10.1.1.2   Gi0/0</pre>","exPlain":"R1(config-if)# ip ospf priority 100\nR1# show ip ospf neighbor\nNeighbor ID  Pri  State     Dead Time  Address    Interface\n2.2.2.2      1    FULL/BDR  00:00:35   10.1.1.2   Gi0/0","neg":"no ip ospf priority","kind":"cmd"},{"i":160,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf network <i>{broadcast|point-to-point|non-broadcast|point-to-multipoint}</i>","synPlain":"ip ospf network {broadcast|point-to-point|non-broadcast|point-to-multipoint}","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد نوع شبكة OSPF للواجهة. على روابط Point-to-Point الحقيقية (Serial) يُفضّل <code>point-to-point</code> لأنه يتجاوز انتخاب DR/BDR ويسرّع الالتقاء. على روابط Frame Relay أو Tunnel تُستخدم الخيارات الأخرى.","en":"Declares the interface type, controlling whether a DR is elected and how neighbours are discovered.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip ospf network point-to-point\n<span class=\"p\">R1#</span> show ip ospf interface s0/0/0 | include Network Type</pre>","exPlain":"R1(config-if)# ip ospf network point-to-point\nR1# show ip ospf interface s0/0/0 | include Network Type","neg":"no ip ospf network","kind":"cmd"},{"i":161,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf mtu-ignore","synPlain":"ip ospf mtu-ignore","mode":"Interface Config","modeCls":"m-iconf","ar":"يتجاهل عدم تطابق MTU بين الجارين. OSPF يرفض تكوين الجيرة إذا اختلف MTU (يبقى في حالة ExStart/Exchange)، وهذا شائع جداً في معامل MPLS/Tunnels. استخدام هذا الأمر يحل المشكلة لكنه يخفي سببها الحقيقي.","en":"Ignores the MTU mismatch check that otherwise keeps neighbours stuck in EXSTART.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip ospf mtu-ignore</pre>","exPlain":"R1(config-if)# ip ospf mtu-ignore","neg":"no ip ospf mtu-ignore","kind":"cmd"},{"i":162,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"default-information originate [always] [metric <i>n</i>] [metric-type <i>1|2</i>]","synPlain":"default-information originate [always] [metric n] [metric-type 1|2]","mode":"Router Config","modeCls":"m-rconfig","ar":"يجعل هذا الراوتر يُعلن مساراً افتراضياً داخل OSPF. بدون <code>always</code> لن يُعلن شيئاً إلا إذا كان لديه مسار افتراضي فعلي في جدوله. <code>always</code> يُعلنه حتى لو لم يوجد — وهو مطلوب على راوتر الحدود (ASBR) في كثير من التصاميم. النوع E2 هو الافتراضي.","en":"Injects a default route into OSPF, but only if the router already has one unless always is used.","ex":"<pre><span class=\"p\">R1(config-router)#</span> default-information originate\n<span class=\"p\">R1(config-router)#</span> default-information originate always metric 10 metric-type 1\n<span class=\"p\">R1#</span> show ip route | include 0.0.0.0</pre>","exPlain":"R1(config-router)# default-information originate\nR1(config-router)# default-information originate always metric 10 metric-type 1\nR1# show ip route | include 0.0.0.0","neg":"no default-information originate","kind":"cmd"},{"i":163,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"area <i>area-id</i> range <i>network</i> <i>mask</i>","synPlain":"area area-id range network mask","mode":"Router Config (ABR)","modeCls":"m-rconfig","ar":"تلخيص المسارات بين المناطق (Inter-Area Summary). يُنفَّذ على <b>ABR</b> لتقليل حجم جدول التوجيه في المنطقة 0. مثال: تلخيص 10.1.0.0/16 من أربع شبكات /24. الشرط: أن تكون الشبكات موجودة فعلاً في قاعدة بيانات تلك المنطقة.","en":"Summarises inter-area routes at an ABR, shrinking the LSDB of downstream areas.","ex":"<pre><span class=\"p\">R1(config-router)#</span> area 1 range 10.1.0.0 255.255.0.0\n<span class=\"p\">R1#</span> show ip ospf database summary</pre>","exPlain":"R1(config-router)# area 1 range 10.1.0.0 255.255.0.0\nR1# show ip ospf database summary","neg":"no area 1 range 10.1.0.0 255.255.0.0","kind":"cmd"},{"i":164,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"summary-address <i>network</i> <i>mask</i>","synPlain":"summary-address network mask","mode":"Router Config (ASBR)","modeCls":"m-rconfig","ar":"تلخيص المسارات <b>الخارجية</b> (المُعاد توزيعها) على ASBR. الفرق عن <code>area range</code>: هذا للمسارات الخارجية (LSA 5/7)، وذاك للمسارات الداخلية بين المناطق (LSA 3).","en":"Summarises external routes at an ASBR, covering Type-5 summarisation.","ex":"<pre><span class=\"p\">R1(config-router)#</span> summary-address 172.16.0.0 255.255.0.0</pre>","exPlain":"R1(config-router)# summary-address 172.16.0.0 255.255.0.0","neg":"no summary-address 172.16.0.0 255.255.0.0","kind":"cmd"},{"i":165,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"area <i>area-id</i> stub [no-summary]","synPlain":"area area-id stub [no-summary]","mode":"Router Config","modeCls":"m-rconfig","ar":"يحوّل المنطقة إلى <b>Stub</b>: لا تستقبل LSA 5 (مسارات خارجية) وتستخدم مساراً افتراضياً بدلاً منها. <code>no-summary</code> يجعلها <b>Totally Stubby</b> (تمنع LSA 3 أيضاً). يجب تطبيقها على كل راوترات المنطقة، وكلها يجب أن تكون متصلة بالمنطقة 0.","en":"Blocks Type-5 LSAs from the area; no-summary also blocks Type-3, making it totally stubby.","ex":"<pre><span class=\"p\">R1(config-router)#</span> area 1 stub\n<span class=\"p\">R1(config-router)#</span> area 2 stub no-summary</pre>","exPlain":"R1(config-router)# area 1 stub\nR1(config-router)# area 2 stub no-summary","neg":"no area 1 stub","kind":"cmd"},{"i":166,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"area <i>area-id</i> nssa [default-information-originate]","synPlain":"area area-id nssa [default-information-originate]","mode":"Router Config","modeCls":"m-rconfig","ar":"Not-So-Stubby Area: تمنع LSA 5 لكنها تسمح باستيراد مسارات خارجية بصيغة <b>LSA 7</b> (يُترجمها ABR إلى LSA 5). تُستخدم عندما تحتاج منطقة طرفية أن تُعلن شبكات خارجية (مثل فرع متصل بـ Internet محلي).","en":"Allows external routes as Type-7 LSAs inside the area while still blocking Type-5.","ex":"<pre><span class=\"p\">R1(config-router)#</span> area 3 nssa\n<span class=\"p\">R1(config-router)#</span> area 3 nssa default-information-originate</pre>","exPlain":"R1(config-router)# area 3 nssa\nR1(config-router)# area 3 nssa default-information-originate","neg":"no area 3 nssa","kind":"cmd"},{"i":167,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ip ospf message-digest-key <i>key-id</i> md5 <i>key</i> | ip ospf authentication message-digest","synPlain":"ip ospf message-digest-key key-id md5 key | ip ospf authentication message-digest","mode":"Interface Config","modeCls":"m-iconf","ar":"مصادقة MD5 على مستوى الواجهة (الطريقة الموصى بها). يجب تطبيقها على الطرفين بنفس <b>key-id</b> ونفس <b>key</b>. خلاف ذلك تبقى الجيرة في حالة محاولة فاشلة وتظهر رسالة <code>%OSPF-5-ADJCHG ... Bad authentication type</code>.","en":"Configures MD5 authentication on the interface using a key-id and key.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip ospf message-digest-key 1 md5 Ospf@123\n<span class=\"p\">R1(config-if)#</span> ip ospf authentication message-digest\n<span class=\"p\">R1#</span> show ip ospf interface g0/0 | include auth</pre>","exPlain":"R1(config-if)# ip ospf message-digest-key 1 md5 Ospf@123\nR1(config-if)# ip ospf authentication message-digest\nR1# show ip ospf interface g0/0 | include auth","neg":"no ip ospf authentication message-digest","kind":"cmd"},{"i":168,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"area <i>area-id</i> authentication message-digest","synPlain":"area area-id authentication message-digest","mode":"Router Config","modeCls":"m-rconfig","ar":"يفعّل المصادقة على كل واجهات المنطقة (الطريقة القديمة). بعدها ما زلت تحتاج <code>ip ospf message-digest-key</code> على كل واجهة. الطريقة الأحدث (per-interface) تتفوق لأنها أكثر مرونة.","en":"Turns on MD5 authentication for the whole area instead of per interface.","ex":"<pre><span class=\"p\">R1(config-router)#</span> area 0 authentication message-digest</pre>","exPlain":"R1(config-router)# area 0 authentication message-digest","neg":"no area 0 authentication","kind":"cmd"},{"i":169,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ipv6 router ospf <i>pid</i> | ipv6 ospf <i>pid</i> area <i>id</i>","synPlain":"ipv6 router ospf pid | ipv6 ospf pid area id","mode":"Global / Interface","modeCls":"m-gconf","ar":"تشغيل OSPFv3 للـ IPv6. يُفعّل على الواجهة مباشرة (لا يوجد <code>network</code> في OSPFv3). يجب تفعيل <code>ipv6 unicast-routing</code> أولاً. الجيران يتكونون عبر عناوين <b>Link-Local</b> وليس العناوين العامة.","en":"Starts OSPFv3 and enables it per interface — OSPFv3 has no network statement.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 unicast-routing\n<span class=\"p\">R1(config)#</span> ipv6 router ospf 1\n<span class=\"p\">R1(config-rtr)#</span> router-id 1.1.1.1\n<span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> ipv6 ospf 1 area 0</pre>","exPlain":"R1(config)# ipv6 unicast-routing\nR1(config)# ipv6 router ospf 1\nR1(config-rtr)# router-id 1.1.1.1\nR1(config)# interface g0/0\nR1(config-if)# ipv6 ospf 1 area 0","neg":"no ipv6 router ospf 1","kind":"cmd"},{"i":170,"sec":"ospf","no":"09","secAr":"OSPF","secEn":"OSPF","grp":"routing","syn":"ipv6 ospf authentication ipsec spi <i>spi</i> <i>sha1|md5</i> <i>key</i>","synPlain":"ipv6 ospf authentication ipsec spi spi sha1|md5 key","mode":"Interface Config","modeCls":"m-iconf","ar":"مصادقة OSPFv3 عبر IPsec (لأن OSPFv3 لا يحمل حقل مصادقة خاصاً به في البروتوكول الأصلي). تحتاج SPI (Security Parameter Index) متطابقاً ومفتاحاً متطابقاً على الطرفين.","en":"Secures OSPFv3 with IPsec AH or ESP, since OSPFv3 authentication is not built in.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 ospf authentication ipsec spi 500 sha1 0123456789ABCDEF0123456789ABCDEF01234567</pre>","exPlain":"R1(config-if)# ipv6 ospf authentication ipsec spi 500 sha1 0123456789ABCDEF0123456789ABCDEF01234567","neg":"no ipv6 ospf authentication","kind":"cmd"},{"i":171,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"router eigrp <i>as-number</i>","synPlain":"router eigrp as-number","mode":"Global Config","modeCls":"m-gconf","ar":"يشغّل عملية EIGRP. <b>رقم AS يجب أن يتطابق على كل الراوترات</b> التي تريدها أن تتجاور (على عكس OSPF حيث رقم العملية محلي). راوتران برقمين مختلفين لا يتحدثان إطلاقاً.","en":"Starts classic EIGRP with an autonomous-system number that must match on all neighbours.","ex":"<pre><span class=\"p\">R1(config)#</span> router eigrp 100\n<span class=\"p\">R1(config-router)#</span> network 10.1.1.0 0.0.0.255\n<span class=\"p\">R1(config-router)#</span> network 192.168.10.0 0.0.0.255\n<span class=\"p\">R1(config-router)#</span> no auto-summary</pre>","exPlain":"R1(config)# router eigrp 100\nR1(config-router)# network 10.1.1.0 0.0.0.255\nR1(config-router)# network 192.168.10.0 0.0.0.255\nR1(config-router)# no auto-summary","neg":"no router eigrp 100","kind":"cmd"},{"i":172,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"network <i>network</i> [<i>wildcard-mask</i>]","synPlain":"network network [wildcard-mask]","mode":"Router Config","modeCls":"m-rconfig","ar":"يفعّل EIGRP على الواجهات المطابقة ويعلن شبكاتها. بدون wildcard يُستخدم الصنف الكامل (Classful) — وهو سلوك قديم يعلن شبكة كاملة. <b>الأفضل دائماً</b> كتابة الـ wildcard صراحة لتجنّب إعلان شبكات غير مقصودة.","en":"Enables EIGRP on matching interfaces and advertises their connected subnets.","ex":"<pre><span class=\"p\">R1(config-router)#</span> network 10.1.1.0 0.0.0.255\n<span class=\"p\">R1(config-router)#</span> network 0.0.0.0\n<span class=\"p\">R1#</span> show ip eigrp interfaces</pre>","exPlain":"R1(config-router)# network 10.1.1.0 0.0.0.255\nR1(config-router)# network 0.0.0.0\nR1# show ip eigrp interfaces","neg":"no network 10.1.1.0 0.0.0.255","kind":"cmd"},{"i":173,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"no auto-summary","synPlain":"no auto-summary","mode":"Router Config","modeCls":"m-rconfig","ar":"يمنع التلخيص التلقائي على حدود الشبكات الصنفية (Classful boundaries). في الإصدارات 12.4 وما بعدها هو <b>معطّل افتراضياً</b>، لكن كتابته صراحة ضرورة في المعامل والأسئلة لأنه يمنع مشاكل التوجيه عند وجود شبكات غير متصلة (Discontiguous Networks).","en":"Disables classful summarisation at the major-network boundary (off by default since 12.4).","ex":"<pre><span class=\"p\">R1(config-router)#</span> no auto-summary\n<span class=\"p\">R1#</span> show ip protocols | include Auto</pre>","exPlain":"R1(config-router)# no auto-summary\nR1# show ip protocols | include Auto","neg":"auto-summary","kind":"cmd"},{"i":174,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"eigrp router-id <i>ip</i>","synPlain":"eigrp router-id ip","mode":"Router Config","modeCls":"m-rconfig","ar":"يحدد Router-ID لعملية EIGRP. ترتيب الاختيار: الأمر الصريح، ثم أعلى IP على Loopback، ثم أعلى IP على واجهة نشطة. <b>يجب أن يكون فريداً</b> في النطاق، وإلا ترفض الجيرة التكوين.","en":"Pins the EIGRP router-id so the highest-IP election cannot change after a reload.","ex":"<pre><span class=\"p\">R1(config-router)#</span> eigrp router-id 1.1.1.1</pre>","exPlain":"R1(config-router)# eigrp router-id 1.1.1.1","neg":"no eigrp router-id","kind":"cmd"},{"i":175,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"passive-interface <i>{interface|default}</i>","synPlain":"passive-interface {interface|default}","mode":"Router Config","modeCls":"m-rconfig","ar":"يمنع إرسال Hellos على الواجهة (لا جيران) مع بقاء الشبكة معلنة. يُستخدم على واجهات المستخدمين والـ Loopbacks. مفيد أيضاً لتقليل استهلاك النطاق على روابط WAN منخفضة السرعة.","en":"Suppresses Hellos on an interface while still advertising its network.","ex":"<pre><span class=\"p\">R1(config-router)#</span> passive-interface g0/2\n<span class=\"p\">R1(config-router)#</span> passive-interface default\n<span class=\"p\">R1(config-router)#</span> no passive-interface g0/0</pre>","exPlain":"R1(config-router)# passive-interface g0/2\nR1(config-router)# passive-interface default\nR1(config-router)# no passive-interface g0/0","neg":"no passive-interface g0/2","kind":"cmd"},{"i":176,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"variance <i>multiplier</i>","synPlain":"variance multiplier","mode":"Router Config","modeCls":"m-rconfig","ar":"يسمح بتثبيت مسارات ذات مترية أعلى (أسوأ) بشرط أن تكون ≤ (مترية المسار الأفضل × variance)، وأن تستوفي <b>شرط الجدوى</b> (RD للمسار البديل < FD للمسار الأساسي). مثال: الأفضل 1000، variance 2 → يُثبَّت أي مسار حتى 2000. بدون استيفاء شرط الجدوى لن يعمل variance مهما كبر.","en":"Allows unequal-cost load balancing over feasible successors up to N times the best metric.","ex":"<pre><span class=\"p\">R1(config-router)#</span> variance 2\n<span class=\"p\">R1#</span> show ip route 192.168.30.0\n  192.168.30.0/24, 2 successors, FD is 3072\n    via 10.1.1.2 (3072/2816)\n    via 10.1.2.2 (5376/5120)</pre>","exPlain":"R1(config-router)# variance 2\nR1# show ip route 192.168.30.0\n  192.168.30.0/24, 2 successors, FD is 3072\n    via 10.1.1.2 (3072/2816)\n    via 10.1.2.2 (5376/5120)","neg":"no variance","kind":"cmd"},{"i":177,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"maximum-paths <i>n</i>","synPlain":"maximum-paths n","mode":"Router Config","modeCls":"m-rconfig","ar":"أقصى عدد مسارات متساوية المترية تُثبَّت في جدول التوجيه (افتراضي 4، حتى 32 حسب المنصة). يختلف عن variance: هذا للمسارات <b>المتساوية</b> فقط.","en":"Sets how many equal-cost paths EIGRP installs in the routing table (default 4).","ex":"<pre><span class=\"p\">R1(config-router)#</span> maximum-paths 6</pre>","exPlain":"R1(config-router)# maximum-paths 6","neg":"no maximum-paths","kind":"cmd"},{"i":178,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"metric weights <i>tos k1 k2 k3 k4 k5</i>","synPlain":"metric weights tos k1 k2 k3 k4 k5","mode":"Router Config","modeCls":"m-rconfig","ar":"يغيّر أوزان المترية (K-values). <b>يجب أن تتطابق على كل الراوترات</b> وإلا فشلت الجيرة برسالة <code>K-value mismatch</code>. نادراً ما تُستخدم عملياً، وتظهر في CCNP كسؤال مفهومي.","en":"Tunes the K-values of the composite metric; they must match on every neighbour.","ex":"<pre><span class=\"p\">R1(config-router)#</span> metric weights 0 1 0 1 0 0</pre>","exPlain":"R1(config-router)# metric weights 0 1 0 1 0 0","neg":"تحذير لا تغيّرها إلا على كل الأجهزة في النطاق","kind":"cmd"},{"i":179,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"ip hello-interval eigrp <i>as</i> <i>sec</i> | ip hold-time eigrp <i>as</i> <i>sec</i>","synPlain":"ip hello-interval eigrp as sec | ip hold-time eigrp as sec","mode":"Interface Config","modeCls":"m-iconf","ar":"يضبطان مؤقّتات EIGRP على الواجهة. الافتراضي: Hello = 5s وHold = 15s على الروابط عالية السرعة، و60s/180s على الروابط بطيئة (أقل من T1). <b>يجب التطابق</b> على الطرفين وإلا لن تتكون الجيرة.","en":"Tunes EIGRP timers; hold time is normally three times the hello interval.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip hello-interval eigrp 100 5\n<span class=\"p\">R1(config-if)#</span> ip hold-time eigrp 100 15</pre>","exPlain":"R1(config-if)# ip hello-interval eigrp 100 5\nR1(config-if)# ip hold-time eigrp 100 15","neg":"no ip hello-interval eigrp 100","kind":"cmd"},{"i":180,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"ip bandwidth-percent eigrp <i>as</i> <i>percent</i>","synPlain":"ip bandwidth-percent eigrp as percent","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد نسبة النطاق المسموح لـ EIGRP من bandwidth الواجهة (افتراضي 50%). يُخفَّض على الروابط منخفضة السرعة جداً (مثل روابط الأقمار الصناعية) حيث تكون حزم Hello والـ updates عبئاً ملحوظاً.","en":"Caps how much of the interface bandwidth EIGRP may claim (default 50%).","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip bandwidth-percent eigrp 100 20</pre>","exPlain":"R1(config-if)# ip bandwidth-percent eigrp 100 20","neg":"no ip bandwidth-percent eigrp 100","kind":"cmd"},{"i":181,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"key chain <i>name</i> | key <i>n</i> | key-string <i>pass</i>","synPlain":"key chain name | key n | key-string pass","mode":"Global Config","modeCls":"m-gconf","ar":"يبني سلسلة مفاتيح للمصادقة (MD5/SHA). يمكن تعريف عدة مفاتيح بفترات صلاحية للتدوير الآمن دون انقطاع. المفتاح المستخدم حالياً يجب أن يتطابق على الطرفين.","en":"Builds the key chain used to authenticate routing updates.","ex":"<pre><span class=\"p\">R1(config)#</span> key chain EIGRP-KEYS\n<span class=\"p\">R1(config-keychain)#</span> key 1\n<span class=\"p\">R1(config-keychain-key)#</span> key-string Eigrp@123\n<span class=\"p\">R1(config-keychain-key)#</span> accept-lifetime 00:00:00 Jan 1 2026 infinite\n<span class=\"p\">R1(config-keychain-key)#</span> send-lifetime 00:00:00 Jan 1 2026 infinite</pre>","exPlain":"R1(config)# key chain EIGRP-KEYS\nR1(config-keychain)# key 1\nR1(config-keychain-key)# key-string Eigrp@123\nR1(config-keychain-key)# accept-lifetime 00:00:00 Jan 1 2026 infinite\nR1(config-keychain-key)# send-lifetime 00:00:00 Jan 1 2026 infinite","neg":"no key chain EIGRP-KEYS","kind":"cmd"},{"i":182,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"ip authentication mode eigrp <i>as</i> md5 | ip authentication key-chain eigrp <i>as</i> <i>name</i>","synPlain":"ip authentication mode eigrp as md5 | ip authentication key-chain eigrp as name","mode":"Interface Config","modeCls":"m-iconf","ar":"يفعّل المصادقة على الواجهة ويربطها بسلسلة المفاتيح. أمران يجب تنفيذهما معاً — نسيان أحدهما يجعل الواجهة بلا مصادقة فعّالة. بعد التفعيل تظهر رسالة نجاح الجيرة فقط إذا تطابقت المفاتيح.","en":"Enables MD5 authentication for EIGRP and binds it to the key chain.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip authentication mode eigrp 100 md5\n<span class=\"p\">R1(config-if)#</span> ip authentication key-chain eigrp 100 EIGRP-KEYS\n<span class=\"p\">R1#</span> show ip eigrp interfaces detail | include auth</pre>","exPlain":"R1(config-if)# ip authentication mode eigrp 100 md5\nR1(config-if)# ip authentication key-chain eigrp 100 EIGRP-KEYS\nR1# show ip eigrp interfaces detail | include auth","neg":"no ip authentication mode eigrp 100","kind":"cmd"},{"i":183,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"router eigrp <i>name</i> | address-family ipv4 autonomous-system <i>as</i>","synPlain":"router eigrp name | address-family ipv4 autonomous-system as","mode":"Global Config","modeCls":"m-gconf","ar":"الوضع المسمّى (Named Mode) هو الأسلوب الحديث في IOS 15+ وIOS-XE: يجمع كل إعدادات EIGRP (العامة، الواجهات،AF) تحت اسم واحد، ويدعم IPv4 وIPv6 وVRF في وقت واحد. كل الأوامر القديمة لها مقابل هنا.","en":"Configures EIGRP in named mode, the modern structure supporting IPv4, IPv6, and per-AF settings.","ex":"<pre><span class=\"p\">R1(config)#</span> router eigrp CORP\n<span class=\"p\">R1(config-router)#</span> address-family ipv4 autonomous-system 100\n<span class=\"p\">R1(config-router-af)#</span> network 10.1.1.0 0.0.0.255\n<span class=\"p\">R1(config-router-af)#</span> eigrp router-id 1.1.1.1\n<span class=\"p\">R1(config-router-af)#</span> af-interface default\n<span class=\"p\">R1(config-router-af-interface)#</span> passive-interface\n<span class=\"p\">R1(config-router-af-interface)#</span> exit-af-interface\n<span class=\"p\">R1(config-router-af)#</span> af-interface g0/0\n<span class=\"p\">R1(config-router-af-interface)#</span> no passive-interface\n<span class=\"p\">R1(config-router-af-interface)#</span> authentication mode md5\n<span class=\"p\">R1(config-router-af-interface)#</span> authentication key-chain EIGRP-KEYS</pre>","exPlain":"R1(config)# router eigrp CORP\nR1(config-router)# address-family ipv4 autonomous-system 100\nR1(config-router-af)# network 10.1.1.0 0.0.0.255\nR1(config-router-af)# eigrp router-id 1.1.1.1\nR1(config-router-af)# af-interface default\nR1(config-router-af-interface)# passive-interface\nR1(config-router-af-interface)# exit-af-interface\nR1(config-router-af)# af-interface g0/0\nR1(config-router-af-interface)# no passive-interface\nR1(config-router-af-interface)# authentication mode md5\nR1(config-router-af-interface)# authentication key-chain EIGRP-KEYS","neg":"no router eigrp CORP","kind":"cmd"},{"i":184,"sec":"eigrp","no":"10","secAr":"EIGRP","secEn":"EIGRP","grp":"routing","syn":"eigrp stub <i>{connected|static|summary|receive-only}</i>","synPlain":"eigrp stub {connected|static|summary|receive-only}","mode":"Router Config","modeCls":"m-rconfig","ar":"يجعل الراوتر «Stub» — أي لا يُسأل عن مسارات بعيدة، فيُقلّل استعلامات EIGRP وحجم التحديثات. مثالي للفروع. الافتراضي يعلن <code>connected</code> و<code>summary</code>. لا تستخدمه على راوتر عبور (Transit).","en":"Marks the router as a stub so it advertises only the selected route types and limits query scope.","ex":"<pre><span class=\"p\">R1(config-router)#</span> eigrp stub connected summary\n<span class=\"p\">R1#</span> show ip eigrp neighbors detail</pre>","exPlain":"R1(config-router)# eigrp stub connected summary\nR1# show ip eigrp neighbors detail","neg":"no eigrp stub","kind":"cmd"},{"i":185,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"router rip | version 2 | network <i>classful-network</i>","synPlain":"router rip | version 2 | network classful-network","mode":"Global Config","modeCls":"m-gconf","ar":"يشغّل RIP. <b>الإصدار 2 ضروري</b> لأنه يدعم VLSM ويرسل القناع مع التحديث (RIPv1 صنفي ولا يدعمه). لاحظ أن <code>network</code> في RIP يأخذ <b>الشبكة الصنفية فقط</b> (مثل <code>network 10.0.0.0</code>) ولا يقبل wildcard — وهذا فرق جوهري عن OSPF/EIGRP.","en":"Starts RIPv2 and enables it on classful networks; version 2 sends the mask with every route.","ex":"<pre><span class=\"p\">R1(config)#</span> router rip\n<span class=\"p\">R1(config-router)#</span> version 2\n<span class=\"p\">R1(config-router)#</span> no auto-summary\n<span class=\"p\">R1(config-router)#</span> network 10.0.0.0\n<span class=\"p\">R1(config-router)#</span> network 192.168.10.0</pre>","exPlain":"R1(config)# router rip\nR1(config-router)# version 2\nR1(config-router)# no auto-summary\nR1(config-router)# network 10.0.0.0\nR1(config-router)# network 192.168.10.0","neg":"no router rip","kind":"cmd"},{"i":186,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"timers basic <i>update</i> <i>invalid</i> <i>holddown</i> <i>flush</i>","synPlain":"timers basic update invalid holddown flush","mode":"Router Config","modeCls":"m-rconfig","ar":"يضبط مؤقّتات RIP بالثواني. الافتراضيات: update 30، invalid 180، holddown 180، flush 240. <b>يجب أن تتطابق على كل الراوترات</b> وإلا أصبحت الشبكة غير مستقرة. لا تُغيّرها في الإنتاج.","en":"Changes the RIP update, invalid, holddown, and flush timers (default 30/180/180/240).","ex":"<pre><span class=\"p\">R1(config-router)#</span> timers basic 30 180 180 240</pre>","exPlain":"R1(config-router)# timers basic 30 180 180 240","neg":"no timers basic","kind":"cmd"},{"i":187,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"passive-interface <i>interface</i> | default-information originate","synPlain":"passive-interface interface | default-information originate","mode":"Router Config","modeCls":"m-rconfig","ar":"<code>passive-interface</code> يمنع إرسال تحديثات RIP على الواجهة (لكنه يعلن شبكتها). و<code>default-information originate</code> يجعل RIP يبثّ مساراً افتراضياً — وهو ضروري لأن RIP لا ينقل المسار الافتراضي تلقائياً.","en":"Silences RIP on an interface, or injects a default route into RIP.","ex":"<pre><span class=\"p\">R1(config-router)#</span> passive-interface g0/2\n<span class=\"p\">R1(config-router)#</span> default-information originate\n<span class=\"p\">R1(config-router)#</span> offset-list 1 in 2 g0/0</pre>","exPlain":"R1(config-router)# passive-interface g0/2\nR1(config-router)# default-information originate\nR1(config-router)# offset-list 1 in 2 g0/0","neg":"no passive-interface g0/2","kind":"cmd"},{"i":188,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"redistribute <i>{connected|static|ospf <i>pid</i>|eigrp <i>as</i>|rip}</i> [subnets] [metric <i>n</i>] [metric-type <i>1|2</i>] [route-map <i>name</i>]","synPlain":"redistribute {connected|static|ospf pid|eigrp as|rip} [subnets] [metric n] [metric-type 1|2] [route-map name]","mode":"Router Config","modeCls":"m-rconfig","ar":"يحقن مسارات من مصدر آخر داخل البروتوكول الحالي. أربع قواعد لا تُنسى:","en":"Injects routes from another protocol or source into the routing process.","ex":"<pre><span class=\"p\">R1(config)#</span> router ospf 1\n<span class=\"p\">R1(config-router)#</span> redistribute eigrp 100 subnets metric 20 metric-type 1\n<span class=\"p\">R1(config-router)#</span> redistribute static subnets\n<span class=\"p\">R1(config)#</span> router eigrp 100\n<span class=\"p\">R1(config-router)#</span> redistribute ospf 1 metric 10000 100 255 1 1500</pre>","exPlain":"R1(config)# router ospf 1\nR1(config-router)# redistribute eigrp 100 subnets metric 20 metric-type 1\nR1(config-router)# redistribute static subnets\nR1(config)# router eigrp 100\nR1(config-router)# redistribute ospf 1 metric 10000 100 255 1 1500","neg":"no redistribute eigrp 100 subnets","kind":"cmd"},{"i":189,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"default-metric <i>bandwidth delay reliability load mtu</i>","synPlain":"default-metric bandwidth delay reliability load mtu","mode":"Router Config","modeCls":"m-rconfig","ar":"يحدد المترية الافتراضية لكل المسارات المُعاد توزيعها في EIGRP/RIP، بدلاً من كتابتها في كل أمر <code>redistribute</code>. في EIGRP الترتيب: bandwidth (kbps) delay (عشرات الميكروثانية) reliability load MTU.","en":"Supplies the seed metric for redistributed routes when the source protocol has none.","ex":"<pre><span class=\"p\">R1(config-router)#</span> default-metric 10000 100 255 1 1500</pre>","exPlain":"R1(config-router)# default-metric 10000 100 255 1 1500","neg":"no default-metric","kind":"cmd"},{"i":190,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"distribute-list <i>{acl|prefix-list name}</i> <i>{in|out}</i> [<i>interface</i>]","synPlain":"distribute-list {acl|prefix-list name} {in|out} [interface]","mode":"Router Config","modeCls":"m-rconfig","ar":"يفلتر المسارات (وليس الحزم) عند الدخول أو الخروج من عملية التوجيه. <code>in</code> يمنع تعلّم مسارات معيّنة، و<code>out</code> يمنع إعلانها. مع <code>prefix-list</code> يصبح التحكم أدق بكثير من ACL.","en":"Filters which routes are accepted or advertised, per interface and direction.","ex":"<pre><span class=\"p\">R1(config)#</span> ip prefix-list ALLOW-10 seq 5 permit 10.0.0.0/8 le 24\n<span class=\"p\">R1(config)#</span> router ospf 1\n<span class=\"p\">R1(config-router)#</span> distribute-list prefix ALLOW-10 in g0/0</pre>","exPlain":"R1(config)# ip prefix-list ALLOW-10 seq 5 permit 10.0.0.0/8 le 24\nR1(config)# router ospf 1\nR1(config-router)# distribute-list prefix ALLOW-10 in g0/0","neg":"no distribute-list prefix ALLOW-10 in g0/0","kind":"cmd"},{"i":191,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"ip prefix-list <i>name</i> [seq <i>n</i>] <i>{permit|deny}</i> <i>prefix/len</i> [ge <i>x</i>] [le <i>y</i>]","synPlain":"ip prefix-list name [seq n] {permit|deny} prefix/len [ge x] [le y]","mode":"Global Config","modeCls":"m-gconf","ar":"أداة فلترة المسارات الأدق. <code>ge</code> (greater-or-equal) و<code>le</code> (less-or-equal) يحددان نطاق أطوال القناع المقبولة. مثال: <code>10.0.0.0/8 le 24</code> يقبل كل بادئة تبدأ بـ 10.0.0.0 وقناعها بين /8 و/24. بدون <code>ge/le</code> يطابق البادئة والطول بدقة تامة.","en":"Builds a prefix list that matches on prefix length with ge and le ranges, far more precise than an ACL.","ex":"<pre><span class=\"p\">R1(config)#</span> ip prefix-list PL-1 seq 5 deny 10.1.1.0/24\n<span class=\"p\">R1(config)#</span> ip prefix-list PL-1 seq 10 permit 10.0.0.0/8 le 24\n<span class=\"p\">R1(config)#</span> ip prefix-list PL-1 seq 15 permit 0.0.0.0/0\n<span class=\"p\">R1#</span> show ip prefix-list PL-1</pre>","exPlain":"R1(config)# ip prefix-list PL-1 seq 5 deny 10.1.1.0/24\nR1(config)# ip prefix-list PL-1 seq 10 permit 10.0.0.0/8 le 24\nR1(config)# ip prefix-list PL-1 seq 15 permit 0.0.0.0/0\nR1# show ip prefix-list PL-1","neg":"no ip prefix-list PL-1","kind":"cmd"},{"i":192,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"route-map <i>name</i> <i>{permit|deny}</i> <i>seq</i> | match | set","synPlain":"route-map name {permit|deny} seq | match | set","mode":"Global Config","modeCls":"m-gconf","ar":"أداة السياسات العامة: تُطابق شروطاً (<code>match</code>) ثم تُنفّذ إجراءات (<code>set</code>). تُستخدم في إعادة التوزيع، BGP، PBR، NAT. القواعد: ① لا يوجد <b>deny implicit</b> — إن لم يطابق أي بند يُرفض المسار. ② يجب وجود <code>permit</code> صريح في النهاية. ③ عدة شروط <code>match</code> في نفس البند = AND.","en":"Creates an ordered policy used by redistribution, BGP, and policy-based routing.","ex":"<pre><span class=\"p\">R1(config)#</span> route-map RM-OSPF permit 10\n<span class=\"p\">R1(config-route-map)#</span> match ip address prefix-list PL-1\n<span class=\"p\">R1(config-route-map)#</span> set metric 50\n<span class=\"p\">R1(config-route-map)#</span> set metric-type type-1\n<span class=\"p\">R1(config)#</span> router ospf 1\n<span class=\"p\">R1(config-router)#</span> redistribute eigrp 100 subnets route-map RM-OSPF</pre>","exPlain":"R1(config)# route-map RM-OSPF permit 10\nR1(config-route-map)# match ip address prefix-list PL-1\nR1(config-route-map)# set metric 50\nR1(config-route-map)# set metric-type type-1\nR1(config)# router ospf 1\nR1(config-router)# redistribute eigrp 100 subnets route-map RM-OSPF","neg":"no route-map RM-OSPF permit 10","kind":"cmd"},{"i":193,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"match <i>ip address|interface|metric|route-type|tag</i> | set <i>metric|metric-type|tag|next-hop</i>","synPlain":"match ip address|interface|metric|route-type|tag | set metric|metric-type|tag|next-hop","mode":"Route-map Config","modeCls":"m-rmap","ar":"شروط المطابقة والإجراءات. <code>tag</code> أداة قوية لمنع الحلقات في إعادة التوزيع ثنائية الاتجاه: ضع tag عند التوزيع الأول، ثم امنع استقبال المسارات التي تحمل نفس الـ tag عند التوزيع العكسي.","en":"Defines the conditions a route must meet and the attributes to change when it does.","ex":"<pre><span class=\"p\">R1(config-route-map)#</span> match ip address 10\n<span class=\"p\">R1(config-route-map)#</span> match interface g0/0\n<span class=\"p\">R1(config-route-map)#</span> set tag 100\n<span class=\"p\">R1(config-route-map)#</span> set next-hop 10.1.1.2</pre>","exPlain":"R1(config-route-map)# match ip address 10\nR1(config-route-map)# match interface g0/0\nR1(config-route-map)# set tag 100\nR1(config-route-map)# set next-hop 10.1.1.2","neg":"no match ip address 10","kind":"cmd"},{"i":194,"sec":"rip","no":"11","secAr":"RIP وإعادة التوزيع","secEn":"RIP & Redistribution","grp":"routing","syn":"distance <i>admin-distance</i> <i>source-ip</i> <i>wildcard</i> [<i>acl</i>]","synPlain":"distance admin-distance source-ip wildcard [acl]","mode":"Router Config","modeCls":"m-rconfig","ar":"يغيّر المسافة الإدارية لمسارات قادمة من مصدر محدد — أسلوب بديل لـ floating static في التحكم بالأفضلية. مثال: جعل مسارات OSPF القادمة من جار معيّن أقل ثقة من مسارات RIP.","en":"Changes administrative distance for routes from a specific neighbour — a manual preference knob.","ex":"<pre><span class=\"p\">R1(config-router)#</span> distance 200 10.1.1.2 0.0.0.0</pre>","exPlain":"R1(config-router)# distance 200 10.1.1.2 0.0.0.0","neg":"no distance 200 10.1.1.2 0.0.0.0","kind":"cmd"},{"i":195,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"router bgp <i>local-as</i>","synPlain":"router bgp local-as","mode":"Global Config","modeCls":"m-gconf","ar":"يشغّل عملية BGP برقم AS محلي (<span class=\"num\">1–65535</span>، والمدى <span class=\"num\">64512–65534</span> خاص/Private). الرقم يحدد نوع الجيرة: نفس الرقم = <b>iBGP</b>، رقم مختلف = <b>eBGP</b>.","en":"Starts the BGP process with this router's autonomous system number.","ex":"<pre><span class=\"p\">R1(config)#</span> router bgp 65001\n<span class=\"p\">R1(config-router)#</span> bgp router-id 1.1.1.1\n<span class=\"p\">R1(config-router)#</span> bgp log-neighbor-changes\n<span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 remote-as 65002</pre>","exPlain":"R1(config)# router bgp 65001\nR1(config-router)# bgp router-id 1.1.1.1\nR1(config-router)# bgp log-neighbor-changes\nR1(config-router)# neighbor 10.1.1.2 remote-as 65002","neg":"no router bgp 65001","kind":"cmd"},{"i":196,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> remote-as <i>as-number</i>","synPlain":"neighbor ip remote-as as-number","mode":"Router Config","modeCls":"m-rconfig","ar":"ينشئ جيرة BGP مع عنوان محدد ويحدد AS الطرف الآخر. <b>يجب أن يتطابق</b> رقم AS المُعلن مع رقم AS المُعدّ على الطرف المقابل، وإلا بقيت الحالة في <code>Active</code> أو <code>Idle</code>. BGP لا يكتشف الجيران تلقائياً — يجب تعريف كل جار يدوياً.","en":"Declares a BGP peer and its AS; iBGP if the AS matches, eBGP otherwise.","ex":"<pre><span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 remote-as 65002\n<span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 description ISP-Primary\n<span class=\"p\">R1#</span> show ip bgp summary</pre>","exPlain":"R1(config-router)# neighbor 10.1.1.2 remote-as 65002\nR1(config-router)# neighbor 10.1.1.2 description ISP-Primary\nR1# show ip bgp summary","neg":"no neighbor 10.1.1.2 remote-as 65002","kind":"cmd"},{"i":197,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"network <i>network</i> mask <i>subnet-mask</i>","synPlain":"network network mask subnet-mask","mode":"Router Config","modeCls":"m-rconfig","ar":"يعلن بادئة في BGP. <b>شرط أساسي:</b> يجب أن تكون البادئة موجودة في جدول التوجيه (من <code>connected</code> أو <code>static</code> أو IGP) وإلا فلن تُعلن. هذا يختلف عن OSPF/EIGRP حيث <code>network</code> يفعّل البروتوكول على الواجهة. الحل الشائع: <code>ip route &lt;net&gt; &lt;mask&gt; null0</code> أو <code>network ... route-map</code>.","en":"Originates a prefix into BGP; the exact prefix must already exist in the routing table.","ex":"<pre><span class=\"p\">R1(config-router)#</span> network 203.0.113.0 mask 255.255.255.0\n<span class=\"p\">R1#</span> show ip bgp\nBGP table version is 3\n*&gt; 203.0.113.0/24  0.0.0.0  0  32768  i</pre>","exPlain":"R1(config-router)# network 203.0.113.0 mask 255.255.255.0\nR1# show ip bgp\nBGP table version is 3\n*> 203.0.113.0/24  0.0.0.0  0  32768  i","neg":"no network 203.0.113.0 mask 255.255.255.0","kind":"cmd"},{"i":198,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> update-source <i>interface</i>","synPlain":"neighbor ip update-source interface","mode":"Router Config","modeCls":"m-rconfig","ar":"يحدد عنوان المصدر لجلسة TCP (المنفذ 179). ضروري في iBGP: الجيران يُعرَّفون بعنوان Loopback، فيجب أن تكون الجلسة صادرة من نفس العنوان وإلا فشل الاتصال.","en":"Forces TCP updates to use a specific interface, usually a loopback, for stability.","ex":"<pre><span class=\"p\">R1(config-router)#</span> neighbor 2.2.2.2 remote-as 65001\n<span class=\"p\">R1(config-router)#</span> neighbor 2.2.2.2 update-source loopback 0</pre>","exPlain":"R1(config-router)# neighbor 2.2.2.2 remote-as 65001\nR1(config-router)# neighbor 2.2.2.2 update-source loopback 0","neg":"no neighbor 2.2.2.2 update-source","kind":"cmd"},{"i":199,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> next-hop-self","synPlain":"neighbor ip next-hop-self","mode":"Router Config","modeCls":"m-rconfig","ar":"يجعل الراوتر يعلن نفسه كـ next-hop للجيران iBGP بدلاً من تمرير next-hop الأصلي. <b>مشكلة حقيقية:</b> في iBGP لا يُغيَّر next-hop تلقائياً، فإذا كان المسار قادماً من eBGP فقد لا يستطيع الجار الداخلي الوصول إلى ذلك العنوان الخارجي. الحل: <code>next-hop-self</code> على راوتر الحدود.","en":"Rewrites the next hop to itself when advertising to an iBGP peer, fixing unreachable next hops.","ex":"<pre><span class=\"p\">R1(config-router)#</span> neighbor 2.2.2.2 next-hop-self</pre>","exPlain":"R1(config-router)# neighbor 2.2.2.2 next-hop-self","neg":"no neighbor 2.2.2.2 next-hop-self","kind":"cmd"},{"i":200,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> password <i>pass</i> | neighbor <i>ip</i> shutdown","synPlain":"neighbor ip password pass | neighbor ip shutdown","mode":"Router Config","modeCls":"m-rconfig","ar":"<code>password</code> يفعّل مصادقة TCP MD5 (يجب تطابقها على الطرفين). <code>shutdown</code> يعطّل الجيرة إدارياً دون حذف إعدادها — مفيد للصيانة. <code>no neighbor ... shutdown</code> يعيدها.","en":"Adds TCP MD5 authentication to the session, or administratively disables the peer.","ex":"<pre><span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 password Bgp@123\n<span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 shutdown\n<span class=\"p\">R1#</span> show ip bgp summary | include 10.1.1.2</pre>","exPlain":"R1(config-router)# neighbor 10.1.1.2 password Bgp@123\nR1(config-router)# neighbor 10.1.1.2 shutdown\nR1# show ip bgp summary | include 10.1.1.2","neg":"no neighbor 10.1.1.2 password","kind":"cmd"},{"i":201,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"address-family ipv4 unicast | neighbor <i>ip</i> activate","synPlain":"address-family ipv4 unicast | neighbor ip activate","mode":"Router Config","modeCls":"m-rconfig","ar":"في IOS الحديث (والـ IOS-XE) أصبح كل شيء داخل address-family. <b>نسيان <code>activate</code></b> هو السبب الأول لبقاء الجيرة Established دون تبادل أي مسار. تحقق من عمود <code>State/PfxRcd</code> في <code>show ip bgp summary</code>.","en":"Enters the address family and activates the peer for it, required in modern IOS.","ex":"<pre><span class=\"p\">R1(config)#</span> router bgp 65001\n<span class=\"p\">R1(config-router)#</span> address-family ipv4 unicast\n<span class=\"p\">R1(config-router-af)#</span> neighbor 10.1.1.2 activate\n<span class=\"p\">R1(config-router-af)#</span> network 203.0.113.0 mask 255.255.255.0</pre>","exPlain":"R1(config)# router bgp 65001\nR1(config-router)# address-family ipv4 unicast\nR1(config-router-af)# neighbor 10.1.1.2 activate\nR1(config-router-af)# network 203.0.113.0 mask 255.255.255.0","neg":"no neighbor 10.1.1.2 activate","kind":"cmd"},{"i":202,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> route-map <i>name</i> <i>{in|out}</i> | neighbor <i>ip</i> prefix-list <i>name</i> <i>{in|out}</i>","synPlain":"neighbor ip route-map name {in|out} | neighbor ip prefix-list name {in|out}","mode":"Router Config","modeCls":"m-rconfig","ar":"يفلتر المسارات الداخلة أو الخارجة. <code>route-map</code> أكثر مرونة (يمكنه تعديل الخصائص أيضاً)، و<code>prefix-list</code> أبسط وأسرع للفلترة البحتة. في BGP الفلترة إلزامية عملياً: لا تثق بجارك بأن يرسل لك ما تريد فقط.","en":"Applies inbound or outbound policy to filter and modify routes per neighbour.","ex":"<pre><span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 prefix-list PL-IN in\n<span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 route-map RM-OUT out\n<span class=\"p\">R1#</span> show ip bgp neighbors 10.1.1.2 routes</pre>","exPlain":"R1(config-router)# neighbor 10.1.1.2 prefix-list PL-IN in\nR1(config-router)# neighbor 10.1.1.2 route-map RM-OUT out\nR1# show ip bgp neighbors 10.1.1.2 routes","neg":"no neighbor 10.1.1.2 prefix-list PL-IN in","kind":"cmd"},{"i":203,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> maximum-prefix <i>n</i> [<i>threshold</i>] [warning-only]","synPlain":"neighbor ip maximum-prefix n [threshold] [warning-only]","mode":"Router Config","modeCls":"m-rconfig","ar":"حماية ضد تسرّب جدول التوجيه (Route Leak): يقطع الجيرة إذا تجاوز عدد البادئات حداً معيناً. إجراء أمني وتشغيلي أساسي في شبكات المشغّلين. <code>warning-only</code> يسجّل تحذيراً دون قطع.","en":"Protects memory by tearing down the session when a peer exceeds N prefixes.","ex":"<pre><span class=\"p\">R1(config-router)#</span> neighbor 10.1.1.2 maximum-prefix 500 80 warning-only</pre>","exPlain":"R1(config-router)# neighbor 10.1.1.2 maximum-prefix 500 80 warning-only","neg":"no neighbor 10.1.1.2 maximum-prefix","kind":"cmd"},{"i":204,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"timers bgp <i>keepalive</i> <i>holdtime</i>","synPlain":"timers bgp keepalive holdtime","mode":"Router Config","modeCls":"m-rconfig","ar":"يضبط مؤقّتات BGP. الافتراضي 60/180 ثانية. <b>لا يجب أن تقل عن 3 ثوان</b>، ويجب أن تكون متوافقة مع الجار (يُعتمد الأقل بين القيمتين). تقليلها يسرّع اكتشاف الانقطاع لكنه يزيد الحمل.","en":"Tunes BGP keepalives (default 60 s) and hold time (default 180 s).","ex":"<pre><span class=\"p\">R1(config-router)#</span> timers bgp 30 90</pre>","exPlain":"R1(config-router)# timers bgp 30 90","neg":"no timers bgp","kind":"cmd"},{"i":205,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"neighbor <i>ip</i> soft-reconfiguration inbound | clear ip bgp * soft","synPlain":"neighbor ip soft-reconfiguration inbound | clear ip bgp * soft","mode":"Router Config","modeCls":"m-rtr","ar":"يسمح بإعادة تطبيق سياسة الدخول (route-map / prefix-list / distribute-list) على الجيران <b>دون قطع الجيرة</b>. <code>soft-reconfiguration inbound</code> يخزّن نسخة من التحديثات الخام قبل الفلترة فيستهلك ذاكرة، بينما <code>route-refresh</code> (المدعوم أوسع) يطلب إعادة الإرسال من الجار نفسه فلا يستهلك شيئاً — وهو المفضّل. <b>لا تستخدم</b> <code>clear ip bgp *</code> بلا <code>soft</code> على جار إنتاجي: ستقطع الجلسة.","en":"Re-applies inbound policy without tearing the session down. Storing the raw updates costs memory, so route-refresh is preferred where both peers support it.","ex":"<pre><span class=\"p\">R1(config)#</span> router bgp 65001\n<span class=\"p\">R1(config-router)#</span> neighbor 10.0.0.2 soft-reconfiguration inbound\n<span class=\"p\">R1#</span> clear ip bgp * soft in\n<span class=\"p\">R1#</span> clear ip bgp 10.0.0.2 soft out\n<span class=\"p\">R1#</span> show ip bgp neighbors 10.0.0.2 | include refresh</pre>","exPlain":"R1(config)# router bgp 65001\nR1(config-router)# neighbor 10.0.0.2 soft-reconfiguration inbound\nR1# clear ip bgp * soft in\nR1# clear ip bgp 10.0.0.2 soft out\nR1# show ip bgp neighbors 10.0.0.2 | include refresh","neg":"no neighbor 10.0.0.2 soft-reconfiguration inbound","kind":"cmd"},{"i":206,"sec":"bgp","no":"12","secAr":"BGP","secEn":"BGP","grp":"routing","syn":"aggregate-address <i>network</i> <i>mask</i> [summary-only] [as-set]","synPlain":"aggregate-address network mask [summary-only] [as-set]","mode":"Router Config","modeCls":"m-rtr","ar":"يبني مساراً مجمّعاً من المسارات الأكثر تحديداً الموجودة في جدول BGP. <code>summary-only</code> يخفي التفاصيل ويُعلن المجمّع وحده — وهو ما يقصده معظم المهندسين. بدونه يُعلن المجمّع <b>و</b> التفاصيل معاً. <code>as-set</code> يحفظ قائمة AS_PATH للأصل لمنع الحلقات، ويجعل المسار يبدو كأنه قادم من مجموعة AS. تحقق بـ <code>show ip bgp</code> وابحث عن سطر يبدأ بـ <code>s</code> (suppressed).","en":"Builds a summary route from the more-specific BGP entries. `summary-only` suppresses the specifics, and `as-set` preserves the origin AS_PATH so the aggregate cannot create a loop.","ex":"<pre><span class=\"p\">R1(config)#</span> router bgp 65001\n<span class=\"p\">R1(config-router)#</span> aggregate-address 10.0.0.0 255.255.0.0 summary-only\n<span class=\"p\">R1#</span> show ip bgp\n   Network          Next Hop            Metric LocPrf Weight Path\n*> 10.0.0.0/16      0.0.0.0                  0         32768 i\ns> 10.1.0.0/24      0.0.0.0                  0         32768 i\ns> 10.2.0.0/24      0.0.0.0                  0         32768 i</pre>","exPlain":"R1(config)# router bgp 65001\nR1(config-router)# aggregate-address 10.0.0.0 255.255.0.0 summary-only\nR1# show ip bgp\n   Network          Next Hop            Metric LocPrf Weight Path\n*> 10.0.0.0/16      0.0.0.0                  0         32768 i\ns> 10.1.0.0/24      0.0.0.0                  0         32768 i\ns> 10.2.0.0/24      0.0.0.0                  0         32768 i","neg":"no aggregate-address 10.0.0.0 255.255.0.0","kind":"cmd"},{"i":207,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"standby <i>group</i> ip <i>virtual-ip</i>","synPlain":"standby group ip virtual-ip","mode":"Interface Config","modeCls":"m-iconf","ar":"ينشئ مجموعة HSRP ويحدد العنوان الافتراضي المشترك — وهو العنوان الذي ستضعه كبوابة على الأجهزة الطرفية. <b>رقم المجموعة</b> يجب أن يتطابق على الراوترين، والعنوان يجب أن يكون في نفس الشبكة الفرعية للواجهة.","en":"Creates an HSRP group with a shared virtual IP that hosts use as their default gateway.","ex":"<pre><span class=\"p\">R1(config-if)#</span> standby 1 ip 192.168.10.254\n<span class=\"p\">R2(config-if)#</span> standby 1 ip 192.168.10.254\n<span class=\"p\">R1#</span> show standby brief</pre>","exPlain":"R1(config-if)# standby 1 ip 192.168.10.254\nR2(config-if)# standby 1 ip 192.168.10.254\nR1# show standby brief","neg":"no standby 1 ip 192.168.10.254","kind":"cmd"},{"i":208,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"standby <i>group</i> priority <i>0-255</i>","synPlain":"standby group priority 0-255","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد أولوية الراوتر في المجموعة (افتراضي 100، الأعلى يصبح Active). القيمة 255 تمنع أي راوتر آخر من أن يصبح Active. القيمة 0 تجعله يتنازل دائماً.","en":"Sets election priority; higher wins (default 100).","ex":"<pre><span class=\"p\">R1(config-if)#</span> standby 1 priority 150\n<span class=\"p\">R2(config-if)#</span> standby 1 priority 100</pre>","exPlain":"R1(config-if)# standby 1 priority 150\nR2(config-if)# standby 1 priority 100","neg":"no standby 1 priority","kind":"cmd"},{"i":209,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"standby <i>group</i> preempt","synPlain":"standby group preempt","mode":"Interface Config","modeCls":"m-iconf","ar":"يجعل الراوتر يستعيد دور Active فور عودة الرابط، بدلاً من البقاء Standby حتى يسقط الراوتر الآخر. <b>معطّل افتراضياً في HSRP</b> (بخلاف VRRP) — ونسيانه يعني أن الراوتر ذا الأولوية الأعلى يبقى Standby بعد استعادة الخدمة، وهذا خطأ تصميمي شائع.","en":"Lets a higher-priority router take the Active role back when it recovers.","ex":"<pre><span class=\"p\">R1(config-if)#</span> standby 1 preempt\n<span class=\"p\">R1(config-if)#</span> standby 1 preempt delay minimum 30</pre>","exPlain":"R1(config-if)# standby 1 preempt\nR1(config-if)# standby 1 preempt delay minimum 30","neg":"no standby 1 preempt","kind":"cmd"},{"i":210,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"standby <i>group</i> track <i>{object|interface}</i> <i>decrement</i>","synPlain":"standby group track {object|interface} decrement","mode":"Interface Config","modeCls":"m-iconf","ar":"يربط HSRP بحالة شيء آخر (واجهة WAN، أو كائن IP SLA). عند سقوطه تُخفَّض الأولوية بمقدار <code>decrement</code> فينتقل الدور للراوتر الآخر — حتى لو كانت واجهة LAN ما زالت تعمل. هذا هو ما يحقق <b>Redundancy حقيقياً</b> وليس مجرد فشل واجهة.","en":"Lowers the priority when a tracked object or interface fails, forcing a failover.","ex":"<pre><span class=\"p\">R1(config-if)#</span> standby 1 track g0/1 20\n<span class=\"p\">R1(config-if)#</span> standby 1 track 1 decrement 30\n<span class=\"p\">R1#</span> show standby | include Track</pre>","exPlain":"R1(config-if)# standby 1 track g0/1 20\nR1(config-if)# standby 1 track 1 decrement 30\nR1# show standby | include Track","neg":"no standby 1 track g0/1","kind":"cmd"},{"i":211,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"standby version 2","synPlain":"standby version 2","mode":"Interface Config","modeCls":"m-iconf","ar":"يفعّل HSRPv2. الفروق: دعم مجموعات أكثر (<span class=\"num\">0–4095</span>)، توقيتات milli-second، MAC مختلف، وحزمة TLV. <b>يجب أن يكون الإصدار موحّداً</b> على كل أجهزة المجموعة وإلا لن تتفاعل.","en":"Enables HSRPv2, which supports group numbers above 255 and IPv6.","ex":"<pre><span class=\"p\">R1(config-if)#</span> standby version 2\n<span class=\"p\">R1(config-if)#</span> standby 1 timers msec 200 msec 750</pre>","exPlain":"R1(config-if)# standby version 2\nR1(config-if)# standby 1 timers msec 200 msec 750","neg":"no standby version","kind":"cmd"},{"i":212,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"standby <i>group</i> authentication md5 key-string <i>key</i>","synPlain":"standby group authentication md5 key-string key","mode":"Interface Config","modeCls":"m-iconf","ar":"يحمي المجموعة بكلمة سر MD5 تمنع أي جهاز من الانضمام أو التأثير على الانتخاب. إجراء أمني أساسي في شبكات المؤسسات.","en":"Authenticates HSRP hellos so a rogue router cannot join the group.","ex":"<pre><span class=\"p\">R1(config-if)#</span> standby 1 authentication md5 key-string Hsrp@123</pre>","exPlain":"R1(config-if)# standby 1 authentication md5 key-string Hsrp@123","neg":"no standby 1 authentication","kind":"cmd"},{"i":213,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"show standby | show standby brief","synPlain":"show standby | show standby brief","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض حالة المجموعة، من هو Active، الأولوية، العنوان الافتراضي، والـ timers. <code>brief</code> يعطي جدولاً مختصراً لكل المجموعات — أسرع للتحقق في المعمل.","en":"Shows group state, virtual IP, active and standby routers, and timers.","ex":"<pre><span class=\"p\">R1#</span> show standby brief\nInterface  Grp  Pri P State   Active      Standby     Virtual IP\nGi0/0      1    150 P Active  local       192.168.10.2 192.168.10.254</pre>","exPlain":"R1# show standby brief\nInterface  Grp  Pri P State   Active      Standby     Virtual IP\nGi0/0      1    150 P Active  local       192.168.10.2 192.168.10.254","neg":"","kind":"cmd"},{"i":214,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"vrrp <i>group</i> ip <i>virtual-ip</i>","synPlain":"vrrp group ip virtual-ip","mode":"Interface Config","modeCls":"m-iconf","ar":"ينشئ مجموعة VRRP — المعيار المفتوح (RFC) الذي يعمل بين مصنّعين مختلفين. الفرق الجوهري: يمكن استخدام <b>عنوان IP الواجهة نفسه</b> كعنوان افتراضي (Owner)، وفي هذه الحالة تكون الأولوية 255 تلقائياً.","en":"Creates a VRRP group; VRRP is the open-standard equivalent of HSRP.","ex":"<pre><span class=\"p\">R1(config-if)#</span> vrrp 1 ip 192.168.10.254\n<span class=\"p\">R1(config-if)#</span> vrrp 1 priority 120\n<span class=\"p\">R1(config-if)#</span> vrrp 1 preempt</pre>","exPlain":"R1(config-if)# vrrp 1 ip 192.168.10.254\nR1(config-if)# vrrp 1 priority 120\nR1(config-if)# vrrp 1 preempt","neg":"no vrrp 1 ip 192.168.10.254","kind":"cmd"},{"i":215,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"vrrp <i>group</i> track <i>object</i> decrement <i>n</i> | vrrp <i>group</i> authentication text <i>key</i>","synPlain":"vrrp group track object decrement n | vrrp group authentication text key","mode":"Interface Config","modeCls":"m-iconf","ar":"التتبّع والمصادقة في VRRP. لاحظ أن VRRP يستخدم <code>authentication text</code> (نص واضح) في بعض المنصات، وهو أضعف من MD5 في HSRP — نقطة أمنية تُذكر في المقارنات.","en":"Adjusts priority on failure, or adds plaintext authentication to VRRP advertisements.","ex":"<pre><span class=\"p\">R1(config-if)#</span> vrrp 1 track 1 decrement 30\n<span class=\"p\">R1(config-if)#</span> vrrp 1 authentication text Vrrp@123\n<span class=\"p\">R1#</span> show vrrp brief</pre>","exPlain":"R1(config-if)# vrrp 1 track 1 decrement 30\nR1(config-if)# vrrp 1 authentication text Vrrp@123\nR1# show vrrp brief","neg":"no vrrp 1 track 1","kind":"cmd"},{"i":216,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"glbp <i>group</i> ip <i>virtual-ip</i>","synPlain":"glbp group ip virtual-ip","mode":"Interface Config","modeCls":"m-iconf","ar":"Gateway Load Balancing Protocol: ميزة Cisco التي تتيح استخدام <b>كل</b> الراوترات في نفس الوقت. AVG (Active Virtual Gateway) يوزّع عناوين MAC افتراضية مختلفة على الأجهزة، وكل AVF (Active Virtual Forwarder) يخدم مجموعة منها. النتيجة: مضاعفة النطاق بدل تركه معطلاً.","en":"Creates a GLBP group, which load-balances across gateways instead of one active and one standby.","ex":"<pre><span class=\"p\">R1(config-if)#</span> glbp 1 ip 192.168.10.254\n<span class=\"p\">R1(config-if)#</span> glbp 1 priority 150\n<span class=\"p\">R1(config-if)#</span> glbp 1 preempt\n<span class=\"p\">R1(config-if)#</span> glbp 1 load-balancing round-robin</pre>","exPlain":"R1(config-if)# glbp 1 ip 192.168.10.254\nR1(config-if)# glbp 1 priority 150\nR1(config-if)# glbp 1 preempt\nR1(config-if)# glbp 1 load-balancing round-robin","neg":"no glbp 1 ip 192.168.10.254","kind":"cmd"},{"i":217,"sec":"fhrp","no":"13","secAr":"HSRP / VRRP / GLBP","secEn":"First Hop Redundancy","grp":"routing","syn":"glbp <i>group</i> load-balancing <i>{round-robin|host-dependent|weighted}</i>","synPlain":"glbp group load-balancing {round-robin|host-dependent|weighted}","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد طريقة التوزيع: <b>round-robin</b> بالتناوب على الأجهزة، <b>host-dependent</b> يثبّت كل جهاز على نفس البوابة، <b>weighted</b> يوزّع حسب سعة كل راوتر (مع <code>glbp 1 weighting</code>).","en":"Chooses how GLBP distributes clients across the active virtual forwarders.","ex":"<pre><span class=\"p\">R1(config-if)#</span> glbp 1 load-balancing weighted\n<span class=\"p\">R1(config-if)#</span> glbp 1 weighting 100 lower 1 upper 100\n<span class=\"p\">R1#</span> show glbp</pre>","exPlain":"R1(config-if)# glbp 1 load-balancing weighted\nR1(config-if)# glbp 1 weighting 100 lower 1 upper 100\nR1# show glbp","neg":"no glbp 1 load-balancing","kind":"cmd"},{"i":218,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"access-list <i>1-99</i> <i>{permit|deny}</i> <i>source</i> <i>wildcard</i>","synPlain":"access-list 1-99 {permit|deny} source wildcard","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ سطراً في ACL قياسية. <code>any</code> تعني أي عنوان (0.0.0.0 255.255.255.255)، و<code>host x.x.x.x</code> تعني عنواناً واحداً (wildcard 0.0.0.0). الـ Wildcard هو مقلوب القناع: <code>255.255.255.0</code> يعطي <code>0.0.0.255</code>.","en":"Builds a standard ACL that filters on the source address only.","ex":"<pre><span class=\"p\">R1(config)#</span> access-list 10 permit 192.168.10.0 0.0.0.255\n<span class=\"p\">R1(config)#</span> access-list 10 permit host 10.1.1.5\n<span class=\"p\">R1(config)#</span> access-list 10 deny any\n<span class=\"p\">R1#</span> show access-lists 10</pre>","exPlain":"R1(config)# access-list 10 permit 192.168.10.0 0.0.0.255\nR1(config)# access-list 10 permit host 10.1.1.5\nR1(config)# access-list 10 deny any\nR1# show access-lists 10","neg":"no access-list 10","kind":"cmd"},{"i":219,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"ip access-group <i>{acl-number|name}</i> <i>{in|out}</i>","synPlain":"ip access-group {acl-number|name} {in|out}","mode":"Interface Config","modeCls":"m-iconf","ar":"يطبّق ACL على الواجهة. <b>in</b> = الحزم الداخلة إلى الراوتر من هذه الواجهة، <b>out</b> = الحزم الخارجة منها. الحد الأقصى: ACL واحد لكل بروتوكول لكل اتجاه لكل واجهة. تطبيق ACL فارغة يحجب كل شيء.","en":"Applies an ACL to an interface in one direction; one ACL per direction per protocol.","ex":"<pre><span class=\"p\">R1(config)#</span> interface g0/1\n<span class=\"p\">R1(config-if)#</span> ip access-group 10 out\n<span class=\"p\">R1#</span> show ip interface g0/1 | include access list</pre>","exPlain":"R1(config)# interface g0/1\nR1(config-if)# ip access-group 10 out\nR1# show ip interface g0/1 | include access list","neg":"no ip access-group 10 out","kind":"cmd"},{"i":220,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"access-list <i>100-199</i> <i>{permit|deny}</i> <i>protocol</i> <i>src</i> <i>src-wild</i> <i>dst</i> <i>dst-wild</i> [eq <i>port</i>]","synPlain":"access-list 100-199 {permit|deny} protocol src src-wild dst dst-wild [eq port]","mode":"Global Config","modeCls":"m-gconf","ar":"يفلتر حسب المصدر والهدف والبروتوكول والمنفذ. البروتوكولات: <code>ip</code>، <code>tcp</code>، <code>udp</code>، <code>icmp</code>، <code>eigrp</code>، <code>ospf</code>. معاملات المنفذ: <code>eq</code> (يساوي)، <code>gt</code>، <code>lt</code>، <code>neq</code>، <code>range</code>. يمكن استخدام الأسماء (<code>www</code>، <code>telnet</code>، <code>ssh</code>) أو الأرقام.","en":"Builds an extended ACL matching protocol, source, destination, and ports.","ex":"<pre><span class=\"p\">R1(config)#</span> access-list 100 permit tcp 192.168.10.0 0.0.0.255 any eq 80\n<span class=\"p\">R1(config)#</span> access-list 100 permit tcp 192.168.10.0 0.0.0.255 any eq 443\n<span class=\"p\">R1(config)#</span> access-list 100 permit tcp any host 203.0.113.10 eq 22\n<span class=\"p\">R1(config)#</span> access-list 100 deny ip any any log</pre>","exPlain":"R1(config)# access-list 100 permit tcp 192.168.10.0 0.0.0.255 any eq 80\nR1(config)# access-list 100 permit tcp 192.168.10.0 0.0.0.255 any eq 443\nR1(config)# access-list 100 permit tcp any host 203.0.113.10 eq 22\nR1(config)# access-list 100 deny ip any any log","neg":"no access-list 100","kind":"cmd"},{"i":221,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"access-list <i>100</i> permit icmp <i>src</i> <i>wild</i> <i>dst</i> <i>wild</i> [echo|echo-reply|traceroute]","synPlain":"access-list 100 permit icmp src wild dst wild [echo|echo-reply|traceroute]","mode":"Global Config","modeCls":"m-gconf","ar":"يسمح بنوع محدد من ICMP. مفيد جداً: تريد السماح بـ <code>ping</code> (echo) دون السماح بكل ICMP. تذكّر أن <code>ping</code> يحتاج <b>echo request</b> في اتجاه و<b>echo-reply</b> في الاتجاه العكسي.","en":"Permits or denies specific ICMP types — the correct way to allow ping without opening everything.","ex":"<pre><span class=\"p\">R1(config)#</span> access-list 101 permit icmp any any echo\n<span class=\"p\">R1(config)#</span> access-list 101 permit icmp any any echo-reply\n<span class=\"p\">R1(config)#</span> access-list 101 permit icmp any any unreachable</pre>","exPlain":"R1(config)# access-list 101 permit icmp any any echo\nR1(config)# access-list 101 permit icmp any any echo-reply\nR1(config)# access-list 101 permit icmp any any unreachable","neg":"","kind":"cmd"},{"i":222,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"ip access-list <i>{standard|extended}</i> <i>name</i>","synPlain":"ip access-list {standard|extended} name","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ ACL مسمّاة ويُدخلك إلى وضع التحرير سطراً بسطر. <b>مزاياها:</b> ① يمكن حذف سطر واحد دون حذف القائمة كلها (<code>no &lt;seq&gt;</code>). ② أسماء معبّرة أفضل من أرقام. ③ إمكانية إدراج سطر في المنتصف باستخدام <code>seq</code>. هي الطريقة الموصى بها اليوم.","en":"Creates a named ACL that can be edited line by line and re-sequenced.","ex":"<pre><span class=\"p\">R1(config)#</span> ip access-list extended BLOCK-WEB\n<span class=\"p\">R1(config-ext-nacl)#</span> 10 deny tcp 192.168.10.0 0.0.0.255 any eq 80\n<span class=\"p\">R1(config-ext-nacl)#</span> 20 permit ip any any\n<span class=\"p\">R1(config-ext-nacl)#</span> no 10\n<span class=\"p\">R1(config-ext-nacl)#</span> 15 permit tcp host 192.168.10.5 any eq 80</pre>","exPlain":"R1(config)# ip access-list extended BLOCK-WEB\nR1(config-ext-nacl)# 10 deny tcp 192.168.10.0 0.0.0.255 any eq 80\nR1(config-ext-nacl)# 20 permit ip any any\nR1(config-ext-nacl)# no 10\nR1(config-ext-nacl)# 15 permit tcp host 192.168.10.5 any eq 80","neg":"no ip access-list extended BLOCK-WEB","kind":"cmd"},{"i":223,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"<i>seq</i> permit|deny <i>...</i> | remark <i>text</i>","synPlain":"seq permit|deny ... | remark text","mode":"Named ACL Config","modeCls":"m-nacl","ar":"داخل ACL مسمّاة تكتب السطر مع رقم تسلسلي اختياري (seq). الأرقام تسمح بالإدراج والحذف الدقيق. <code>remark</code> يضيف تعليقاً — عادة مهنية تجعل القائمة مفهومة بعد ستة أشهر.","en":"Adds rules with explicit sequence numbers and inline comments.","ex":"<pre><span class=\"p\">R1(config-ext-nacl)#</span> remark === Allow Sales to Web ===\n<span class=\"p\">R1(config-ext-nacl)#</span> 30 permit tcp 192.168.20.0 0.0.0.255 any eq 443\n<span class=\"p\">R1(config-ext-nacl)#</span> 40 deny ip any any log</pre>","exPlain":"R1(config-ext-nacl)# remark === Allow Sales to Web ===\nR1(config-ext-nacl)# 30 permit tcp 192.168.20.0 0.0.0.255 any eq 443\nR1(config-ext-nacl)# 40 deny ip any any log","neg":"no 30","kind":"cmd"},{"i":224,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"ip access-list resequence <i>name</i> <i>start</i> <i>increment</i>","synPlain":"ip access-list resequence name start increment","mode":"Global Config","modeCls":"m-gconf","ar":"يعيد ترقيم الأسطر بفاصل منتظم. يُستخدم عندما تنفد الأرقام بين سطرين وتريد إدراج قاعدة جديدة بينهما.","en":"Renumbers an ACL so new entries can be inserted between existing ones.","ex":"<pre><span class=\"p\">R1(config)#</span> ip access-list resequence BLOCK-WEB 10 10\n<span class=\"p\">R1#</span> show ip access-lists BLOCK-WEB</pre>","exPlain":"R1(config)# ip access-list resequence BLOCK-WEB 10 10\nR1# show ip access-lists BLOCK-WEB","neg":"ملاحظة لا يمكن التراجع عن إعادة الترقيم — احفظ نسخة قبلها","kind":"cmd"},{"i":225,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"access-class <i>{acl|name}</i> <i>{in|out}</i>","synPlain":"access-class {acl|name} {in|out}","mode":"Line Config (VTY)","modeCls":"m-lconf","ar":"يقيّد <b>من يستطيع تسجيل الدخول</b> إلى الجهاز عبر VTY (Telnet/SSH). لاحظ الفرق: <code>ip access-group</code> يفلتر الترافيك العابر، و<code>access-class</code> يفلتر جلسات الإدارة إلى الجهاز نفسه. الأخطاء هنا قد تقفل عليك الوصول.","en":"Restricts which addresses may open VTY (Telnet and SSH) sessions to the router.","ex":"<pre><span class=\"p\">R1(config)#</span> access-list 20 permit 10.1.1.0 0.0.0.255\n<span class=\"p\">R1(config)#</span> line vty 0 15\n<span class=\"p\">R1(config-line)#</span> access-class 20 in</pre>","exPlain":"R1(config)# access-list 20 permit 10.1.1.0 0.0.0.255\nR1(config)# line vty 0 15\nR1(config-line)# access-class 20 in","neg":"no access-class 20 in","kind":"cmd"},{"i":226,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"time-range <i>name</i> | periodic <i>days hh:mm to hh:mm</i> | absolute","synPlain":"time-range name | periodic days hh:mm to hh:mm | absolute","mode":"Global Config","modeCls":"m-gconf","ar":"يعرّف نافذة زمنية تُستخدم داخل ACL مع <code>time-range</code>. مفيد لسياسات «لا إنترنت في ساعات العمل». يتطلب ساعة دقيقة (NTP) وإلا فشلت السياسة بصمت.","en":"Defines a schedule that ACL entries can reference, enabling time-based filtering.","ex":"<pre><span class=\"p\">R1(config)#</span> time-range WORK-HOURS\n<span class=\"p\">R1(config-time-range)#</span> periodic weekdays 08:00 to 17:00\n<span class=\"p\">R1(config)#</span> ip access-list extended BLOCK-AT-WORK\n<span class=\"p\">R1(config-ext-nacl)#</span> deny tcp any any eq 80 time-range WORK-HOURS\n<span class=\"p\">R1(config-ext-nacl)#</span> permit ip any any</pre>","exPlain":"R1(config)# time-range WORK-HOURS\nR1(config-time-range)# periodic weekdays 08:00 to 17:00\nR1(config)# ip access-list extended BLOCK-AT-WORK\nR1(config-ext-nacl)# deny tcp any any eq 80 time-range WORK-HOURS\nR1(config-ext-nacl)# permit ip any any","neg":"no time-range WORK-HOURS","kind":"cmd"},{"i":227,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"ipv6 access-list <i>name</i> | permit|deny <i>protocol</i> <i>src/len</i> <i>dst/len</i>","synPlain":"ipv6 access-list name | permit|deny protocol src/len dst/len","mode":"Global Config","modeCls":"m-gconf","ar":"ACL للـ IPv6. لا توجد أرقام ولا wildcards — تُستخدم صيغة البادئة <code>prefix/length</code> مباشرة، و<code>any</code> للجميع. تُطبَّق بـ <code>ipv6 traffic-filter</code>.","en":"Builds an IPv6 ACL; IPv6 ACLs are always named and end with an implicit deny.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 access-list V6-WEB\n<span class=\"p\">R1(config-ipv6-acl)#</span> permit tcp 2001:db8:10::/64 any eq 443\n<span class=\"p\">R1(config-ipv6-acl)#</span> deny ipv6 any any\n<span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> ipv6 traffic-filter V6-WEB in</pre>","exPlain":"R1(config)# ipv6 access-list V6-WEB\nR1(config-ipv6-acl)# permit tcp 2001:db8:10::/64 any eq 443\nR1(config-ipv6-acl)# deny ipv6 any any\nR1(config)# interface g0/0\nR1(config-if)# ipv6 traffic-filter V6-WEB in","neg":"no ipv6 traffic-filter V6-WEB in","kind":"cmd"},{"i":228,"sec":"acl","no":"14","secAr":"قوائم التحكم ACLs","secEn":"Access Control Lists","grp":"services","syn":"show access-lists | show ip access-lists <i>name</i>","synPlain":"show access-lists | show ip access-lists name","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض كل ACLs مع <b>عدّادات المطابقة</b> لكل سطر — وهي أداة تشخيص لا تُقدَّر بثمن: إذا كان عدّاد سطر <code>deny</code> يتزايد، فأنت تعرف بالضبط أي قاعدة تحجب الترافيك. لتصفير العدّادات: <code>clear ip access-list counters</code>.","en":"Shows every ACE with its match counters — the fastest way to see which line is hitting.","ex":"<pre><span class=\"p\">R1#</span> show ip access-lists BLOCK-WEB\nExtended IP access list BLOCK-WEB\n    10 deny tcp 192.168.10.0 0.0.0.255 any eq www (24 matches)\n    20 permit ip any any (1830 matches)</pre>","exPlain":"R1# show ip access-lists BLOCK-WEB\nExtended IP access list BLOCK-WEB\n    10 deny tcp 192.168.10.0 0.0.0.255 any eq www (24 matches)\n    20 permit ip any any (1830 matches)","neg":"clear ip access-list counters BLOCK-WEB","kind":"cmd"},{"i":229,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat inside | ip nat outside","synPlain":"ip nat inside | ip nat outside","mode":"Interface Config","modeCls":"m-iconf","ar":"يحدد اتجاه الواجهة بالنسبة لعملية NAT. <b>inside</b> = الشبكة الداخلية (قبل الترجمة)، <b>outside</b> = الشبكة الخارجية (بعد الترجمة). يجب تطبيق أحد الأمرين على <b>كل</b> واجهة مشاركة في المسار — وإلا فلن تُترجم الحزم.","en":"Marks which interfaces are on the translated (inside) and untranslated (outside) side.","ex":"<pre><span class=\"p\">R1(config)#</span> interface g0/1\n<span class=\"p\">R1(config-if)#</span> ip nat inside\n<span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> ip nat outside\n<span class=\"p\">R1#</span> show ip nat statistics | include interfaces</pre>","exPlain":"R1(config)# interface g0/1\nR1(config-if)# ip nat inside\nR1(config)# interface g0/0\nR1(config-if)# ip nat outside\nR1# show ip nat statistics | include interfaces","neg":"no ip nat inside","kind":"cmd"},{"i":230,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat inside source static <i>local-ip</i> <i>global-ip</i>","synPlain":"ip nat inside source static local-ip global-ip","mode":"Global Config","modeCls":"m-gconf","ar":"ربط دائم 1:1 بين عنوان داخلي وعنوان عام. أي حزمة قادمة إلى العنوان العام تُترجم وتُوجَّه إلى العنوان الداخلي، والعكس صحيح. هو الحل لخادم بريد أو ويب يجب أن يكون مرئياً من الإنترنت.","en":"One-to-one static NAT mapping a private address to a public address.","ex":"<pre><span class=\"p\">R1(config)#</span> ip nat inside source static 192.168.10.50 203.0.113.5\n<span class=\"p\">R1#</span> show ip nat translations\nPro Inside global      Inside local       Outside local      Outside global\n--- 203.0.113.5        192.168.10.50      ---                ---</pre>","exPlain":"R1(config)# ip nat inside source static 192.168.10.50 203.0.113.5\nR1# show ip nat translations\nPro Inside global      Inside local       Outside local      Outside global\n--- 203.0.113.5        192.168.10.50      ---                ---","neg":"no ip nat inside source static 192.168.10.50 203.0.113.5","kind":"cmd"},{"i":231,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat inside source static <i>tcp|udp</i> <i>local-ip</i> <i>local-port</i> <i>global-ip</i> <i>global-port</i>","synPlain":"ip nat inside source static tcp|udp local-ip local-port global-ip global-port","mode":"Global Config","modeCls":"m-gconf","ar":"<b>Port Forwarding:</b> يترجم منفذاً محدداً على العنوان العام إلى منفذ على خادم داخلي، فيمكن نشر خدمة واحدة دون كشف الجهاز بالكامل. يمكن استخدام منفذ خارجي مختلف عن الداخلي.","en":"Port forwarding: maps one public port to one internal host and port.","ex":"<pre><span class=\"p\">R1(config)#</span> ip nat inside source static tcp 192.168.10.50 80 203.0.113.5 8080\n<span class=\"p\">R1(config)#</span> ip nat inside source static tcp 192.168.10.50 22 203.0.113.5 2222</pre>","exPlain":"R1(config)# ip nat inside source static tcp 192.168.10.50 80 203.0.113.5 8080\nR1(config)# ip nat inside source static tcp 192.168.10.50 22 203.0.113.5 2222","neg":"no ip nat inside source static tcp 192.168.10.50 80 203.0.113.5 8080","kind":"cmd"},{"i":232,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat inside source list <i>acl</i> interface <i>outside-intf</i> overload","synPlain":"ip nat inside source list acl interface outside-intf overload","mode":"Global Config","modeCls":"m-gconf","ar":"أشهر أمر NAT في العالم: يترجم كل العناوين المطابقة للـ ACL إلى عنوان الواجهة الخارجية باستخدام أرقام منافذ مختلفة (PAT). <b>ملاحظة:</b> الـ ACL هنا ليست جداراً نارياً — هي مجرد <b>محدِّد</b> لأي العناوين تُترجم. الحزم غير المطابقة لا تُترجم ولا تُحجب.","en":"PAT: translates many inside addresses to one outside address using port numbers.","ex":"<pre><span class=\"p\">R1(config)#</span> access-list 1 permit 192.168.0.0 0.0.255.255\n<span class=\"p\">R1(config)#</span> ip nat inside source list 1 interface g0/0 overload\n<span class=\"p\">R1#</span> show ip nat translations\nPro Inside global     Inside local      Outside local     Outside global\ntcp 203.0.113.2:1024  192.168.10.5:51515 8.8.8.8:443      8.8.8.8:443</pre>","exPlain":"R1(config)# access-list 1 permit 192.168.0.0 0.0.255.255\nR1(config)# ip nat inside source list 1 interface g0/0 overload\nR1# show ip nat translations\nPro Inside global     Inside local      Outside local     Outside global\ntcp 203.0.113.2:1024  192.168.10.5:51515 8.8.8.8:443      8.8.8.8:443","neg":"no ip nat inside source list 1 interface g0/0 overload","kind":"cmd"},{"i":233,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat pool <i>name</i> <i>start-ip</i> <i>end-ip</i> netmask <i>mask</i>","synPlain":"ip nat pool name start-ip end-ip netmask mask","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ مجموعة عناوين عامة للترجمة الديناميكية. تُستخدم مع <code>ip nat inside source list</code> بدون <code>overload</code> (ترجمة 1:1 مؤقتة) أو معها (PAT بمجموعة عناوين).","en":"Defines a range of public addresses to translate into.","ex":"<pre><span class=\"p\">R1(config)#</span> ip nat pool PUBLIC 203.0.113.10 203.0.113.20 netmask 255.255.255.0\n<span class=\"p\">R1(config)#</span> ip nat inside source list 1 pool PUBLIC overload</pre>","exPlain":"R1(config)# ip nat pool PUBLIC 203.0.113.10 203.0.113.20 netmask 255.255.255.0\nR1(config)# ip nat inside source list 1 pool PUBLIC overload","neg":"no ip nat pool PUBLIC","kind":"cmd"},{"i":234,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat inside source list <i>acl</i> pool <i>name</i>","synPlain":"ip nat inside source list acl pool name","mode":"Global Config","modeCls":"m-gconf","ar":"Dynamic NAT: كل عنوان داخلي يأخذ عنواناً عاماً من الـ pool طوال مدة الجلسة. القيد: عدد المستخدمين المتزامنين لا يمكن أن يتجاوز حجم الـ pool — وإلا فُقد الاتصال لمن يأتي بعد نفاد العناوين.","en":"Dynamic NAT: maps inside hosts to the pool on a first-come, first-served basis.","ex":"<pre><span class=\"p\">R1(config)#</span> ip nat inside source list 1 pool PUBLIC\n<span class=\"p\">R1#</span> show ip nat statistics\nTotal active translations: 8 (0 static, 8 dynamic; 0 extended)</pre>","exPlain":"R1(config)# ip nat inside source list 1 pool PUBLIC\nR1# show ip nat statistics\nTotal active translations: 8 (0 static, 8 dynamic; 0 extended)","neg":"no ip nat inside source list 1 pool PUBLIC","kind":"cmd"},{"i":235,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat translation timeout <i>sec</i> | udp-timeout | tcp-timeout","synPlain":"ip nat translation timeout sec | udp-timeout | tcp-timeout","mode":"Global Config","modeCls":"m-gconf","ar":"يتحكم في مدة بقاء إدخال الترجمة. الافتراضي: 86400 ثانية للجلسات العامة، 300 ثانية لـ UDP، 86400 لـ TCP. تقليل المهلة يحرّر الموارد أسرع لكنه قد يقطع جلسات طويلة خاملة.","en":"Controls how long idle NAT entries remain in the translation table.","ex":"<pre><span class=\"p\">R1(config)#</span> ip nat translation timeout 3600\n<span class=\"p\">R1(config)#</span> ip nat translation udp-timeout 120\n<span class=\"p\">R1(config)#</span> ip nat translation max-entries 5000</pre>","exPlain":"R1(config)# ip nat translation timeout 3600\nR1(config)# ip nat translation udp-timeout 120\nR1(config)# ip nat translation max-entries 5000","neg":"no ip nat translation timeout","kind":"cmd"},{"i":236,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"show ip nat translations [verbose]","synPlain":"show ip nat translations [verbose]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"الجدول الفعلي للترجمات. الأعمدة: <b>Inside local</b> (العنوان الحقيقي للجهاز الداخلي)، <b>Inside global</b> (العنوان بعد الترجمة كما يراه الخارج)، <b>Outside local/global</b>. <code>verbose</code> يضيف تفاصيل الجلسة والمؤقّتات.","en":"Lists active inside and outside translations; add verbose for counters.","ex":"<pre><span class=\"p\">R1#</span> show ip nat translations verbose\nPro Inside global     Inside local      Outside local    Outside global\nicmp 203.0.113.2:1    192.168.10.5:1    8.8.8.8:1        8.8.8.8:1\n  create 00:02:11, use 00:00:04, timeout 60000</pre>","exPlain":"R1# show ip nat translations verbose\nPro Inside global     Inside local      Outside local    Outside global\nicmp 203.0.113.2:1    192.168.10.5:1    8.8.8.8:1        8.8.8.8:1\n  create 00:02:11, use 00:00:04, timeout 60000","neg":"clear ip nat translation *","kind":"cmd"},{"i":237,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"show ip nat statistics","synPlain":"show ip nat statistics","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض عدد الترجمات النشطة، الواجهات المعرّفة، عدد الـ hits وmisses، وحالة الـ pool. إذا كان <code>Hits: 0</code> فمعناه أن NAT لا تُطبَّق أصلاً — راجع <code>ip nat inside/outside</code>.","en":"Shows hits, misses, and pool utilisation — it confirms whether NAT is actually being applied.","ex":"<pre><span class=\"p\">R1#</span> show ip nat statistics\nTotal translations: 12 (1 static, 11 dynamic, 9 extended)\nHits: 342  Misses: 4\nDynamic mappings:\n-- Inside Source\naccess-list 1 pool PUBLIC refcount 11</pre>","exPlain":"R1# show ip nat statistics\nTotal translations: 12 (1 static, 11 dynamic, 9 extended)\nHits: 342  Misses: 4\nDynamic mappings:\n-- Inside Source\naccess-list 1 pool PUBLIC refcount 11","neg":"","kind":"cmd"},{"i":238,"sec":"nat","no":"15","secAr":"ترجمة العناوين NAT","secEn":"Network Address Translation","grp":"services","syn":"ip nat log translations syslog","synPlain":"ip nat log translations syslog","mode":"Global Config","modeCls":"m-gconf","ar":"يسجّل كل عملية إنشاء/حذف ترجمة في السجل — مفيد للتدقيق الأمني وتتبع مصدر الاتصالات. استخدمه بحذر لأنه يولّد حجماً كبيراً من السجلات على الشبكات المزدحمة.","en":"Generates a syslog message for every NAT binding, useful for auditing.","ex":"<pre><span class=\"p\">R1(config)#</span> ip nat log translations syslog\n<span class=\"p\">R1#</span> show logging | include NAT</pre>","exPlain":"R1(config)# ip nat log translations syslog\nR1# show logging | include NAT","neg":"no ip nat log translations syslog","kind":"cmd"},{"i":239,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"service dhcp","synPlain":"service dhcp","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل خدمة خادم/وسيط DHCP على الراوتر. <b>مفعّلة افتراضياً</b> على معظم المنصات، لكن بعض إصدارات IOS-XE تكون مغلقة. إن لم يعمل الخادم رغم صحة الـ pool، فهذا أول ما تتحقق منه.","en":"Enables the built-in DHCP server service, which is on by default.","ex":"<pre><span class=\"p\">R1(config)#</span> service dhcp\n<span class=\"p\">R1#</span> show ip dhcp server statistics | include Enabled</pre>","exPlain":"R1(config)# service dhcp\nR1# show ip dhcp server statistics | include Enabled","neg":"no service dhcp","kind":"cmd"},{"i":240,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"ip dhcp excluded-address <i>start-ip</i> [<i>end-ip</i>]","synPlain":"ip dhcp excluded-address start-ip [end-ip]","mode":"Global Config","modeCls":"m-gconf","ar":"يستثني نطاقاً من التوزيع. <b>إلزامي عملياً:</b> استثنِ عنوان البوابة، الخوادم، الطابعات، وأجهزة الشبكة. بدون الاستثناء قد يُسلّم عنوان البوابة لجهاز طرفي فتنهار الشبكة — وهو خطأ كلاسيكي في الامتحان.","en":"Reserves addresses (gateway, servers, printers) so the pool never hands them out.","ex":"<pre><span class=\"p\">R1(config)#</span> ip dhcp excluded-address 192.168.10.1 192.168.10.20\n<span class=\"p\">R1(config)#</span> ip dhcp excluded-address 192.168.10.254</pre>","exPlain":"R1(config)# ip dhcp excluded-address 192.168.10.1 192.168.10.20\nR1(config)# ip dhcp excluded-address 192.168.10.254","neg":"no ip dhcp excluded-address 192.168.10.1 192.168.10.20","kind":"cmd"},{"i":241,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"ip dhcp pool <i>name</i>","synPlain":"ip dhcp pool name","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ Pool ويُدخلك إلى وضع إعداد DHCP. الاسم محلي للتوثيق فقط. داخل الـ pool تُعرَّف الشبكة والخيارات ومدة الإيجار.","en":"Creates a DHCP pool and enters Pool Configuration.","ex":"<pre><span class=\"p\">R1(config)#</span> ip dhcp pool LAN10\n<span class=\"p\">R1(dhcp-config)#</span> network 192.168.10.0 255.255.255.0\n<span class=\"p\">R1(dhcp-config)#</span> default-router 192.168.10.1\n<span class=\"p\">R1(dhcp-config)#</span> dns-server 8.8.8.8 1.1.1.1\n<span class=\"p\">R1(dhcp-config)#</span> domain-name lab.local\n<span class=\"p\">R1(dhcp-config)#</span> lease 7</pre>","exPlain":"R1(config)# ip dhcp pool LAN10\nR1(dhcp-config)# network 192.168.10.0 255.255.255.0\nR1(dhcp-config)# default-router 192.168.10.1\nR1(dhcp-config)# dns-server 8.8.8.8 1.1.1.1\nR1(dhcp-config)# domain-name lab.local\nR1(dhcp-config)# lease 7","neg":"no ip dhcp pool LAN10","kind":"cmd"},{"i":242,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"network <i>network</i> <i>mask</i> [<i>/prefix</i>]","synPlain":"network network mask [/prefix]","mode":"DHCP Pool Config","modeCls":"m-dhcp","ar":"يحدد نطاق العناوين الذي يخدمه الـ pool. يجب أن يطابق شبكة فرعية موجودة على الراوتر (أو أن يكون هناك مسار إليها عند استخدام Relay). الـ pool يوزّع من هذا النطاق تلقائياً مع استثناء العناوين المحجوزة.","en":"Defines the subnet the pool serves and therefore its size.","ex":"<pre><span class=\"p\">R1(dhcp-config)#</span> network 192.168.10.0 255.255.255.0\n<span class=\"p\">R1(dhcp-config)#</span> network 192.168.20.0 /24</pre>","exPlain":"R1(dhcp-config)# network 192.168.10.0 255.255.255.0\nR1(dhcp-config)# network 192.168.20.0 /24","neg":"no network 192.168.10.0 255.255.255.0","kind":"cmd"},{"i":243,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"default-router <i>ip</i> | dns-server <i>ip1 ip2</i> | domain-name <i>name</i>","synPlain":"default-router ip | dns-server ip1 ip2 | domain-name name","mode":"DHCP Pool Config","modeCls":"m-dhcp","ar":"الخيارات التي تُسلَّم للعميل. <code>default-router</code> = البوابة (خيار 3)، و<code>dns-server</code> = خادم الأسماء (خيار 6)، و<code>domain-name</code> = النطاق (خيار 15). يمكن إضافة حتى 8 عناوين DNS.","en":"Supplies the options clients need: default gateway, DNS servers, and domain name.","ex":"<pre><span class=\"p\">R1(dhcp-config)#</span> default-router 192.168.10.1\n<span class=\"p\">R1(dhcp-config)#</span> dns-server 8.8.8.8 1.1.1.1\n<span class=\"p\">R1(dhcp-config)#</span> domain-name lab.local\n<span class=\"p\">R1(dhcp-config)#</span> netbios-name-server 192.168.10.5</pre>","exPlain":"R1(dhcp-config)# default-router 192.168.10.1\nR1(dhcp-config)# dns-server 8.8.8.8 1.1.1.1\nR1(dhcp-config)# domain-name lab.local\nR1(dhcp-config)# netbios-name-server 192.168.10.5","neg":"no default-router","kind":"cmd"},{"i":244,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"lease <i>{days [hours] [minutes] | infinite}</i>","synPlain":"lease {days [hours] [minutes] | infinite}","mode":"DHCP Pool Config","modeCls":"m-dhcp","ar":"مدة الإيجار. الافتراضي يوم واحد. في شبكات الضيوف يُفضّل تقليلها (ساعات) لتحرير العناوين سريعاً؛ وفي شبكات المكاتب الثابتة يمكن زيادتها إلى <span class=\"num\">7–8</span> أيام لتقليل حركة DHCP.","en":"Sets the address lease duration, or infinite for permanent assignments.","ex":"<pre><span class=\"p\">R1(dhcp-config)#</span> lease 7\n<span class=\"p\">R1(dhcp-config)#</span> lease 0 8 30\n<span class=\"p\">R1(dhcp-config)#</span> lease infinite</pre>","exPlain":"R1(dhcp-config)# lease 7\nR1(dhcp-config)# lease 0 8 30\nR1(dhcp-config)# lease infinite","neg":"no lease","kind":"cmd"},{"i":245,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"option <i>code</i> <i>{ip|ascii|hex}</i> <i>value</i>","synPlain":"option code {ip|ascii|hex} value","mode":"DHCP Pool Config","modeCls":"m-dhcp","ar":"يضيف خيار DHCP مخصّصاً. الأشهر في شبكات Cisco: <b>option 150</b> لعنوان خادم TFTP (تحميل إعدادات هواتف IP)، و<b>option 66</b> لاسم خادم TFTP، و<b>option 67</b> لاسم ملف الإقلاع. أسئلة CCNA تذكر option 150 كثيراً.","en":"Adds any DHCP option by number and type (66 TFTP, 150 TFTP list, 42 NTP, ...).","ex":"<pre><span class=\"p\">R1(dhcp-config)#</span> option 150 ip 192.168.10.5\n<span class=\"p\">R1(dhcp-config)#</span> option 66 ascii tftp.lab.local\n<span class=\"p\">R1(dhcp-config)#</span> option 67 ascii phones/cp7940.cnf.xml</pre>","exPlain":"R1(dhcp-config)# option 150 ip 192.168.10.5\nR1(dhcp-config)# option 66 ascii tftp.lab.local\nR1(dhcp-config)# option 67 ascii phones/cp7940.cnf.xml","neg":"no option 150","kind":"cmd"},{"i":246,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"host <i>ip</i> <i>mask</i> | hardware-address <i>mac</i> | client-identifier <i>id</i>","synPlain":"host ip mask | hardware-address mac | client-identifier id","mode":"DHCP Pool Config","modeCls":"m-dhcp","ar":"حجز عنوان ثابت لجهاز معيّن (Static Binding) عبر DHCP. أفضل من الإعداد اليدوي على الجهاز لأنه مركزي وقابل للتغيير. <code>client-identifier</code> يُستخدم للأجهزة التي لا تعرّف نفسها بـ MAC (مثل بعض الهواتف).","en":"Creates a manual binding for one specific device.","ex":"<pre><span class=\"p\">R1(config)#</span> ip dhcp pool PRINTER\n<span class=\"p\">R1(dhcp-config)#</span> host 192.168.10.60 255.255.255.0\n<span class=\"p\">R1(dhcp-config)#</span> hardware-address 0050.7966.6800\n<span class=\"p\">R1(dhcp-config)#</span> default-router 192.168.10.1</pre>","exPlain":"R1(config)# ip dhcp pool PRINTER\nR1(dhcp-config)# host 192.168.10.60 255.255.255.0\nR1(dhcp-config)# hardware-address 0050.7966.6800\nR1(dhcp-config)# default-router 192.168.10.1","neg":"no ip dhcp pool PRINTER","kind":"cmd"},{"i":247,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"ip helper-address <i>dhcp-server-ip</i>","synPlain":"ip helper-address dhcp-server-ip","mode":"Interface Config","modeCls":"m-iconf","ar":"يحوّل بث DHCP المحلي إلى Unicast موجّه إلى خادم DHCP في شبكة أخرى. يُطبَّق على الواجهة <b>المواجهة للعملاء</b> (أي البوابة). بدون هذا الأمر، طلب DHCP (بث 255.255.255.255) لا يعبر الراوتر أبداً — وهذا هو السبب الأول لفشل DHCP في الشبكات المتعددة.","en":"Forwards broadcast DHCP requests as unicast to a server on another subnet.","ex":"<pre><span class=\"p\">R1(config)#</span> interface g0/1\n<span class=\"p\">R1(config-if)#</span> ip helper-address 10.1.1.100\n<span class=\"p\">R1(config-if)#</span> ip helper-address 10.1.1.101</pre>","exPlain":"R1(config)# interface g0/1\nR1(config-if)# ip helper-address 10.1.1.100\nR1(config-if)# ip helper-address 10.1.1.101","neg":"no ip helper-address 10.1.1.100","kind":"cmd"},{"i":248,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"ip forward-protocol udp <i>port</i>","synPlain":"ip forward-protocol udp port","mode":"Global Config","modeCls":"m-gconf","ar":"<code>ip helper-address</code> يمرّر افتراضياً منافذ محددة (DHCP 67، TFTP 69، DNS 53، NetBIOS، TACACS). لتمرير خدمة أخرى (مثل بث تطبيق مخصّص) يجب إضافتها صراحة بهذا الأمر.","en":"Chooses which UDP broadcasts the helper forwards; DHCP is UDP port 67.","ex":"<pre><span class=\"p\">R1(config)#</span> ip forward-protocol udp 5000\n<span class=\"p\">R1(config)#</span> no ip forward-protocol udp 37</pre>","exPlain":"R1(config)# ip forward-protocol udp 5000\nR1(config)# no ip forward-protocol udp 37","neg":"no ip forward-protocol udp 5000","kind":"cmd"},{"i":249,"sec":"dhcp","no":"16","secAr":"DHCP","secEn":"DHCP","grp":"services","syn":"ip address dhcp client-id <i>interface</i>","synPlain":"ip address dhcp client-id interface","mode":"Interface Config","modeCls":"m-iconf","ar":"مثل <code>ip address dhcp</code> لكنه يُرسل <b>client-id</b> مأخوذاً من واجهة أخرى بدل MAC الواجهة نفسها. تحتاجه عندما يربط المزوّد الإيجار بعنوان MAC محدد — كأن استبدلت الراوتر وتريد الاحتفاظ بنفس العنوان العام. تحقق بـ <code>show dhcp lease</code>.","en":"Behaves like ip address dhcp but sends the client-id taken from another interface, which is what ISPs that bind the lease to a fixed MAC require after a hardware swap.","ex":"<pre><span class=\"p\">R1(config)#</span> interface GigabitEthernet0/0\n<span class=\"p\">R1(config-if)#</span> ip address dhcp client-id GigabitEthernet0/1\n<span class=\"p\">R1(config-if)#</span> no shutdown\n<span class=\"p\">R1#</span> show dhcp lease\nTemp IP addr: 203.0.113.45 for peer on Interface: GigabitEthernet0/0\nTemp sub net mask: 255.255.255.0</pre>","exPlain":"R1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip address dhcp client-id GigabitEthernet0/1\nR1(config-if)# no shutdown\nR1# show dhcp lease\nTemp IP addr: 203.0.113.45 for peer on Interface: GigabitEthernet0/0\nTemp sub net mask: 255.255.255.0","neg":"no ip address dhcp","kind":"cmd"},{"i":250,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"ntp server <i>ip</i> [prefer]","synPlain":"ntp server ip [prefer]","mode":"Global Config","modeCls":"m-gconf","ar":"يزامن ساعة الجهاز مع خادم NTP. <code>prefer</code> يجعله الخادم المفضّل عند تعدد الخوادم. التوقيت الدقيق ضروري لأن السجلات والشهادات وتصحيح الأخطاء كلها تعتمد عليه.","en":"Points the device at an NTP server; prefer marks the primary source.","ex":"<pre><span class=\"p\">R1(config)#</span> ntp server 216.239.35.0 prefer\n<span class=\"p\">R1(config)#</span> ntp server 216.239.35.4\n<span class=\"p\">R1(config)#</span> ntp source loopback 0\n<span class=\"p\">R1#</span> show ntp associations\n  address         ref clock     st  when  poll reach  delay  offset\n*~216.239.35.0   .GOOG.        1    64    64   377   12.3   0.512</pre>","exPlain":"R1(config)# ntp server 216.239.35.0 prefer\nR1(config)# ntp server 216.239.35.4\nR1(config)# ntp source loopback 0\nR1# show ntp associations\n  address         ref clock     st  when  poll reach  delay  offset\n*~216.239.35.0   .GOOG.        1    64    64   377   12.3   0.512","neg":"no ntp server 216.239.35.0","kind":"cmd"},{"i":251,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"ntp master <i>stratum</i>","synPlain":"ntp master stratum","mode":"Global Config","modeCls":"m-gconf","ar":"يجعل الراوتر مصدر توقيت بنفسه (Stratum محدد، عادةً <span class=\"num\">3–5</span>) بدلاً من الاعتماد على خادم خارجي. يُستخدم في شبكات معزولة أو كخادم داخلي للشبكة كلها.","en":"Makes this router an NTP server at the given stratum.","ex":"<pre><span class=\"p\">R1(config)#</span> ntp master 3\n<span class=\"p\">R2(config)#</span> ntp server 10.1.1.1\n<span class=\"p\">R1#</span> show ntp status\nClock is synchronized, stratum 3, reference is 10.1.1.1</pre>","exPlain":"R1(config)# ntp master 3\nR2(config)# ntp server 10.1.1.1\nR1# show ntp status\nClock is synchronized, stratum 3, reference is 10.1.1.1","neg":"no ntp master","kind":"cmd"},{"i":252,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"ntp authentication-key <i>n</i> md5 <i>key</i> | ntp trusted-key <i>n</i> | ntp authenticate","synPlain":"ntp authentication-key n md5 key | ntp trusted-key n | ntp authenticate","mode":"Global Config","modeCls":"m-gconf","ar":"يحمي NTP من خوادم مزيفة (NTP Spoofing). الثلاثة معاً: تعريف المفتاح، اعتباره موثوقاً، وتفعيل المصادقة عالمياً. ثم أضف <code>key &lt;n&gt;</code> إلى أمر <code>ntp server</code>.","en":"Secures NTP so only authenticated time sources are accepted.","ex":"<pre><span class=\"p\">R1(config)#</span> ntp authentication-key 1 md5 Ntp@123\n<span class=\"p\">R1(config)#</span> ntp trusted-key 1\n<span class=\"p\">R1(config)#</span> ntp authenticate\n<span class=\"p\">R1(config)#</span> ntp server 10.1.1.1 key 1</pre>","exPlain":"R1(config)# ntp authentication-key 1 md5 Ntp@123\nR1(config)# ntp trusted-key 1\nR1(config)# ntp authenticate\nR1(config)# ntp server 10.1.1.1 key 1","neg":"no ntp authenticate","kind":"cmd"},{"i":253,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"clock timezone <i>name</i> <i>offset</i> | clock set <i>hh:mm:ss day month year</i>","synPlain":"clock timezone name offset | clock set hh:mm:ss day month year","mode":"Global Config / EXEC","modeCls":"m-gconf","ar":"يضبط المنطقة الزمنية والإزاحة عن UTC، ويضبط الساعة يدوياً. <code>clock set</code> يُنفَّذ من Privileged EXEC لا من Config Mode. ملاحظة: NTP يضبط UTC داخلياً ويعرض الوقت المحلي حسب <code>clock timezone</code>.","en":"Sets the timezone offset and, on devices without NTP, the clock itself.","ex":"<pre><span class=\"p\">R1(config)#</span> clock timezone AST 3\n<span class=\"p\">R1(config)#</span> clock summer-time AST recurring\n<span class=\"p\">R1#</span> clock set 18:42:00 25 October 2026\n<span class=\"p\">R1#</span> show clock detail</pre>","exPlain":"R1(config)# clock timezone AST 3\nR1(config)# clock summer-time AST recurring\nR1# clock set 18:42:00 25 October 2026\nR1# show clock detail","neg":"no clock timezone","kind":"cmd"},{"i":254,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"logging host <i>ip</i> | logging trap <i>level</i>","synPlain":"logging host ip | logging trap level","mode":"Global Config","modeCls":"m-gconf","ar":"<code>logging host</code> يحدد خادم Syslog. <code>logging trap</code> يحدد أدنى مستوى يُرسل (<span class=\"num\">0=emergencies … 7=debugging</span>). المستويات الشائعة: <b>6 (informational)</b> للإنتاج، و7 للتحقيق المؤقت فقط. تحذير: إرسال level 7 دائماً يغرق الخادم.","en":"Sends syslog messages to a remote collector, filtered by severity.","ex":"<pre><span class=\"p\">R1(config)#</span> logging host 10.1.1.100\n<span class=\"p\">R1(config)#</span> logging trap informational\n<span class=\"p\">R1(config)#</span> logging source-interface loopback 0\n<span class=\"p\">R1(config)#</span> logging facility local7</pre>","exPlain":"R1(config)# logging host 10.1.1.100\nR1(config)# logging trap informational\nR1(config)# logging source-interface loopback 0\nR1(config)# logging facility local7","neg":"no logging host 10.1.1.100","kind":"cmd"},{"i":255,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"logging buffered <i>size</i> <i>level</i> | logging console <i>level</i>","synPlain":"logging buffered size level | logging console level","mode":"Global Config","modeCls":"m-gconf","ar":"<code>buffered</code> يحفظ السجلات في ذاكرة الراوتر (يُقرأ بـ <code>show logging</code>) — وهو الأهم عملياً. <code>console</code> يحدد ما يظهر على الكونسول؛ يُنصح بتخفيضه إلى <code>warnings</code> أو أعلى لمنع إغراق الشاشة أثناء العمل.","en":"Sets the local buffer size and level, and how verbose console output is.","ex":"<pre><span class=\"p\">R1(config)#</span> logging buffered 16384 informational\n<span class=\"p\">R1(config)#</span> logging console warnings\n<span class=\"p\">R1(config)#</span> logging monitor debugging\n<span class=\"p\">R1(config)#</span> service timestamps log datetime msec localtime</pre>","exPlain":"R1(config)# logging buffered 16384 informational\nR1(config)# logging console warnings\nR1(config)# logging monitor debugging\nR1(config)# service timestamps log datetime msec localtime","neg":"no logging console","kind":"cmd"},{"i":256,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"show logging | clear logging","synPlain":"show logging | clear logging","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض إعدادات السجل ومحتوى الـ buffer. ابحث عن <code>%LINK</code>، <code>%LINEPROTO</code>، <code>%SYS-5-CONFIG_I</code> (من غيّر الإعداد)، <code>%SEC_LOGIN</code>. هذه الأكواد هي التي تكشف ما حدث فعلاً.","en":"Reads or clears the local syslog buffer.","ex":"<pre><span class=\"p\">R1#</span> show logging\nSyslog logging: enabled (0 messages dropped, 1 flushes)\n    Console logging: level warnings\n    Buffer logging: level informational, 42 messages logged\n*Oct 25 18:40:02.115: %SYS-5-CONFIG_I: Configured from console by admin</pre>","exPlain":"R1# show logging\nSyslog logging: enabled (0 messages dropped, 1 flushes)\n    Console logging: level warnings\n    Buffer logging: level informational, 42 messages logged\n*Oct 25 18:40:02.115: %SYS-5-CONFIG_I: Configured from console by admin","neg":"clear logging","kind":"cmd"},{"i":257,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"snmp-server community <i>string</i> <i>{ro|rw}</i> [<i>acl</i>]","synPlain":"snmp-server community string {ro|rw} [acl]","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ «مجتمع» SNMP للوصول. <code>ro</code> للقراءة فقط (وهو المطلوب في 95% من الحالات)، و<code>rw</code> للكتابة والتعديل (خطر أمني كبير — تجنّبه). استخدم ACL لتقييد من يستطيع الاستعلام.","en":"Defines a read-only or read-write SNMPv2c community, optionally restricted by an ACL.","ex":"<pre><span class=\"p\">R1(config)#</span> snmp-server community S3cr3tRO ro 20\n<span class=\"p\">R1(config)#</span> snmp-server location DataCenter-Rack-12\n<span class=\"p\">R1(config)#</span> snmp-server contact netops@lab.local\n<span class=\"p\">R1(config)#</span> snmp-server host 10.1.1.100 version 2c S3cr3tRO</pre>","exPlain":"R1(config)# snmp-server community S3cr3tRO ro 20\nR1(config)# snmp-server location DataCenter-Rack-12\nR1(config)# snmp-server contact netops@lab.local\nR1(config)# snmp-server host 10.1.1.100 version 2c S3cr3tRO","neg":"no snmp-server community S3cr3tRO","kind":"cmd"},{"i":258,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"snmp-server enable traps <i>[type]</i>","synPlain":"snmp-server enable traps [type]","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل إرسال الـ Traps (إشعارات غير مطلوبة) عند أحداث معيّنة. بدونها يستطيع الخادم أن يسأل (Poll) لكنه لن يُنبَّه تلقائياً. الأنواع الشائعة: <code>snmp</code>، <code>config</code>، <code>linkdown</code>، <code>bgp</code>، <code>ospf</code>.","en":"Chooses which event types are sent as SNMP traps.","ex":"<pre><span class=\"p\">R1(config)#</span> snmp-server enable traps snmp authentication linkdown linkup\n<span class=\"p\">R1(config)#</span> snmp-server enable traps config\n<span class=\"p\">R1#</span> show snmp</pre>","exPlain":"R1(config)# snmp-server enable traps snmp authentication linkdown linkup\nR1(config)# snmp-server enable traps config\nR1# show snmp","neg":"no snmp-server enable traps","kind":"cmd"},{"i":259,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"snmp-server group <i>name</i> v3 priv | snmp-server user <i>user</i> <i>group</i> v3 auth sha <i>pass</i> priv aes 128 <i>pass</i>","synPlain":"snmp-server group name v3 priv | snmp-server user user group v3 auth sha pass priv aes 128 pass","mode":"Global Config","modeCls":"m-gconf","ar":"SNMPv3 هو الإصدار الآمن (مصادقة وتشفير). v1 وv2c يرسلان الـ community كنص واضح. الإعداد من أربع قطع: group + user + host + engine ID. هذا هو المطلوب في أي تدقيق أمني.","en":"Configures SNMPv3 with authentication and encryption, the secure option.","ex":"<pre><span class=\"p\">R1(config)#</span> snmp-server group NMSGRP v3 priv\n<span class=\"p\">R1(config)#</span> snmp-server user nms NMSGRP v3 auth sha Auth@123 priv aes 128 Priv@123\n<span class=\"p\">R1(config)#</span> snmp-server host 10.1.1.100 version 3 priv nms\n<span class=\"p\">R1#</span> show snmp user</pre>","exPlain":"R1(config)# snmp-server group NMSGRP v3 priv\nR1(config)# snmp-server user nms NMSGRP v3 auth sha Auth@123 priv aes 128 Priv@123\nR1(config)# snmp-server host 10.1.1.100 version 3 priv nms\nR1# show snmp user","neg":"no snmp-server user nms NMSGRP v3","kind":"cmd"},{"i":260,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"ip name-server <i>ip1 ip2</i> | ip domain-lookup | ip host <i>name</i> <i>ip</i>","synPlain":"ip name-server ip1 ip2 | ip domain-lookup | ip host name ip","mode":"Global Config","modeCls":"m-gconf","ar":"<code>ip name-server</code> يحدد خوادم DNS. <code>ip host</code> ينشئ سجلاً محلياً (مثل /etc/hosts) — مفيد لأسماء الأجهزة في المعمل. في المعامل يُفضّل <code>no ip domain-lookup</code> لمنع الانتظار.","en":"Sets DNS servers, enables resolution, and adds static host entries.","ex":"<pre><span class=\"p\">R1(config)#</span> ip name-server 8.8.8.8 1.1.1.1\n<span class=\"p\">R1(config)#</span> ip domain-lookup\n<span class=\"p\">R1(config)#</span> ip host R2 10.1.1.2\n<span class=\"p\">R1#</span> ping R2</pre>","exPlain":"R1(config)# ip name-server 8.8.8.8 1.1.1.1\nR1(config)# ip domain-lookup\nR1(config)# ip host R2 10.1.1.2\nR1# ping R2","neg":"no ip host R2","kind":"cmd"},{"i":261,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"cdp run | cdp enable | no cdp run","synPlain":"cdp run | cdp enable | no cdp run","mode":"Global / Interface","modeCls":"m-gconf","ar":"Cisco Discovery Protocol — بروتوكول خاص بـ Cisco يعمل في الطبقة الثانية ويكتشف الجيران المباشرين مع موديلاتهم وعناوين IP وواجهاتهم. مفيد جداً في رسم الطوبولوجيا، لكنه ثغرة معلوماتية: يُفضّل تعطيله على الواجهات المتجهة للخارج.","en":"Enables Cisco Discovery Protocol globally or per interface for Layer 2 neighbour discovery.","ex":"<pre><span class=\"p\">R1(config)#</span> cdp run\n<span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> no cdp enable\n<span class=\"p\">R1#</span> show cdp neighbors detail</pre>","exPlain":"R1(config)# cdp run\nR1(config)# interface g0/0\nR1(config-if)# no cdp enable\nR1# show cdp neighbors detail","neg":"no cdp run","kind":"cmd"},{"i":262,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"lldp run | lldp transmit | lldp receive","synPlain":"lldp run | lldp transmit | lldp receive","mode":"Global / Interface","modeCls":"m-gconf","ar":"LLDP هو المعيار المفتوح (802.1AB) المكافئ لـ CDP ويعمل بين مصنّعين مختلفين. مفيد في الشبكات المختلطة. لاحظ أنه معطّل افتراضياً عالمياً على أجهزة Cisco.","en":"Enables the vendor-neutral LLDP with independent transmit and receive control.","ex":"<pre><span class=\"p\">R1(config)#</span> lldp run\n<span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> lldp transmit\n<span class=\"p\">R1(config-if)#</span> lldp receive\n<span class=\"p\">R1#</span> show lldp neighbors</pre>","exPlain":"R1(config)# lldp run\nR1(config)# interface g0/0\nR1(config-if)# lldp transmit\nR1(config-if)# lldp receive\nR1# show lldp neighbors","neg":"no lldp run","kind":"cmd"},{"i":263,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"ip ftp username <i>user</i> | ip ftp password <i>pass</i> | ip tftp source-interface <i>intf</i>","synPlain":"ip ftp username user | ip ftp password pass | ip tftp source-interface intf","mode":"Global Config","modeCls":"m-gconf","ar":"بيانات الاعتماد لخادم FTP، والواجهة المصدر لعمليات TFTP. تحديد <code>source-interface</code> ضروري عندما يكون للراوتر عدة مسارات، لضمان أن الرد يعود إلى نفس العنوان (وإلا تفشل عملية النسخ بصمت).","en":"Stores FTP credentials for copy operations and pins the source IP used for TFTP.","ex":"<pre><span class=\"p\">R1(config)#</span> ip ftp username backup\n<span class=\"p\">R1(config)#</span> ip ftp password Bkp@123\n<span class=\"p\">R1(config)#</span> ip tftp source-interface loopback 0\n<span class=\"p\">R1#</span> copy running-config ftp://backup@10.1.1.100/r1.cfg</pre>","exPlain":"R1(config)# ip ftp username backup\nR1(config)# ip ftp password Bkp@123\nR1(config)# ip tftp source-interface loopback 0\nR1# copy running-config ftp://backup@10.1.1.100/r1.cfg","neg":"no ip ftp username","kind":"cmd"},{"i":264,"sec":"svc","no":"17","secAr":"NTP / Syslog / SNMP","secEn":"Network Services","grp":"services","syn":"snmp-server host <i>ip</i> [version {2c | 3 auth | 3 priv}] <i>community-or-user</i>","synPlain":"snmp-server host ip [version {2c | 3 auth | 3 priv}] community-or-user","mode":"Global Config","modeCls":"m-glob","ar":"يحدد <b>مستقبِل</b> الـ traps — وهو ما ينساه كثيرون: تفعيل <code>enable traps</code> وحده لا يرسل شيئاً بلا <code>host</code>. استخدم <code>version 3 priv</code> في الإنتاج لأن v2c يرسل الـ community كنص واضح. تحقق من الوصول بـ <code>show snmp host</code> ثم <code>show snmp</code> لمتابعة العدادات.","en":"Defines where traps are sent. Enabling traps alone sends nothing without a host, and v3 priv is the only option that does not put the community string on the wire in clear text.","ex":"<pre><span class=\"p\">R1(config)#</span> snmp-server community S3cr3t RO\n<span class=\"p\">R1(config)#</span> snmp-server enable traps\n<span class=\"p\">R1(config)#</span> snmp-server host 10.10.10.50 version 3 priv NMSuser\n<span class=\"p\">R1#</span> show snmp host\nNotification host: 10.10.10.50  udp-port: 162  type: trap\nuser: NMSuser  security model: v3 priv</pre>","exPlain":"R1(config)# snmp-server community S3cr3t RO\nR1(config)# snmp-server enable traps\nR1(config)# snmp-server host 10.10.10.50 version 3 priv NMSuser\nR1# show snmp host\nNotification host: 10.10.10.50  udp-port: 162  type: trap\nuser: NMSuser  security model: v3 priv","neg":"no snmp-server host 10.10.10.50","kind":"cmd"},{"i":265,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"mls qos","synPlain":"mls qos","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"يفعّل QoS على سويتشات Catalyst. <b>تحذير:</b> بعد تفعيله تُعاد جميع المنافذ إلى <code>untrusted</code> وتُصفَّر إعدادات CoS — لذلك يُنفَّذ أولاً قبل أي إعداد آخر. على منصات 9K يُستخدم <code>qos</code> بدلاً منه.","en":"Enables QoS processing on the switch, which is globally off by default.","ex":"<pre><span class=\"p\">SW1(config)#</span> mls qos\n<span class=\"p\">SW1#</span> show mls qos</pre>","exPlain":"SW1(config)# mls qos\nSW1# show mls qos","neg":"no mls qos","kind":"cmd"},{"i":266,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"class-map <i>{match-all|match-any}</i> <i>name</i>","synPlain":"class-map {match-all|match-any} name","mode":"Global Config","modeCls":"m-gconf","ar":"يعرّف فئة ترافيك. <code>match-all</code> = يجب تحقق <b>كل</b> الشروط (AND)، و<code>match-any</code> = يكفي شرط واحد (OR). الاسم يبدأ بحرف كبير عادةً كاصطلاح. لا يمكن تغيير نوع المطابقة بعد الإنشاء.","en":"Groups traffic by match criteria; all means AND, any means OR.","ex":"<pre><span class=\"p\">R1(config)#</span> class-map match-any VOICE\n<span class=\"p\">R1(config-cmap)#</span> match dscp ef\n<span class=\"p\">R1(config-cmap)#</span> match access-group name VOICE-RTP\n<span class=\"p\">R1(config)#</span> class-map match-all CRITICAL\n<span class=\"p\">R1(config-cmap)#</span> match access-group 101\n<span class=\"p\">R1(config-cmap)#</span> match dscp af31</pre>","exPlain":"R1(config)# class-map match-any VOICE\nR1(config-cmap)# match dscp ef\nR1(config-cmap)# match access-group name VOICE-RTP\nR1(config)# class-map match-all CRITICAL\nR1(config-cmap)# match access-group 101\nR1(config-cmap)# match dscp af31","neg":"no class-map match-any VOICE","kind":"cmd"},{"i":267,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"match <i>dscp|cos|access-group|protocol|input-interface</i>","synPlain":"match dscp|cos|access-group|protocol|input-interface","mode":"Class-map Config","modeCls":"m-cmap","ar":"شروط التصنيف. <code>dscp</code> يطابق علامة الطبقة الثالثة، <code>cos</code> علامة الطبقة الثانية (<span class=\"num\">0–7</span>، تُستخدم على Trunks)، و<code>access-group</code> يطابق بعنوان/منفذ. يمكن استخدام <code>match not</code> للنفي.","en":"Defines the actual classification conditions inside a class-map.","ex":"<pre><span class=\"p\">R1(config-cmap)#</span> match dscp ef\n<span class=\"p\">R1(config-cmap)#</span> match cos 5\n<span class=\"p\">R1(config-cmap)#</span> match access-group name VOICE-RTP\n<span class=\"p\">R1(config-cmap)#</span> match not dscp default</pre>","exPlain":"R1(config-cmap)# match dscp ef\nR1(config-cmap)# match cos 5\nR1(config-cmap)# match access-group name VOICE-RTP\nR1(config-cmap)# match not dscp default","neg":"no match dscp ef","kind":"cmd"},{"i":268,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"policy-map <i>name</i> | class <i>{name|class-default}</i>","synPlain":"policy-map name | class {name|class-default}","mode":"Global Config","modeCls":"m-gconf","ar":"يربط الفئات بإجراءات. <code>class-default</code> هي الفئة التي تشمل كل ما لم يُطابق — يجب أن تبقى دائماً في النهاية وإلا فُقد الترافيك غير المصنّف.","en":"Binds classes to actions; class-default catches everything that is not matched.","ex":"<pre><span class=\"p\">R1(config)#</span> policy-map WAN-OUT\n<span class=\"p\">R1(config-pmap)#</span> class VOICE\n<span class=\"p\">R1(config-pmap-c)#</span> priority percent 20\n<span class=\"p\">R1(config-pmap)#</span> class CRITICAL\n<span class=\"p\">R1(config-pmap-c)#</span> bandwidth percent 30\n<span class=\"p\">R1(config-pmap)#</span> class class-default\n<span class=\"p\">R1(config-pmap-c)#</span> fair-queue</pre>","exPlain":"R1(config)# policy-map WAN-OUT\nR1(config-pmap)# class VOICE\nR1(config-pmap-c)# priority percent 20\nR1(config-pmap)# class CRITICAL\nR1(config-pmap-c)# bandwidth percent 30\nR1(config-pmap)# class class-default\nR1(config-pmap-c)# fair-queue","neg":"no policy-map WAN-OUT","kind":"cmd"},{"i":269,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"priority percent <i>n</i> | bandwidth percent <i>n</i> | police <i>rate</i>","synPlain":"priority percent n | bandwidth percent n | police rate","mode":"Policy-map Class Config","modeCls":"m-pmap-c","ar":"الإجراءات: <b>priority</b> = طابور أولوية (Low Latency Queue) للصوت — يُخدم أولاً ويُحدَّد سقفه، والزيادة تُسقَط. <b>bandwidth</b> = ضمان حد أدنى عند الازدحام (لا يمنع الزيادة). <b>police</b> = تحديد سقف صارم وإسقاط/تعليم الزائد.","en":"Reserves strict priority, guarantees a bandwidth share, or rate-limits the class.","ex":"<pre><span class=\"p\">R1(config-pmap-c)#</span> priority percent 20\n<span class=\"p\">R1(config-pmap-c)#</span> bandwidth percent 30\n<span class=\"p\">R1(config-pmap-c)#</span> police 1000000 conform-action transmit exceed-action drop\n<span class=\"p\">R1(config-pmap-c)#</span> set dscp af31</pre>","exPlain":"R1(config-pmap-c)# priority percent 20\nR1(config-pmap-c)# bandwidth percent 30\nR1(config-pmap-c)# police 1000000 conform-action transmit exceed-action drop\nR1(config-pmap-c)# set dscp af31","neg":"no priority percent 20","kind":"cmd"},{"i":270,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"service-policy <i>{input|output}</i> <i>policy-name</i>","synPlain":"service-policy {input|output} policy-name","mode":"Interface Config","modeCls":"m-iconf","ar":"يطبّق السياسة على الواجهة. <b>الاتجاه مهم:</b> غالباً تُطبَّق على <code>output</code> للواجهة المتجهة إلى WAN (لأن الازدحام يحدث عند الإرسال). تطبيق سياسة على <code>input</code> يفيد في التصنيف والتعليم فقط.","en":"Attaches the policy to an interface in one direction.","ex":"<pre><span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> service-policy output WAN-OUT\n<span class=\"p\">R1#</span> show policy-map interface g0/0</pre>","exPlain":"R1(config)# interface g0/0\nR1(config-if)# service-policy output WAN-OUT\nR1# show policy-map interface g0/0","neg":"no service-policy output WAN-OUT","kind":"cmd"},{"i":271,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"auto qos voip trust | auto qos voip cisco-phone","synPlain":"auto qos voip trust | auto qos voip cisco-phone","mode":"Interface Config","modeCls":"m-iconf","ar":"ماكرو يولّد إعداد QoS كامل لهاتف IP تلقائياً (class-maps، policy-maps، trust boundaries). <code>trust</code> يعني الثقة بعلامة الهاتف، و<code>cisco-phone</code> يضيف التحقق عبر CDP. أسرع طريقة لتشغيل QoS للصوت.","en":"Applies Cisco's pre-built voice QoS template with a single command.","ex":"<pre><span class=\"p\">SW1(config-if)#</span> auto qos voip cisco-phone\n<span class=\"p\">SW1#</span> show auto qos interface g0/1</pre>","exPlain":"SW1(config-if)# auto qos voip cisco-phone\nSW1# show auto qos interface g0/1","neg":"no auto qos voip","kind":"cmd"},{"i":272,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"monitor session <i>n</i> source interface <i>intf</i> <i>{rx|tx|both}</i>","synPlain":"monitor session n source interface intf {rx|tx|both}","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"يحدد المنفذ (أو الـ VLAN) الذي تُنسخ حزمه للمراقبة. يُستخدم لتوصيل محلّل شبكة (Wireshark) أو نظام IDS. <code>both</code> ينسخ الاتجاهين. يمكن تحديد عدة مصادر لنفس الجلسة.","en":"Selects the ports whose traffic is copied for capture.","ex":"<pre><span class=\"p\">SW1(config)#</span> monitor session 1 source interface g0/1 both\n<span class=\"p\">SW1(config)#</span> monitor session 1 source interface g0/2 rx\n<span class=\"p\">SW1(config)#</span> monitor session 1 source vlan 10 both</pre>","exPlain":"SW1(config)# monitor session 1 source interface g0/1 both\nSW1(config)# monitor session 1 source interface g0/2 rx\nSW1(config)# monitor session 1 source vlan 10 both","neg":"no monitor session 1","kind":"cmd"},{"i":273,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"monitor session <i>n</i> destination interface <i>intf</i> [<i>encapsulation replicate</i>]","synPlain":"monitor session n destination interface intf [encapsulation replicate]","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"يحدد منفذ الوجهة حيث يُرسل نسخة من الترافيك. هذا المنفذ لا يستخدم للترافيك العادي. <code>encapsulation replicate</code> يحافظ على وسوم VLAN في النسخة — ضروري عند تحليل ترافيك trunk.","en":"Selects the port where copied traffic is delivered to the analyser.","ex":"<pre><span class=\"p\">SW1(config)#</span> monitor session 1 destination interface g0/24 encapsulation replicate\n<span class=\"p\">SW1#</span> show monitor session 1</pre>","exPlain":"SW1(config)# monitor session 1 destination interface g0/24 encapsulation replicate\nSW1# show monitor session 1","neg":"no monitor session 1 destination","kind":"cmd"},{"i":274,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"monitor session <i>n</i> destination remote vlan <i>id</i>","synPlain":"monitor session n destination remote vlan id","mode":"Global Config (Switch)","modeCls":"m-gconf","ar":"RSPAN: إرسال نسخة الترافيك عبر الشبكة في VLAN مخصص إلى سويتش آخر. يسمح بالمراقبة عن بُعد دون جهاز على نفس السويتش. يتطلب تعريف نفس RSPAN VLAN على كل السويتشات الوسيطة.","en":"Sends SPAN traffic across a trunk to a remote capture device (RSPAN).","ex":"<pre><span class=\"p\">SW1(config)#</span> vlan 99\n<span class=\"p\">SW1(config-vlan)#</span> remote-span\n<span class=\"p\">SW1(config)#</span> monitor session 1 destination remote vlan 99</pre>","exPlain":"SW1(config)# vlan 99\nSW1(config-vlan)# remote-span\nSW1(config)# monitor session 1 destination remote vlan 99","neg":"no monitor session 1","kind":"cmd"},{"i":275,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"ip flow-export destination <i>ip</i> <i>port</i> | ip flow-export version 9","synPlain":"ip flow-export destination ip port | ip flow-export version 9","mode":"Global Config","modeCls":"m-gconf","ar":"يصدّر سجلات التدفق (من/إلى/بروتوكول/حجم/توقيت) إلى مُجمِّع (Collector). الإصدار 9 يدعم قوالب مرنة، والإصدار 5 بسيط وثابت. NetFlow يجيب على سؤال «من يستهلك النطاق؟» بدقة.","en":"Configures NetFlow export to a collector and the export format.","ex":"<pre><span class=\"p\">R1(config)#</span> ip flow-export destination 10.1.1.100 2055\n<span class=\"p\">R1(config)#</span> ip flow-export version 9\n<span class=\"p\">R1(config)#</span> ip flow-export source loopback 0</pre>","exPlain":"R1(config)# ip flow-export destination 10.1.1.100 2055\nR1(config)# ip flow-export version 9\nR1(config)# ip flow-export source loopback 0","neg":"no ip flow-export destination 10.1.1.100 2055","kind":"cmd"},{"i":276,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"ip flow ingress | ip flow egress","synPlain":"ip flow ingress | ip flow egress","mode":"Interface Config","modeCls":"m-iconf","ar":"يفعّل مراقبة التدفقات على الواجهة في اتجاه محدد. <code>ingress</code> هو الأكثر استخداماً لأنه يلتقط الترافيك قبل معالجته. لاحظ أن NetFlow يستهلك CPU وذاكرة — فعّله على نقاط محددة لا على كل الواجهات.","en":"Turns on NetFlow accounting in one or both directions on the interface.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ip flow ingress\n<span class=\"p\">R1#</span> show ip cache flow\n<span class=\"p\">R1#</span> show ip flow export</pre>","exPlain":"R1(config-if)# ip flow ingress\nR1# show ip cache flow\nR1# show ip flow export","neg":"no ip flow ingress","kind":"cmd"},{"i":277,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"show ip cache flow","synPlain":"show ip cache flow","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض التدفقات النشطة في الكاش: عناوين المصدر والهدف، المنافذ، البروتوكول، عدد الحزم والبایتات. أسرع طريقة لمعرفة ما يجري على الرابط الآن دون محلّل حزم.","en":"Shows the active NetFlow cache — top talkers, protocols, and flows.","ex":"<pre><span class=\"p\">R1#</span> show ip cache flow\nIP packet size distribution (1834 total packets):\nSrcIf  SrcIPaddress  DstIf  DstIPaddress  Pr SrcP DstP  Pkts\nGi0/1  192.168.10.5  Gi0/0  8.8.8.8       06 0C1A 01BB  24</pre>","exPlain":"R1# show ip cache flow\nIP packet size distribution (1834 total packets):\nSrcIf  SrcIPaddress  DstIf  DstIPaddress  Pr SrcP DstP  Pkts\nGi0/1  192.168.10.5  Gi0/0  8.8.8.8       06 0C1A 01BB  24","neg":"","kind":"cmd"},{"i":278,"sec":"qos","no":"18","secAr":"QoS وأدوات المراقبة","secEn":"QoS & Monitoring","grp":"services","syn":"shape average <i>target-bps</i>","synPlain":"shape average target-bps","mode":"Policy-map Class Config","modeCls":"m-pmap","ar":"يحدد <b>سقفاً</b> لمعدل الإرسال ويؤخّر (buffers) الزائد بدل إسقاطه — عكس <code>police</code> الذي يُسقط أو يعيد تصنيف الزائد. يُستخدم على حافة WAN حين تكون سرعة المزوّد أقل من سرعة الواجهة: بدونه تتراكم الطوابير في المزوّد ويزيد التأخير وفقدان الحزم. القاعدة العملية: <b>shape</b> صوب الشبكة، و<b>police</b> صوب المستخدم.","en":"Caps the sending rate and buffers the excess instead of dropping it. Use it toward a slower WAN provider link; use police toward users where dropping is acceptable.","ex":"<pre><span class=\"p\">R1(config)#</span> policy-map WAN-EDGE\n<span class=\"p\">R1(config-pmap)#</span> class class-default\n<span class=\"p\">R1(config-pmap-c)#</span> shape average 50000000\n<span class=\"p\">R1(config)#</span> interface GigabitEthernet0/1\n<span class=\"p\">R1(config-if)#</span> service-policy output WAN-EDGE\n<span class=\"p\">R1#</span> show policy-map interface Gi0/1\n    Shape: 50000000 bps, Target: 50 kbps, 0/0 packets delayed</pre>","exPlain":"R1(config)# policy-map WAN-EDGE\nR1(config-pmap)# class class-default\nR1(config-pmap-c)# shape average 50000000\nR1(config)# interface GigabitEthernet0/1\nR1(config-if)# service-policy output WAN-EDGE\nR1# show policy-map interface Gi0/1\n    Shape: 50000000 bps, Target: 50 kbps, 0/0 packets delayed","neg":"no shape average","kind":"cmd"},{"i":279,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"GET https://<i>controller</i>/api/v1/interface","synPlain":"GET https://controller/api/v1/interface","mode":"REST (Northbound)","modeCls":"m-any","ar":"مثال استدعاء REST لقراءة حالة الواجهات. الـ Headers تحتوي على رمز المصادقة (Token)، والاستجابة بصيغة <b>JSON</b>. هذا هو النمط الذي تعمل به كل أدوات الأتمتة الحديثة.","en":"A RESTCONF call returning interface data as JSON — the northbound API model of modern IOS-XE.","ex":"<pre>GET /api/v1/interface HTTP/1.1\nHost: catalyst-center.lab.local\nX-Auth-Token: eyJhbGciOiJIUzI1NiIs...\nAccept: application/json\n\n<span class=\"c\">// Response 200 OK</span>\n{\n  \"name\": \"GigabitEthernet1/0/1\",\n  \"status\": \"up\",\n  \"vlan\": 10,\n  \"speed\": \"1000\"\n}</pre>","exPlain":"GET /api/v1/interface HTTP/1.1\nHost: catalyst-center.lab.local\nX-Auth-Token: eyJhbGciOiJIUzI1NiIs...\nAccept: application/json\n\n// Response 200 OK\n{\n  \"name\": \"GigabitEthernet1/0/1\",\n  \"status\": \"up\",\n  \"vlan\": 10,\n  \"speed\": \"1000\"\n}","neg":"{}","kind":"concept"},{"i":280,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"python — استدعاء REST باستخدام requests","synPlain":"python — استدعاء REST باستخدام requests","mode":"Script","modeCls":"m-any","ar":"نفس الطلب برمجياً. الفكرة: <code>requests.get</code> = GET، و<code>json()</code> يحوّل الاستجابة إلى قاموس Python. هذا هو الجسر بين الشبكات والبرمجة، وهو ما يسأل عنه الامتحان بمستوى مفهومي.","en":"A minimal Python client that authenticates and reads the same data programmatically.","ex":"<pre>import requests\n\nurl = \"https://controller.lab.local/api/v1/interface\"\nheaders = {\"X-Auth-Token\": token, \"Accept\": \"application/json\"}\n\nr = requests.get(url, headers=headers, verify=False)\nprint(r.status_code)      <span class=\"c\"># 200</span>\nfor intf in r.json()[\"response\"]:\n    print(intf[\"name\"], intf[\"status\"])</pre>","exPlain":"import requests\n\nurl = \"https://controller.lab.local/api/v1/interface\"\nheaders = {\"X-Auth-Token\": token, \"Accept\": \"application/json\"}\n\nr = requests.get(url, headers=headers, verify=False)\nprint(r.status_code)      # 200\nfor intf in r.json()[\"response\"]:\n    print(intf[\"name\"], intf[\"status\"])","neg":"","kind":"concept"},{"i":281,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"netconf-yang","synPlain":"netconf-yang","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل خادم NETCONF مع نماذج YANG على الجهاز. NETCONF يعمل عبر SSH (المنفذ 830) ويستخدم XML. هو المعيار المفضّل لتكوين الأجهزة برمجياً لأنه <b>معياري ونموذجي</b> وليس شاشة أوامر.","en":"Enables the NETCONF/YANG interface for model-driven configuration.","ex":"<pre><span class=\"p\">R1(config)#</span> netconf-yang\n<span class=\"p\">R1(config)#</span> netconf-yang feature candidate-datastore\n<span class=\"p\">R1#</span> show netconf-yang sessions</pre>","exPlain":"R1(config)# netconf-yang\nR1(config)# netconf-yang feature candidate-datastore\nR1# show netconf-yang sessions","neg":"no netconf-yang","kind":"concept"},{"i":282,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"restconf","synPlain":"restconf","mode":"Global Config","modeCls":"m-gconf","ar":"يفعّل واجهة RESTCONF — REST فوق HTTPS مع بيانات JSON/XML ونماذج YANG. أسهل من NETCONF لمن اعتاد على REST. يتطلب <code>ip http secure-server</code> ومستخدم بصلاحية مناسبة.","en":"Enables the RESTCONF HTTP/JSON interface used by most automation tools.","ex":"<pre><span class=\"p\">R1(config)#</span> ip http secure-server\n<span class=\"p\">R1(config)#</span> restconf\n<span class=\"p\">R1(config)#</span> ip http authentication local\n<span class=\"p\">R1#</span> show platform software yang-management process</pre>","exPlain":"R1(config)# ip http secure-server\nR1(config)# restconf\nR1(config)# ip http authentication local\nR1# show platform software yang-management process","neg":"no restconf","kind":"concept"},{"i":283,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"show running-config | section <i>keyword</i> | show version | include <i>text</i>","synPlain":"show running-config | section keyword | show version | include text","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"أدوات التحقق التي تعتمد عليها السكربتات: استخراج جزء محدد من الإعداد أو المخرجات. في الأتمتة تُستخدم هذه المخرجات للتحقق (Idempotency Check) قبل تطبيق تغيير.","en":"Filters show output with regular expressions — essential on large configurations.","ex":"<pre><span class=\"p\">R1#</span> show running-config | section interface GigabitEthernet0/1\n<span class=\"p\">R1#</span> show version | include uptime\n<span class=\"p\">R1#</span> show ip interface brief | exclude unassigned</pre>","exPlain":"R1# show running-config | section interface GigabitEthernet0/1\nR1# show version | include uptime\nR1# show ip interface brief | exclude unassigned","neg":"","kind":"concept"},{"i":284,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"Ansible playbook — مثال بنيوي","synPlain":"Ansible playbook — مثال بنيوي","mode":"Automation","modeCls":"m-any","ar":"Ansible هو الأكثر شيوعاً في الشبكات لأنه <b>لا يحتاج تثبيت وكيل</b> على الأجهزة (يكفي SSH). الـ Playbook ملف YAML يصف الحالة المطلوبة، والأداة تتولّى التنفيذ والتحقق. لاحظ مفهوم <b>Idempotency</b>: تشغيل نفس الملف مرتين لا يغيّر شيئاً في المرة الثانية.","en":"Declarative, idempotent automation that pushes the same configuration to many devices.","ex":"<pre>- name: Configure VLANs\n  hosts: switches\n  gather_facts: no\n  tasks:\n    - name: Create VLAN 10\n      cisco.ios.ios_vlans:\n        config:\n          - vlan_id: 10\n            name: SALES\n        state: merged</pre>","exPlain":"- name: Configure VLANs\n  hosts: switches\n  gather_facts: no\n  tasks:\n    - name: Create VLAN 10\n      cisco.ios.ios_vlans:\n        config:\n          - vlan_id: 10\n            name: SALES\n        state: merged","neg":"","kind":"concept"},{"i":285,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"Catalyst Center (DNA Center) — Workflows","synPlain":"Catalyst Center (DNA Center) — Workflows","mode":"SDN Controller","modeCls":"m-any","ar":"منصة Cisco المركزية لإدارة الشبكة. الوظائف الأساسية التي يسأل عنها الامتحان: <b>Design</b> (تصميم المواقع والطوبولوجيا) → <b>Policy</b> (سياسات الوصول) → <b>Provision</b> (نشر الأجهزة) → <b>Assurance</b> (مراقبة وتحليل بالذكاء الاصطناعي). تعمل عبر REST API شمالاً وNETCONF/SNMP جنوباً.","en":"Controller-based provisioning, assurance, and fabric management for campus networks.","ex":"<pre><span class=\"c\">// مكوّنات أساسية</span>\nDesign      → Sites, Network Settings, Device Credentials\nPolicy      → Group-Based Access Control (GBAC), IP-based\nProvision   → Device Discovery, Templates, Plug-and-Play\nAssurance   → Health Scores, AI Network Analytics, Path Trace</pre>","exPlain":"// مكوّنات أساسية\nDesign      → Sites, Network Settings, Device Credentials\nPolicy      → Group-Based Access Control (GBAC), IP-based\nProvision   → Device Discovery, Templates, Plug-and-Play\nAssurance   → Health Scores, AI Network Analytics, Path Trace","neg":"","kind":"concept"},{"i":286,"sec":"auto","no":"19","secAr":"الأتمتة وSDN","secEn":"Automation & SDN","grp":"modern","syn":"guestshell enable | guestshell run <i>command</i>","synPlain":"guestshell enable | guestshell run command","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يفعّل <b>Guestshell</b>: حاوية Linux على IOS-XE تسمح بتشغيل سكربتات Python وEEM وأدوات مفتوحة المصدر على الجهاز نفسه بلا خادم خارجي. تفعيلها يتطلب مساحة قرص وإصدار IOS-XE حديثاً (16.6+). للتحقق: <code>show guestshell detail</code>. البديل الأخف هو Python مباشرة في الـ EXEC إن كان الإصدار يدعمه.","en":"Turns on the Linux container inside IOS-XE so Python, EEM and open-source tooling can run on-box without an external server.","ex":"<pre><span class=\"p\">R1#</span> guestshell enable\n<span class=\"p\">R1#</span> guestshell run python3 --version\nPython 3.8.2\n<span class=\"p\">R1#</span> show guestshell detail\nVirtual Port Group 0 - 192.168.35.1/24\nGuestshell Enabled: True  State: RUNNING</pre>","exPlain":"R1# guestshell enable\nR1# guestshell run python3 --version\nPython 3.8.2\nR1# show guestshell detail\nVirtual Port Group 0 - 192.168.35.1/24\nGuestshell Enabled: True  State: RUNNING","neg":"guestshell disable","kind":"cmd"},{"i":287,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"show sysinfo | show interface summary","synPlain":"show sysinfo | show interface summary","mode":"WLC EXEC","modeCls":"m-pexec","ar":"أوامر التحقق الأساسية على وحدة التحكم: معلومات النظام والإصدار، وحالة الواجهات (Management، Service-port، Virtual، Dynamic). واجهة <b>Virtual</b> ضرورية لعمل roaming وDHCP Relay.","en":"Baseline WLC health check: software version, uptime, and port status.","ex":"<pre><span class=\"p\">&gt;</span> show sysinfo\nProduct Version.................................. 8.10.181.0\nSystem Name...................................... WLC-01\n<span class=\"p\">&gt;</span> show interface summary\nInterface Name  Port  Vlan  IP Address      Type\nmanagement      1     10    10.1.10.10      Static\nvirtual         -     N/A   192.0.2.1       Static</pre>","exPlain":"> show sysinfo\nProduct Version.................................. 8.10.181.0\nSystem Name...................................... WLC-01\n> show interface summary\nInterface Name  Port  Vlan  IP Address      Type\nmanagement      1     10    10.1.10.10      Static\nvirtual         -     N/A   192.0.2.1       Static","neg":"","kind":"concept"},{"i":288,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"config wlan create <i>id</i> <i>name</i> <i>ssid</i>","synPlain":"config wlan create id name ssid","mode":"WLC Config","modeCls":"m-pexec","ar":"ينشئ WLAN (شبكة لاسلكية) برقم واسم وSSID. الـ WLAN ID من 1 إلى 512. بعد الإنشاء يكون معطّلاً افتراضياً — يجب <code>enable</code>.","en":"Creates a WLAN profile (ID, profile name, SSID) on an AireOS controller.","ex":"<pre><span class=\"p\">&gt;</span> config wlan create 10 CORP-WIFI CORP-WIFI\n<span class=\"p\">&gt;</span> config wlan interface 10 management\n<span class=\"p\">&gt;</span> config wlan enable 10\n<span class=\"p\">&gt;</span> show wlan summary</pre>","exPlain":"> config wlan create 10 CORP-WIFI CORP-WIFI\n> config wlan interface 10 management\n> config wlan enable 10\n> show wlan summary","neg":"config wlan disable 10","kind":"cmd"},{"i":289,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"config wlan security wpa akm psk set-key ascii 0 <i>key</i>","synPlain":"config wlan security wpa akm psk set-key ascii 0 key","mode":"WLC Config","modeCls":"m-pexec","ar":"يضبط WPA2-PSK (كلمة سر مشتركة). الرقم <code>0</code> يعني أن المفتاح ASCII (وليس Hex). للشبكات المؤسسية استخدم <code>802.1x</code> مع خادم RADIUS بدلاً من PSK.","en":"Sets WPA2 or WPA3 with a pre-shared key on the WLAN.","ex":"<pre><span class=\"p\">&gt;</span> config wlan disable 10\n<span class=\"p\">&gt;</span> config wlan security wpa akm psk enable 10\n<span class=\"p\">&gt;</span> config wlan security wpa akm psk set-key ascii 0 Corp@12345\n<span class=\"p\">&gt;</span> config wlan enable 10</pre>","exPlain":"> config wlan disable 10\n> config wlan security wpa akm psk enable 10\n> config wlan security wpa akm psk set-key ascii 0 Corp@12345\n> config wlan enable 10","neg":"config wlan security wpa akm 802.1x enable 10","kind":"cmd"},{"i":290,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"config wlan radius_server auth add <i>wlan-id</i> <i>server-ip</i>","synPlain":"config wlan radius_server auth add wlan-id server-ip","mode":"WLC Config","modeCls":"m-pexec","ar":"يربط WLAN بخادم RADIUS للمصادقة 802.1X. التسلسل: تعريف الخادم أولاً (<code>config radius auth add</code>) ثم ربطه بالـ WLAN. هذا هو أساس أمان المؤسسات (WPA2/WPA3-Enterprise).","en":"Points the WLAN at a RADIUS server for 802.1X authentication.","ex":"<pre><span class=\"p\">&gt;</span> config radius auth add 1 10.1.1.50 1812 ascii Radius@123\n<span class=\"p\">&gt;</span> config wlan radius_server auth add 10 10.1.1.50\n<span class=\"p\">&gt;</span> show radius summary</pre>","exPlain":"> config radius auth add 1 10.1.1.50 1812 ascii Radius@123\n> config wlan radius_server auth add 10 10.1.1.50\n> show radius summary","neg":"config wlan radius_server auth delete 10 10.1.1.50","kind":"cmd"},{"i":291,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"config wlan broadcast-ssid disable <i>id</i>","synPlain":"config wlan broadcast-ssid disable id","mode":"WLC Config","modeCls":"m-pexec","ar":"يخفي اسم الشبكة (Hidden SSID). <b>ليس إجراءً أمنياً حقيقياً:</b> الأدوات تكشف الشبكات المخفية بسهولة، والعميل يرسل اسم الشبكة في كل مكان. الأمان الحقيقي هو WPA2/WPA3 + 802.1X.","en":"Hides the SSID from beacon frames — a weak but very common hardening step.","ex":"<pre><span class=\"p\">&gt;</span> config wlan broadcast-ssid disable 10</pre>","exPlain":"> config wlan broadcast-ssid disable 10","neg":"config wlan broadcast-ssid enable 10","kind":"cmd"},{"i":292,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"show client summary | show ap summary","synPlain":"show client summary | show ap summary","mode":"WLC EXEC","modeCls":"m-pexec","ar":"الأول يعرض العملاء المتصلين (MAC، AP، WLAN، الحالة، البروتوكول)، والثاني يعرض الـ APs المنضمّة (الاسم، الموقع، عدد العملاء، الحالة). أسرع طريقة للتحقق من نجاح الانضمام والاتصال.","en":"Lists associated clients and joined access points.","ex":"<pre><span class=\"p\">&gt;</span> show client summary\nNumber of Clients................................ 12\nMAC Address        AP Name     Status  WLAN  Protocol\n00:50:79:66:68:00  AP-Floor1   Associated 10  802.11ac\n<span class=\"p\">&gt;</span> show ap summary\nNumber of APs.................................... 4</pre>","exPlain":"> show client summary\nNumber of Clients................................ 12\nMAC Address        AP Name     Status  WLAN  Protocol\n00:50:79:66:68:00  AP-Floor1   Associated 10  802.11ac\n> show ap summary\nNumber of APs.................................... 4","neg":"","kind":"cmd"},{"i":293,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"save config","synPlain":"save config","mode":"WLC EXEC","modeCls":"m-pexec","ar":"يحفظ إعداد WLC في NVRAM. <b>بدونه تُفقد كل التغييرات عند إعادة التشغيل</b> — وهو ما يعادل <code>copy run start</code> على الراوتر. يُنسى كثيراً في المعامل.","en":"Persists the WLC configuration to NVRAM; the controller does not save automatically.","ex":"<pre><span class=\"p\">&gt;</span> save config\nAre you sure you want to save? (y/n) <span class=\"p\">y</span>\nConfiguration Saved!</pre>","exPlain":"> save config\nAre you sure you want to save? (y/n) y\nConfiguration Saved!","neg":"show run-config commands","kind":"cmd"},{"i":294,"sec":"wlan","no":"20","secAr":"الشبكات اللاسلكية","secEn":"Wireless","grp":"modern","syn":"wireless profile policy <i>name</i> | wlan <i>name</i> <i>id</i> <i>ssid</i>","synPlain":"wireless profile policy name | wlan name id ssid","mode":"Global Config","modeCls":"m-gconf","ar":"في 9800 تُعرَّف سياسة لاسلكية (VLAN، واجهة، DHCP) ثم يُنشأ WLAN ويرتبط بالسياسة. الأوامر تختلف بين الإصدارات، لذا اعتمد على <code>?</code> داخل الوضع للتأكد من الصيغة الدقيقة.","en":"IOS-XE wireless configuration for a WLAN and its policy profile.","ex":"<pre><span class=\"p\">WLC(config)#</span> wireless profile policy CORP-POLICY\n<span class=\"p\">WLC(config-wireless-policy)#</span> vlan 10\n<span class=\"p\">WLC(config-wireless-policy)#</span> no shutdown\n<span class=\"p\">WLC(config)#</span> wlan CORP-WIFI 10 CORP-WIFI\n<span class=\"p\">WLC(config-wlan)#</span> policy CORP-POLICY\n<span class=\"p\">WLC(config-wlan)#</span> no shutdown</pre>","exPlain":"WLC(config)# wireless profile policy CORP-POLICY\nWLC(config-wireless-policy)# vlan 10\nWLC(config-wireless-policy)# no shutdown\nWLC(config)# wlan CORP-WIFI 10 CORP-WIFI\nWLC(config-wlan)# policy CORP-POLICY\nWLC(config-wlan)# no shutdown","neg":"show wlan summary","kind":"cmd"},{"i":295,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show processes cpu sorted","synPlain":"show processes cpu sorted","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض العمليات مرتّبة حسب استهلاك المعالج. راقب سطر <code>CPU utilization for five seconds</code>؛ إن تجاوز 80% باستمرار فابحث عن عملية واحدة مسيطرة: <b>ARP Input</b> عادةً تعني حلقة L2 أو هجوماً، و<b>IP Input</b> تعني ترافيكاً موجّهاً للمعالج (Punt).","en":"Lists processes by CPU usage; a sustained value above 80% or one dominant process (ARP Input, IP Input) points to a loop or punted traffic.","ex":"<pre><span class=\"p\">Router#</span> show processes cpu sorted\nCPU utilization for five seconds: 12%/0%; one minute: 11%; five minutes: 10%\n PID  Runtime(ms)  Invoked  uSecs  5Sec   1Min   5Min  TTY Process\n   1            0        1      0  0.00%  0.00%  0.00%   0 Chunk Manager\n   2          812    10233     79  0.31%  0.42%  0.40%   0 Load Meter</pre>","exPlain":"Router# show processes cpu sorted\nCPU utilization for five seconds: 12%/0%; one minute: 11%; five minutes: 10%\n PID  Runtime(ms)  Invoked  uSecs  5Sec   1Min   5Min  TTY Process\n   1            0        1      0  0.00%  0.00%  0.00%   0 Chunk Manager\n   2          812    10233     79  0.31%  0.42%  0.40%   0 Load Meter","neg":"","kind":"cmd"},{"i":296,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show processes memory sorted","synPlain":"show processes memory sorted","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يرتّب العمليات حسب الذاكرة المحجوزة. تسرّب الذاكرة يظهر كنموّ مطّرد في عمود <code>Holding</code> لعملية واحدة بينما <code>Free</code> يتقلّص حتى يفشل الجهاز في تخصيص المخازن ويبدأ بإعادة التشغيل.","en":"Shows memory per process; a steadily growing Holding value with shrinking Free memory indicates a leak.","ex":"<pre><span class=\"p\">Router#</span> show processes memory sorted\nProcessor Pool Total: 268435456  Used: 91234567  Free: 177200889\n PID  TTY  Allocated      Freed    Holding  Getbufs  Retbufs Process\n  12    0   41234567   12345678   28888889        0        0 BGP Router</pre>","exPlain":"Router# show processes memory sorted\nProcessor Pool Total: 268435456  Used: 91234567  Free: 177200889\n PID  TTY  Allocated      Freed    Holding  Getbufs  Retbufs Process\n  12    0   41234567   12345678   28888889        0        0 BGP Router","neg":"","kind":"cmd"},{"i":297,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show environment all","synPlain":"show environment all","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الحرارة والجهد وسرعة المراوح وحالة مصادر الطاقة. أي <code>Critical</code> أو <code>Shutdown</code> هنا يفسّر إعادة تشغيل مفاجئة أو سقوط منافذ PoE دفعة واحدة.","en":"Reports temperature, voltage, fan and PSU state; Critical or Shutdown values explain reboots and PoE outages.","ex":"<pre><span class=\"p\">Router#</span> show environment all\nSW 1 TEMPERATURE: 34 Celsius, State: Normal\nFAN 1: 7200 RPM, State: Normal\nPS 1: OK</pre>","exPlain":"Router# show environment all\nSW 1 TEMPERATURE: 34 Celsius, State: Normal\nFAN 1: 7200 RPM, State: Normal\nPS 1: OK","neg":"","kind":"cmd"},{"i":298,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show inventory","synPlain":"show inventory","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يسرد المكوّنات المثبّتة بأرقامها التسلسلية وأسماء الـ PID. أساسي قبل فتح تذكرة TAC، وقبل ترقية IOS للتأكد من مطابقة اسم الصورة للمنصّة.","en":"Lists installed hardware with PID and serial numbers — needed for TAC cases and image compatibility checks.","ex":"<pre><span class=\"p\">Router#</span> show inventory\nNAME: \"Chassis\", DESCR: \"Cisco ISR 4331\"\nPID: ISR4331/K9, VID: V02, SN: FDO2312A0AB</pre>","exPlain":"Router# show inventory\nNAME: \"Chassis\", DESCR: \"Cisco ISR 4331\"\nPID: ISR4331/K9, VID: V02, SN: FDO2312A0AB","neg":"","kind":"cmd"},{"i":299,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"test cable-diagnostics tdr interface [interface]","synPlain":"test cable-diagnostics tdr interface [interface]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يفحص زوج الكابل بصدى النبضات (TDR) فيكشف القطع والمسافة بالأمتار والأزواج الملتوية. يعمل على منافذ النحاس في سويتشات Catalyst، ويوفّر عليك نزولاً إلى الموقع.","en":"Runs a Time Domain Reflectometer test on a copper port and reports open/short pairs with distance in metres.","ex":"<pre><span class=\"p\">SW1#</span> test cable-diagnostics tdr interface gi1/0/5\nTDR test started on interface Gi1/0/5\nPair A: good, length 12 m\nPair B: OPEN, length 4 m</pre>","exPlain":"SW1# test cable-diagnostics tdr interface gi1/0/5\nTDR test started on interface Gi1/0/5\nPair A: good, length 12 m\nPair B: OPEN, length 4 m","neg":"","kind":"cmd"},{"i":300,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show interfaces [interface] switchport","synPlain":"show interfaces [interface] switchport","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يكشف الإعداد <b>الفعلي</b> بعد التفاوض: <code>Administrative Mode</code> مقابل <code>Operational Mode</code>. إن كان الإداري trunk والفعلي static access فاعلم أن الطرف الآخر access أو أن DTP مُعطَّل على أحدهما.","en":"Compares the configured mode with the negotiated operational mode — the fastest way to prove a trunk/access mismatch.","ex":"<pre><span class=\"p\">SW1#</span> show interfaces gi1/0/5 switchport\nName: Gi1/0/5\nAdministrative Mode: trunk\nOperational Mode: static access\nAccess Mode VLAN: 10 (USERS)</pre>","exPlain":"SW1# show interfaces gi1/0/5 switchport\nName: Gi1/0/5\nAdministrative Mode: trunk\nOperational Mode: static access\nAccess Mode VLAN: 10 (USERS)","neg":"","kind":"cmd"},{"i":301,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show vlan brief","synPlain":"show vlan brief","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض كل VLAN بمعرّفها وحالتها والمنافذ المخصّصة لها. منفذ غائب عن القائمة إما في وضع trunk أو أن الـ VLAN غير معرّفة عليه — وهذا سبب شائع لعدم ظهور العميل في الشبكة.","en":"Lists VLANs with status and member ports; a missing port means it is trunking or the VLAN is not defined locally.","ex":"<pre><span class=\"p\">SW1#</span> show vlan brief\nVLAN Name        Status    Ports\n10   USERS       active    Gi1/0/5, Gi1/0/6\n99   MGMT        active    Gi1/0/24</pre>","exPlain":"SW1# show vlan brief\nVLAN Name        Status    Ports\n10   USERS       active    Gi1/0/5, Gi1/0/6\n99   MGMT        active    Gi1/0/24","neg":"","kind":"cmd"},{"i":302,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show interfaces trunk","synPlain":"show interfaces trunk","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض منافذ الـ trunk وطريقة التغليف والـ native VLAN وقائمة الـ VLANs المسموحة والفعّالة. ركّز على <code>Vlans allowed and active in management domain</code> فهو ما يمرّ فعلاً، لا مجرد <code>allowed</code>.","en":"Shows trunk ports, encapsulation, native VLAN and the VLANs actually allowed and active on each trunk.","ex":"<pre><span class=\"p\">SW1#</span> show interfaces trunk\nPort     Mode  Encapsulation  Status    Native vlan\nGi1/0/1  on    802.1q         trunking  1\nPort     Vlans allowed and active in management domain\nGi1/0/1  1,10,20,99</pre>","exPlain":"SW1# show interfaces trunk\nPort     Mode  Encapsulation  Status    Native vlan\nGi1/0/1  on    802.1q         trunking  1\nPort     Vlans allowed and active in management domain\nGi1/0/1  1,10,20,99","neg":"","kind":"cmd"},{"i":303,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show mac address-table [address mac] [interface intf]","synPlain":"show mac address-table [address mac] [interface intf]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يربط عنوان MAC بالمنفذ والـ VLAN — الأداة الأولى لتتبّع جهاز أو اكتشاف حلقة. لاحظ النوع <code>DYNAMIC</code> مقابل <code>STATIC</code> و<code>SECURE</code>، وتذكّر أن عنواناً يتنقّل بين منفذين متتاليين يعني حلقة.","en":"Maps MAC addresses to ports and VLANs; the same MAC flapping between two ports is the classic signature of a loop.","ex":"<pre><span class=\"p\">SW1#</span> show mac address-table | include Gi1/0/5\n  10  0011.2233.4455   DYNAMIC   Gi1/0/5</pre>","exPlain":"SW1# show mac address-table | include Gi1/0/5\n  10  0011.2233.4455   DYNAMIC   Gi1/0/5","neg":"","kind":"cmd"},{"i":304,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show spanning-tree [vlan vlan-id]","synPlain":"show spanning-tree [vlan vlan-id]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الجذر الحالي وأولوية كل جسر وحالة كل منفذ (<code>Root/FWD</code>، <code>Desg/FWD</code>، <code>Altn/BLK</code>). منفذ في حالة <code>Altn</code> على المسار المتوقّع نحو الجذر يعني خطأ في التصميم أو في الـ cost.","en":"Displays the root bridge, bridge priorities and per-port roles and states for each VLAN.","ex":"<pre><span class=\"p\">SW1#</span> show spanning-tree\nVLAN0010\n  Root ID    Priority    4096, Address 0011.2233.0001\n  Bridge ID  Priority    4096, Address 0011.2233.0001\n  This bridge is the root\nInterface  Role Sts Cost\nGi1/0/1    Desg FWD   4</pre>","exPlain":"SW1# show spanning-tree\nVLAN0010\n  Root ID    Priority    4096, Address 0011.2233.0001\n  Bridge ID  Priority    4096, Address 0011.2233.0001\n  This bridge is the root\nInterface  Role Sts Cost\nGi1/0/1    Desg FWD   4","neg":"","kind":"cmd"},{"i":305,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show power inline [interface]","synPlain":"show power inline [interface]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض حالة PoE لكل منفذ: <code>on</code> أو <code>off</code> أو <code>faulty</code>، والواط المستهلك وميزانية الجهاز. <code>faulty</code> تعني كابل تالف أو جهازاً يسحب أكثر من حدّ المنفذ، و<code>denied</code> تعني أن الميزانية استُنفدت.","en":"Shows PoE state and wattage per port; faulty means a bad cable or an over-drawing device, denied means the budget is exhausted.","ex":"<pre><span class=\"p\">SW1#</span> show power inline\nInterface  Admin  Oper   Power  Device\nGi1/0/7    auto   on     6.4    IP Phone</pre>","exPlain":"SW1# show power inline\nInterface  Admin  Oper   Power  Device\nGi1/0/7    auto   on     6.4    IP Phone","neg":"","kind":"cmd"},{"i":306,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip interface [interface]","synPlain":"show ip interface [interface]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"النسخة المفصّلة التي تشرح <b>سبب</b> تعطّل الواجهة: هل العنوان غير معيّن، هل هناك ACL خارج أو داخل، هل هناك helper-address، وما حالة الـ broadcast. لا تكتفِ بـ <code>brief</code> عند التشخيص.","en":"Detailed per-interface IP view: assigned address, ACLs, helper addresses and broadcast handling.","ex":"<pre><span class=\"p\">Router#</span> show ip interface gi0/1\nGigabitEthernet0/1 is up, line protocol is up\n  Internet address is 10.1.1.1/24\n  Broadcast address is 255.255.255.255\n  Outgoing access list is not set</pre>","exPlain":"Router# show ip interface gi0/1\nGigabitEthernet0/1 is up, line protocol is up\n  Internet address is 10.1.1.1/24\n  Broadcast address is 255.255.255.255\n  Outgoing access list is not set","neg":"","kind":"cmd"},{"i":307,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip arp [ip]","synPlain":"show ip arp [ip]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يتحقق من نجاح التحليل بين IP وMAC. الحالة <code>Incomplete</code> تعني أن طلب ARP لا يلقى رداً: غالباً VLAN خاطئ، أو منفذ محجوب بـ port-security، أو الجهاز مطفأ.","en":"Verifies IP-to-MAC resolution; an Incomplete entry means ARP replies are not coming back.","ex":"<pre><span class=\"p\">Router#</span> show ip arp\nProtocol  Address    Age  Hardware Addr   Type  Interface\nInternet  10.1.1.1     -  aabb.cc00.0100  ARPA  GigabitEthernet0/1\nInternet  10.1.1.9     0  0011.2233.4455  ARPA  GigabitEthernet0/1</pre>","exPlain":"Router# show ip arp\nProtocol  Address    Age  Hardware Addr   Type  Interface\nInternet  10.1.1.1     -  aabb.cc00.0100  ARPA  GigabitEthernet0/1\nInternet  10.1.1.9     0  0011.2233.4455  ARPA  GigabitEthernet0/1","neg":"","kind":"cmd"},{"i":308,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip protocols","synPlain":"show ip protocols","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"ملخّص لكل بروتوكول توجيه عامل: رقم العملية أو الـ AS، والشبكات المعلنة، والمسافة الإدارية، والجيران، ومواضع <code>passive-interface</code>. أسرع إجابة عن سؤال «لماذا لا يُعلَن هذا المسار؟».","en":"Summarises every running routing protocol: process, advertised networks, distance, neighbours and passive interfaces.","ex":"<pre><span class=\"p\">Router#</span> show ip protocols\nRouting Protocol is \"ospf 1\"\n  Router ID 10.1.1.1\n  Number of areas in this router is 1\n  Passive Interface(s): Gi0/2</pre>","exPlain":"Router# show ip protocols\nRouting Protocol is \"ospf 1\"\n  Router ID 10.1.1.1\n  Number of areas in this router is 1\n  Passive Interface(s): Gi0/2","neg":"","kind":"cmd"},{"i":309,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip ospf neighbor [detail]","synPlain":"show ip ospf neighbor [detail]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الجيران وحالتهم. <code>FULL/DR</code> أو <code>FULL/BDR</code> سليم، و<code>INIT</code> يعني أن Hello يُرسل ولا يُستقبل، و<code>EXSTART/EXCHANGE</code> شبه دائماً اختلاف MTU، و<code>2WAY</code> طبيعية مع DROther.","en":"Neighbour states decode the failure: INIT means one-way hellos, EXSTART/EXCHANGE means an MTU mismatch.","ex":"<pre><span class=\"p\">Router#</span> show ip ospf neighbor\nNeighbor ID  Pri  State      Dead Time  Address   Interface\n10.1.1.2       1  FULL/BDR   00:00:34   10.1.1.2  Gi0/0</pre>","exPlain":"Router# show ip ospf neighbor\nNeighbor ID  Pri  State      Dead Time  Address   Interface\n10.1.1.2       1  FULL/BDR   00:00:34   10.1.1.2  Gi0/0","neg":"","kind":"cmd"},{"i":310,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip ospf interface brief","synPlain":"show ip ospf interface brief","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"لكل واجهة: المنطقة والـ cost والحالة وعدد الجيران ودور DR/BDR. يكشف فوراً واجهة في <code>LOOPBACK</code> بالخطأ، أو منطقة خاطئة، أو cost غير منطقي يجعل المسار يسلك رابطاً بطيئاً.","en":"Per-interface OSPF state: area, cost, DR/BDR role and neighbour counts.","ex":"<pre><span class=\"p\">Router#</span> show ip ospf interface brief\nInterface  PID  Area  IP Address/Mask  Cost  State  Nbrs F/C\nGi0/0        1     0  10.1.1.1/24         1  DR     1/1</pre>","exPlain":"Router# show ip ospf interface brief\nInterface  PID  Area  IP Address/Mask  Cost  State  Nbrs F/C\nGi0/0        1     0  10.1.1.1/24         1  DR     1/1","neg":"","kind":"cmd"},{"i":311,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip ospf database","synPlain":"show ip ospf database","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض قاعدة حالة الرابط كاملة بأنواعها: 1 Router و2 Network و3 Summary و5 External. راوتر يرى LSA 1 لجاره ولا يرى LSA 3 يعني أن الـ ABR لا يلخّص، أو أن المنطقة غير متصلة بالعمود الفقري.","en":"Dumps the link-state database; missing type-3 LSAs point to summarisation or area-connectivity problems.","ex":"<pre><span class=\"p\">Router#</span> show ip ospf database\n            Router Link States (Area 0)\nLink ID    ADV Router  Age  Seq#       Checksum  Link count\n10.1.1.1   10.1.1.1    124  0x80000004 0x00A1B2   1</pre>","exPlain":"Router# show ip ospf database\n            Router Link States (Area 0)\nLink ID    ADV Router  Age  Seq#       Checksum  Link count\n10.1.1.1   10.1.1.1    124  0x80000004 0x00A1B2   1","neg":"","kind":"cmd"},{"i":312,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip eigrp neighbors [detail]","synPlain":"show ip eigrp neighbors [detail]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الجيران وعمود <code>Q Cnt</code> (الحزم المنتظرة في الطابور) و<code>SRTT</code> و<code>RTO</code>. رقم <code>Q Cnt</code> متزايد لا يعني مشكلة في EIGRP بل أن الجهاز لا يواكب التحديثات بسبب ازدحام أو سرعة رابط.","en":"EIGRP neighbours with retransmission queue depth; a growing Q count means the box cannot keep up, not an EIGRP fault.","ex":"<pre><span class=\"p\">Router#</span> show ip eigrp neighbors\nH   Address    Interface  Hold  Uptime    SRTT  RTO   Q  Seq\n0   10.1.1.2   Gi0/0        12  00:42:11     1  5000   0  12</pre>","exPlain":"Router# show ip eigrp neighbors\nH   Address    Interface  Hold  Uptime    SRTT  RTO   Q  Seq\n0   10.1.1.2   Gi0/0        12  00:42:11     1  5000   0  12","neg":"","kind":"cmd"},{"i":313,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip eigrp topology [network]","synPlain":"show ip eigrp topology [network]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض جدول الطوبولوجيا بحالتَي <code>Passive</code> (مستقر) و<code>Active</code> (يبحث عن بديل). بقاء المسار في <code>Active</code> يعني فقدان المسار وعدم وجود Feasible Successor — راقب مؤقّت Stuck-in-Active.","en":"EIGRP topology table; a route stuck in Active means it is lost with no feasible successor available.","ex":"<pre><span class=\"p\">Router#</span> show ip eigrp topology\nP 10.2.2.0/24, 1 successors, FD is 2816\n   via 10.1.1.2 (2816/256), GigabitEthernet0/0</pre>","exPlain":"Router# show ip eigrp topology\nP 10.2.2.0/24, 1 successors, FD is 2816\n   via 10.1.1.2 (2816/256), GigabitEthernet0/0","neg":"","kind":"cmd"},{"i":314,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip bgp summary","synPlain":"show ip bgp summary","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"أهم أمر في BGP: حالة كل جار يجب أن تكون <code>Established</code>، وعمود <code>State/PfxRcd</code> يعرض عدد البادئات المستلمة. رقم ثابت يعني جلسة سليمة، أما <code>Idle</code> أو <code>Active</code> فمشكلة في TCP أو ACL على المنفذ 179.","en":"BGP neighbour health; a numeric PfxRcd means the session is established, Idle or Active means TCP or filtering problems.","ex":"<pre><span class=\"p\">Router#</span> show ip bgp summary\nNeighbor   V  AS    MsgRcvd MsgSent InQ OutQ Up/Down   State/PfxRcd\n10.1.1.2   4  65001     120     118   0    0 01:22:31  48</pre>","exPlain":"Router# show ip bgp summary\nNeighbor   V  AS    MsgRcvd MsgSent InQ OutQ Up/Down   State/PfxRcd\n10.1.1.2   4  65001     120     118   0    0 01:22:31  48","neg":"","kind":"cmd"},{"i":315,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip bgp [network]","synPlain":"show ip bgp [network]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض جدول BGP مع أفضل مسار بعلامة <code>&gt;</code> وأسباب التفضيل (Weight، Local Preference، AS-Path، Origin، MED). الحرف <code>i</code> يعني مساراً تعلّمه الراوتر من iBGP.","en":"BGP table with the best path marked by > and the attributes that decided it.","ex":"<pre><span class=\"p\">Router#</span> show ip bgp\nBGP table version is 24, local router ID is 10.1.1.1\n   Network          Next Hop     Metric LocPrf Weight Path\n*&gt; 203.0.113.0/24   10.1.1.2          0            0 65001 i</pre>","exPlain":"Router# show ip bgp\nBGP table version is 24, local router ID is 10.1.1.1\n   Network          Next Hop     Metric LocPrf Weight Path\n*> 203.0.113.0/24   10.1.1.2          0            0 65001 i","neg":"","kind":"cmd"},{"i":316,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip dhcp binding","synPlain":"show ip dhcp binding","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض العناوين المؤجّرة ومدّة صلاحيتها ومعرّف العميل. جدول فارغ مع عملاء بلا عنوان يعني أن الطلب لا يصل إلى الخادم (helper-address مفقود) أو أن الـ pool استُنفد.","en":"DHCP leases with client IDs and expiry; an empty table plus clients without addresses means the request never arrives.","ex":"<pre><span class=\"p\">Router#</span> show ip dhcp binding\nIP address      Client-ID/          Lease expiration        Type\n                Hardware address\n192.168.10.11   0100.1122.3344      Sep 12 2026 10:12 AM    Automatic</pre>","exPlain":"Router# show ip dhcp binding\nIP address      Client-ID/          Lease expiration        Type\n                Hardware address\n192.168.10.11   0100.1122.3344      Sep 12 2026 10:12 AM    Automatic","neg":"","kind":"cmd"},{"i":317,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip dhcp conflict","synPlain":"show ip dhcp conflict","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض العناوين التي اكتشف الخادم تعارضها عبر ARP أو ping فاستبعدها من التوزيع. وجود عناوين هنا يفسّر «عميل لا يحصل على IP» رغم توفّر عناوين حرة في الـ pool.","en":"Addresses the server quarantined after detecting a conflict — explains clients failing to lease despite free addresses.","ex":"<pre><span class=\"p\">Router#</span> show ip dhcp conflict\nIP address      Detection method   Detection time\n192.168.10.20   Ping               Sep 10 2026 09:44 AM</pre>","exPlain":"Router# show ip dhcp conflict\nIP address      Detection method   Detection time\n192.168.10.20   Ping               Sep 10 2026 09:44 AM","neg":"","kind":"cmd"},{"i":318,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show policy-map interface [interface]","synPlain":"show policy-map interface [interface]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يتحقق من QoS فعلياً: عدد الحزم المطابقة لكل class وما أُسقط أو عُلّم. أسرع دليل على أن الـ policy-map مطبّق على الواجهة فعلاً وليس معلّقاً في الإعداد فقط.","en":"Live QoS counters per class — proves the policy is actually attached and shows matches, drops and markings.","ex":"<pre><span class=\"p\">Router#</span> show policy-map interface gi0/1\n  Service-policy output: WAN-OUT\n    Class-map: VOICE (match-any)\n      1240 packets, 99200 bytes\n      Match: dscp ef (46)</pre>","exPlain":"Router# show policy-map interface gi0/1\n  Service-policy output: WAN-OUT\n    Class-map: VOICE (match-any)\n      1240 packets, 99200 bytes\n      Match: dscp ef (46)","neg":"","kind":"cmd"},{"i":319,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show ip sla statistics [entry-number]","synPlain":"show ip sla statistics [entry-number]","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض نتائج مجسّات SLA: زمن الذهاب والعودة ونسبة الفقد وحالة آخر عملية. تُستخدم لمراقبة جودة المسار وربطها بكائن تتبّع (object tracking) لتبديل المسار تلقائياً.","en":"IP SLA probe results (round-trip time, loss, return code) used to drive object tracking and path failover.","ex":"<pre><span class=\"p\">Router#</span> show ip sla statistics\nIPSLA operation id: 1\nLatest RTT: 24 milliseconds\nNumber of successes: 120</pre>","exPlain":"Router# show ip sla statistics\nIPSLA operation id: 1\nLatest RTT: 24 milliseconds\nNumber of successes: 120","neg":"","kind":"cmd"},{"i":320,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show monitor session all","synPlain":"show monitor session all","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يتحقق من جلسات SPAN وRSPAN: المنفذ المصدر والوجهة والاتجاه (<code>both</code> أو <code>rx</code> أو <code>tx</code>). جلسة لا تُظهر حزماً في Wireshark سببها غالباً اتجاه خاطئ أو مصدر trunk يحتاج تحديد VLAN.","en":"Shows SPAN/RSPAN sessions and directions; an empty capture usually means the wrong direction or a trunk source.","ex":"<pre><span class=\"p\">SW1#</span> show monitor session all\nSession 1\nType: Local Session\nSource Ports: Both: Gi1/0/5\nDestination Ports: Gi1/0/10</pre>","exPlain":"SW1# show monitor session all\nSession 1\nType: Local Session\nSource Ports: Both: Gi1/0/5\nDestination Ports: Gi1/0/10","neg":"","kind":"cmd"},{"i":321,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show cdp neighbors detail","synPlain":"show cdp neighbors detail","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"يعرض الجار المباشر بالاسم والمنصّة وعنوان IP وإصدار IOS والمنفذ المقابل. أسرع طريقة لرسم الطوبولوجيا الفعلية قبل أي تعديل، وللتأكد من أنك على الجهاز الصحيح.","en":"Detailed neighbour info (name, platform, IP, IOS, far-end port) — the fastest way to map the real topology.","ex":"<pre><span class=\"p\">SW1#</span> show cdp neighbors detail\nDevice ID: R1.corp.local\nIP address: 10.1.1.1\nPlatform: Cisco ISR4331, Capabilities: Router\nInterface: GigabitEthernet1/0/1, Port ID (outgoing port): GigabitEthernet0/1</pre>","exPlain":"SW1# show cdp neighbors detail\nDevice ID: R1.corp.local\nIP address: 10.1.1.1\nPlatform: Cisco ISR4331, Capabilities: Router\nInterface: GigabitEthernet1/0/1, Port ID (outgoing port): GigabitEthernet0/1","neg":"no cdp run","kind":"cmd"},{"i":322,"sec":"tshoot","no":"21","secAr":"استكشاف الأخطاء","secEn":"Troubleshooting","grp":"modern","syn":"show lldp neighbors detail","synPlain":"show lldp neighbors detail","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"بديل CDP المعياري (IEEE 802.1AB): يعمل مع الأجهزة غير السيسكوية ويعرض اسم النظام ووصف المنفذ وعنوان الإدارة. استخدمه حين لا يظهر الجار في CDP لأنه من مورّد آخر.","en":"Vendor-neutral neighbour discovery (802.1AB) for non-Cisco peers that CDP cannot see.","ex":"<pre><span class=\"p\">SW1#</span> show lldp neighbors detail\nChassis id: 0011.2233.4400\nSystem Name: edge-sw-02\nPort id: Gi0/1\nManagement Addresses: 10.9.9.2</pre>","exPlain":"SW1# show lldp neighbors detail\nChassis id: 0011.2233.4400\nSystem Name: edge-sw-02\nPort id: Gi0/1\nManagement Addresses: 10.9.9.2","neg":"no lldp run","kind":"cmd"},{"i":323,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 01 — تهيئة راوتر من الصفر","synPlain":"Lab 01 — تهيئة راوتر من الصفر","mode":"Basic","modeCls":"m-any","ar":"<b>الهدف:</b> جهاز جاهز للإدارة عن بُعد بأمان. <b>المطلوب:</b> hostname، enable secret، مستخدم admin، SSHv2، بانر، حفظ الإعداد.","en":"Hands-on lab: configure a router from scratch and verify every layer.","ex":"<pre>hostname R1\nenable secret Cisco@123\nusername admin privilege 15 secret Adm1n@123\nip domain-name lab.local\ncrypto key generate rsa modulus 2048\nip ssh version 2\nline vty 0 15\n login local\n transport input ssh\nbanner motd #Authorized access only#\nend\ncopy run start</pre>","exPlain":"hostname R1\nenable secret Cisco@123\nusername admin privilege 15 secret Adm1n@123\nip domain-name lab.local\ncrypto key generate rsa modulus 2048\nip ssh version 2\nline vty 0 15\n login local\n transport input ssh\nbanner motd #Authorized access only#\nend\ncopy run start","neg":"show ip ssh","kind":"concept"},{"i":324,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 02 — VLANs وTrunking","synPlain":"Lab 02 — VLANs وTrunking","mode":"Switching","modeCls":"m-any","ar":"<b>الهدف:</b> عزل ترافيك ثلاثة أقسام مع تمريرها بين سويتشين. <b>المطلوب:</b> VLANs 10/20/30، منافذ access، trunk على الرابط بين السويتشين، Native VLAN 99.","en":"Hands-on lab: build VLANs, trunks, and verify the VLAN database.","ex":"<pre>vlan 10\n name SALES\nvlan 20\n name ENG\nvlan 30\n name HR\nvlan 99\n name NATIVE\ninterface range g0/1-2\n switchport mode access\n switchport access vlan 10\ninterface g0/24\n switchport trunk encapsulation dot1q\n switchport mode trunk\n switchport trunk native vlan 99\n switchport trunk allowed vlan 10,20,30,99</pre>","exPlain":"vlan 10\n name SALES\nvlan 20\n name ENG\nvlan 30\n name HR\nvlan 99\n name NATIVE\ninterface range g0/1-2\n switchport mode access\n switchport access vlan 10\ninterface g0/24\n switchport trunk encapsulation dot1q\n switchport mode trunk\n switchport trunk native vlan 99\n switchport trunk allowed vlan 10,20,30,99","neg":"show vlan brief","kind":"concept"},{"i":325,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 03 — Router-on-a-Stick","synPlain":"Lab 03 — Router-on-a-Stick","mode":"Routing","modeCls":"m-any","ar":"<b>الهدف:</b> توجيه بين ثلاثة VLANs برابط فيزيائي واحد. <b>المطلوب:</b> واجهات فرعية مع encapsulation صحيح، وعنوان لكل VLAN يعمل كبوابة.","en":"Hands-on lab: inter-VLAN routing with sub-interfaces.","ex":"<pre>interface g0/0\n no shutdown\ninterface g0/0.10\n encapsulation dot1Q 10\n ip address 192.168.10.1 255.255.255.0\ninterface g0/0.20\n encapsulation dot1Q 20\n ip address 192.168.20.1 255.255.255.0\ninterface g0/0.99\n encapsulation dot1Q 99 native\n ip address 192.168.99.1 255.255.255.0</pre>","exPlain":"interface g0/0\n no shutdown\ninterface g0/0.10\n encapsulation dot1Q 10\n ip address 192.168.10.1 255.255.255.0\ninterface g0/0.20\n encapsulation dot1Q 20\n ip address 192.168.20.1 255.255.255.0\ninterface g0/0.99\n encapsulation dot1Q 99 native\n ip address 192.168.99.1 255.255.255.0","neg":"show ip route connected","kind":"concept"},{"i":326,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 04 — STP وPortFast","synPlain":"Lab 04 — STP وPortFast","mode":"Switching","modeCls":"m-any","ar":"<b>الهدف:</b> جذر محدّد + حماية المنافذ الطرفية. <b>المطلوب:</b> Rapid PVST، SW1 جذر لـ VLAN 10، SW2 جذر لـ VLAN 20، PortFast + BPDU Guard على منافذ المستخدمين.","en":"Hands-on lab: control the STP topology and protect edge ports.","ex":"<pre>spanning-tree mode rapid-pvst\nspanning-tree vlan 10 root primary\nspanning-tree vlan 20 root secondary\ninterface range g0/1-10\n spanning-tree portfast\n spanning-tree bpduguard enable</pre>","exPlain":"spanning-tree mode rapid-pvst\nspanning-tree vlan 10 root primary\nspanning-tree vlan 20 root secondary\ninterface range g0/1-10\n spanning-tree portfast\n spanning-tree bpduguard enable","neg":"show spanning-tree vlan 10","kind":"concept"},{"i":327,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 05 — EtherChannel LACP","synPlain":"Lab 05 — EtherChannel LACP","mode":"Switching","modeCls":"m-any","ar":"<b>الهدف:</b> مضاعفة النطاق بين سويتشين. <b>المطلوب:</b> قناة من رابطين بوضع active، trunk على port-channel، واختبار سحب أحد الرابطين.","en":"Hands-on lab: bundle links with LACP and verify the port-channel.","ex":"<pre>interface range g0/1-2\n channel-group 1 mode active\ninterface port-channel 1\n switchport mode trunk\n switchport trunk allowed vlan 10,20,30</pre>","exPlain":"interface range g0/1-2\n channel-group 1 mode active\ninterface port-channel 1\n switchport mode trunk\n switchport trunk allowed vlan 10,20,30","neg":"show etherchannel summary","kind":"concept"},{"i":328,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 06 — Port Security وDHCP Snooping","synPlain":"Lab 06 — Port Security وDHCP Snooping","mode":"Security","modeCls":"m-any","ar":"<b>الهدف:</b> منع الأجهزة غير المصرّح بها ومنع DHCP Rogue. <b>المطلوب:</b> حد أقصى 2 MAC لكل منفذ وصول، مخالفة restrict، وثقة على منفذ الأبلينك فقط.","en":"Hands-on lab: harden access ports and stop DHCP/ARP attacks.","ex":"<pre>interface range g0/1-10\n switchport mode access\n switchport port-security\n switchport port-security maximum 2\n switchport port-security mac-address sticky\n switchport port-security violation restrict\nip dhcp snooping\nip dhcp snooping vlan 10,20\ninterface g0/24\n ip dhcp snooping trust\ninterface range g0/1-10\n ip dhcp snooping limit rate 10</pre>","exPlain":"interface range g0/1-10\n switchport mode access\n switchport port-security\n switchport port-security maximum 2\n switchport port-security mac-address sticky\n switchport port-security violation restrict\nip dhcp snooping\nip dhcp snooping vlan 10,20\ninterface g0/24\n ip dhcp snooping trust\ninterface range g0/1-10\n ip dhcp snooping limit rate 10","neg":"show port-security","kind":"concept"},{"i":329,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 07 — OSPF Multi-Area","synPlain":"Lab 07 — OSPF Multi-Area","mode":"Routing","modeCls":"m-any","ar":"<b>الهدف:</b> شبكة ثلاث مناطق مع تلخيص. <b>المطلوب:</b> Router-ID صريح، passive على الواجهات الطرفية، مصادقة MD5، وتلخيص على ABR.","en":"Hands-on lab: multi-area OSPF with summarisation and verification.","ex":"<pre>router ospf 1\n router-id 1.1.1.1\n network 10.1.1.0 0.0.0.255 area 0\n network 10.2.2.0 0.0.0.255 area 1\n passive-interface default\n no passive-interface g0/0\n area 1 range 192.168.0.0 255.255.0.0\ninterface g0/0\n ip ospf message-digest-key 1 md5 Ospf@123\n ip ospf authentication message-digest</pre>","exPlain":"router ospf 1\n router-id 1.1.1.1\n network 10.1.1.0 0.0.0.255 area 0\n network 10.2.2.0 0.0.0.255 area 1\n passive-interface default\n no passive-interface g0/0\n area 1 range 192.168.0.0 255.255.0.0\ninterface g0/0\n ip ospf message-digest-key 1 md5 Ospf@123\n ip ospf authentication message-digest","neg":"show ip ospf neighbor","kind":"concept"},{"i":330,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 08 — EIGRP مع Variance","synPlain":"Lab 08 — EIGRP مع Variance","mode":"Routing","modeCls":"m-any","ar":"<b>الهدف:</b> توزيع حمل غير متساوٍ على رابطين. <b>المطلوب:</b> EIGRP AS 100، إيقاف auto-summary، variance 2، والتحقق من وجود مسارين في الجدول.","en":"Hands-on lab: EIGRP with unequal-cost load balancing.","ex":"<pre>router eigrp 100\n network 10.1.1.0 0.0.0.255\n network 10.1.2.0 0.0.0.255\n no auto-summary\n eigrp router-id 1.1.1.1\n variance 2</pre>","exPlain":"router eigrp 100\n network 10.1.1.0 0.0.0.255\n network 10.1.2.0 0.0.0.255\n no auto-summary\n eigrp router-id 1.1.1.1\n variance 2","neg":"show ip route 192.168.30.0","kind":"concept"},{"i":331,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 09 — ACLs متعددة","synPlain":"Lab 09 — ACLs متعددة","mode":"Security","modeCls":"m-any","ar":"<b>الهدف:</b> سياسة وصول واقعية. <b>المطلوب:</b> منع VLAN 10 من الوصول إلى خادم معيّن على 80، السماح بـ HTTPS، منع Telnet من الخارج، والسماح بكل ما تبقّى.","en":"Hands-on lab: layered ACLs for a small enterprise.","ex":"<pre>ip access-list extended POLICY\n 10 deny tcp 192.168.10.0 0.0.0.255 host 192.168.30.10 eq 80\n 20 permit tcp 192.168.10.0 0.0.0.255 any eq 443\n 30 deny tcp any any eq 23\n 40 permit ip any any\ninterface g0/1\n ip access-group POLICY in</pre>","exPlain":"ip access-list extended POLICY\n 10 deny tcp 192.168.10.0 0.0.0.255 host 192.168.30.10 eq 80\n 20 permit tcp 192.168.10.0 0.0.0.255 any eq 443\n 30 deny tcp any any eq 23\n 40 permit ip any any\ninterface g0/1\n ip access-group POLICY in","neg":"show ip access-lists POLICY","kind":"concept"},{"i":332,"sec":"plan","no":"23","secAr":"تمارين معملية","secEn":"Hands-on Labs","grp":"modern","syn":"Lab 10 — NAT + DHCP كامل","synPlain":"Lab 10 — NAT + DHCP كامل","mode":"Services","modeCls":"m-any","ar":"<b>الهدف:</b> شبكة داخلية كاملة تعمل وتصل للإنترنت. <b>المطلوب:</b> DHCP pool مع استثناءات، PAT على الواجهة الخارجية، وتحقّق من الترجمات.","en":"Hands-on lab: complete NAT and DHCP deployment.","ex":"<pre>ip dhcp excluded-address 192.168.10.1 192.168.10.20\nip dhcp pool LAN10\n network 192.168.10.0 255.255.255.0\n default-router 192.168.10.1\n dns-server 8.8.8.8\n lease 7\naccess-list 1 permit 192.168.0.0 0.0.255.255\nip nat inside source list 1 interface g0/0 overload\ninterface g0/1\n ip nat inside\ninterface g0/0\n ip nat outside</pre>","exPlain":"ip dhcp excluded-address 192.168.10.1 192.168.10.20\nip dhcp pool LAN10\n network 192.168.10.0 255.255.255.0\n default-router 192.168.10.1\n dns-server 8.8.8.8\n lease 7\naccess-list 1 permit 192.168.0.0 0.0.255.255\nip nat inside source list 1 interface g0/0 overload\ninterface g0/1\n ip nat inside\ninterface g0/0\n ip nat outside","neg":"show ip dhcp binding","kind":"concept"},{"i":333,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 address <i>prefix/64</i> eui-64","synPlain":"ipv6 address prefix/64 eui-64","mode":"Interface Config","modeCls":"m-iconf","ar":"يبني 64 بت السفلية من MAC الواجهة بصيغة EUI-64: يُقسم MAC إلى نصفين ويُدرَج <code>FFFE</code> بينهما، ويُعكس البت السابع (U/L bit). مثال: العنوان <code>00E0.8F57.1234</code> يعطي <code>02E0:8FFF:FE57:1234</code>. ملاحظة أمنية: EUI-64 يكشف MAC الحقيقي، لذلك تفضّل أنظمة التشغيل الحديثة <b>Privacy Extensions</b> (عناوين عشوائية).","en":"Derives the 64-bit interface ID from the MAC address and inserts FFFE in the middle.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 address 2001:db8:10::/64 eui-64\n<span class=\"p\">R1#</span> show ipv6 interface brief\nGigabitEthernet0/0  [up/up]\n    FE80::2E0:8FFF:FE57:1234\n    2001:DB8:10::2E0:8FFF:FE57:1234</pre>","exPlain":"R1(config-if)# ipv6 address 2001:db8:10::/64 eui-64\nR1# show ipv6 interface brief\nGigabitEthernet0/0  [up/up]\n    FE80::2E0:8FFF:FE57:1234\n    2001:DB8:10::2E0:8FFF:FE57:1234","neg":"no ipv6 address 2001:db8:10::/64 eui-64","kind":"cmd"},{"i":334,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 nd prefix <i>prefix/len</i> <i>valid-lifetime</i> <i>preferred-lifetime</i>","synPlain":"ipv6 nd prefix prefix/len valid-lifetime preferred-lifetime","mode":"Interface Config","modeCls":"m-iconf","ar":"يتحكم في البادئة التي يعلنها الراوتر داخل RA، وفي عمرها الزمني. <b>valid lifetime</b> = المدة التي يبقى فيها العنوان صالحاً، و<b>preferred lifetime</b> = المدة التي يُفضّل فيها استخدامه كعنوان مصدر (يجب أن تكون <code>preferred</code> أصغر من أو تساوي <code>valid</code>). القيمة <code>infinite</code> تعني بلا انتهاء.","en":"Advertises a prefix in Router Advertisements with its valid and preferred lifetimes.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 nd prefix 2001:db8:10::/64 2592000 604800\n<span class=\"p\">R1(config-if)#</span> ipv6 nd prefix 2001:db8:99::/64 7200 3600 no-autoconfig</pre>","exPlain":"R1(config-if)# ipv6 nd prefix 2001:db8:10::/64 2592000 604800\nR1(config-if)# ipv6 nd prefix 2001:db8:99::/64 7200 3600 no-autoconfig","neg":"no ipv6 nd prefix 2001:db8:10::/64","kind":"cmd"},{"i":335,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 nd managed-config-flag | ipv6 nd other-config-flag","synPlain":"ipv6 nd managed-config-flag | ipv6 nd other-config-flag","mode":"Interface Config","modeCls":"m-iconf","ar":"يضبطان علمَي RA:","en":"Tells hosts to use DHCPv6 for addresses (M flag) or only for other settings (O flag).","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 nd managed-config-flag\n<span class=\"p\">R1(config-if)#</span> ipv6 nd other-config-flag\n<span class=\"p\">R1(config-if)#</span> ipv6 nd ra-interval 30\n<span class=\"p\">R1(config-if)#</span> ipv6 nd ra-lifetime 1800</pre>","exPlain":"R1(config-if)# ipv6 nd managed-config-flag\nR1(config-if)# ipv6 nd other-config-flag\nR1(config-if)# ipv6 nd ra-interval 30\nR1(config-if)# ipv6 nd ra-lifetime 1800","neg":"no ipv6 nd managed-config-flag","kind":"cmd"},{"i":336,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 nd ra-interval <i>sec</i> | ipv6 nd ra-lifetime <i>sec</i>","synPlain":"ipv6 nd ra-interval sec | ipv6 nd ra-lifetime sec","mode":"Interface Config","modeCls":"m-iconf","ar":"يضبطان تكرار إرسال RA ومدة اعتباره صالحاً. الافتراضي: 200 ثانية للفاصل، و1800 للعمر. القاعدة: <b>ra-lifetime ≥ 3 × ra-interval</b> وإلا رفض IOS القيمة. تقليل الفاصل يسرّع اكتشاف فشل البوابة لكنه يزيد الحمل.","en":"Controls how often RAs are sent and how long hosts may keep the default route.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 nd ra-interval 20\n<span class=\"p\">R1(config-if)#</span> ipv6 nd ra-lifetime 60</pre>","exPlain":"R1(config-if)# ipv6 nd ra-interval 20\nR1(config-if)# ipv6 nd ra-lifetime 60","neg":"no ipv6 nd ra-interval","kind":"cmd"},{"i":337,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 nd mtu <i>bytes</i>","synPlain":"ipv6 nd mtu bytes","mode":"Interface Config","modeCls":"m-iconf","ar":"يعلن MTU للرابط داخل RA، فيستخدمه كل الأجهزة المتصلة بدلاً من 1500. مفيد في الأنفاق وروابط MPLS لتفادي التجزئة. لا يغيّر MTU الفعلي للواجهة (ذاك <code>ipv6 mtu</code>).","en":"Advertises the link MTU inside RAs so hosts size their packets correctly.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 nd mtu 1400\n<span class=\"p\">R1(config-if)#</span> ipv6 mtu 1400</pre>","exPlain":"R1(config-if)# ipv6 nd mtu 1400\nR1(config-if)# ipv6 mtu 1400","neg":"no ipv6 nd mtu","kind":"cmd"},{"i":338,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 dhcp pool <i>name</i>","synPlain":"ipv6 dhcp pool name","mode":"Global Config","modeCls":"m-gconf","ar":"ينشئ Pool لـ DHCPv6. داخله تُعرَّف البادئة وخادم DNS والنطاق. يُستخدم مع <code>ipv6 dhcp server</code> على الواجهة. الحالة <b>Stateful</b> = الخادم يعطي العنوان ويحفظ الجلسة، و<b>Stateless</b> = يعطي معلومات فقط (DNS) والعنوان يأتي من SLAAC.","en":"Creates a DHCPv6 pool for stateful or stateless service.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 dhcp pool V6-POOL\n<span class=\"p\">R1(config-dhcpv6)#</span> address prefix 2001:db8:10::/64\n<span class=\"p\">R1(config-dhcpv6)#</span> dns-server 2001:4860:4860::8888\n<span class=\"p\">R1(config-dhcpv6)#</span> domain-name lab.local</pre>","exPlain":"R1(config)# ipv6 dhcp pool V6-POOL\nR1(config-dhcpv6)# address prefix 2001:db8:10::/64\nR1(config-dhcpv6)# dns-server 2001:4860:4860::8888\nR1(config-dhcpv6)# domain-name lab.local","neg":"no ipv6 dhcp pool V6-POOL","kind":"cmd"},{"i":339,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 dhcp server <i>pool</i> [rapid-commit] [preference <i>0-255</i>]","synPlain":"ipv6 dhcp server pool [rapid-commit] [preference 0-255]","mode":"Interface Config","modeCls":"m-iconf","ar":"يفعّل الخادم على الواجهة ويربطه بالـ pool. <code>rapid-commit</code> يختصر العملية إلى رسالتين (Solicit/Reply) بدلاً من أربع. <code>preference</code> يحسم عند وجود أكثر من خادم (الأعلى يفوز).","en":"Activates the DHCPv6 server on the interface and binds it to the pool.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 dhcp server V6-POOL rapid-commit preference 255\n<span class=\"p\">R1(config-if)#</span> ipv6 nd managed-config-flag\n<span class=\"p\">R1#</span> show ipv6 dhcp binding</pre>","exPlain":"R1(config-if)# ipv6 dhcp server V6-POOL rapid-commit preference 255\nR1(config-if)# ipv6 nd managed-config-flag\nR1# show ipv6 dhcp binding","neg":"no ipv6 dhcp server V6-POOL","kind":"cmd"},{"i":340,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 dhcp relay destination <i>server-ip</i>","synPlain":"ipv6 dhcp relay destination server-ip","mode":"Interface Config","modeCls":"m-iconf","ar":"وسيط DHCPv6: يمرّر رسائل العملاء إلى خادم في شبكة أخرى. يعمل عبر Multicast <code>FF02::1:2</code> (All DHCP Servers). لا يوجد في IPv6 ما يعادل <code>ip helper-address</code> بالاسم، لكن الفكرة نفسها.","en":"Forwards DHCPv6 messages to a server on another link.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 dhcp relay destination 2001:db8:99::10\n<span class=\"p\">R1(config-if)#</span> ipv6 dhcp relay destination 2001:db8:99::11</pre>","exPlain":"R1(config-if)# ipv6 dhcp relay destination 2001:db8:99::10\nR1(config-if)# ipv6 dhcp relay destination 2001:db8:99::11","neg":"no ipv6 dhcp relay destination 2001:db8:99::10","kind":"cmd"},{"i":341,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 dhcp client pd <i>prefix-name</i>","synPlain":"ipv6 dhcp client pd prefix-name","mode":"Interface Config (CPE)","modeCls":"m-iconf","ar":"<b>Prefix Delegation:</b> يطلب من مزوّد الخدمة بادئة كاملة (عادةً /56 أو /48) لتوزيعها على الشبكات الداخلية. هذا هو الأسلوب المعياري في شبكات المنازل والمؤسسات الصغيرة مع IPv6. تُخزَّن البادئة باسم ثم تُستخدم في الواجهات الداخلية.","en":"Requests a delegated prefix from the ISP (prefix delegation) and names it locally.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 general-prefix ISP-PD ipv6-prefix 2001:db8:abcd::/48\n<span class=\"p\">R1(config)#</span> interface g0/0\n<span class=\"p\">R1(config-if)#</span> ipv6 dhcp client pd ISP-PD\n<span class=\"p\">R1(config)#</span> interface g0/1\n<span class=\"p\">R1(config-if)#</span> ipv6 address ISP-PD ::1:0:0:0:1/64</pre>","exPlain":"R1(config)# ipv6 general-prefix ISP-PD ipv6-prefix 2001:db8:abcd::/48\nR1(config)# interface g0/0\nR1(config-if)# ipv6 dhcp client pd ISP-PD\nR1(config)# interface g0/1\nR1(config-if)# ipv6 address ISP-PD ::1:0:0:0:1/64","neg":"no ipv6 dhcp client pd ISP-PD","kind":"cmd"},{"i":342,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 ospf <i>pid</i> area <i>id</i> | ipv6 ospf network point-to-point","synPlain":"ipv6 ospf pid area id | ipv6 ospf network point-to-point","mode":"Interface Config","modeCls":"m-iconf","ar":"تفعيل OSPFv3 على الواجهة وتحديد نوع الشبكة. على روابط Point-to-Point يُفضّل <code>point-to-point</code> لتجاوز انتخاب DR/BDR وتسريع الالتقاء. لاحظ أن OSPFv3 لا يستخدم <code>network</code> — التفعيل على الواجهة مباشرة.","en":"Enables OSPFv3 on the interface and sets its network type.","ex":"<pre><span class=\"p\">R1(config-if)#</span> ipv6 ospf 1 area 0\n<span class=\"p\">R1(config-if)#</span> ipv6 ospf network point-to-point\n<span class=\"p\">R1(config-if)#</span> ipv6 ospf cost 10\n<span class=\"p\">R1(config-if)#</span> ipv6 ospf priority 100</pre>","exPlain":"R1(config-if)# ipv6 ospf 1 area 0\nR1(config-if)# ipv6 ospf network point-to-point\nR1(config-if)# ipv6 ospf cost 10\nR1(config-if)# ipv6 ospf priority 100","neg":"no ipv6 ospf 1 area 0","kind":"cmd"},{"i":343,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"ipv6 router ospf <i>pid</i> | passive-interface | default-information originate","synPlain":"ipv6 router ospf pid | passive-interface | default-information originate","mode":"Global Config","modeCls":"m-gconf","ar":"إعدادات العملية: Router-ID (إلزامي عملياً لأن OSPFv3 لا يستمدّه من عناوين IPv6)، والواجهات السلبية، والمسار الافتراضي. <b>تذكّر:</b> بدون <code>router-id</code> صريح قد تفشل الجيرة لأن الراوتر لا يجد عنوان IPv4 ليبنيه منه.","en":"Configures the OSPFv3 process, silences interfaces, and injects a default route.","ex":"<pre><span class=\"p\">R1(config)#</span> ipv6 router ospf 1\n<span class=\"p\">R1(config-rtr)#</span> router-id 1.1.1.1\n<span class=\"p\">R1(config-rtr)#</span> passive-interface default\n<span class=\"p\">R1(config-rtr)#</span> no passive-interface g0/0\n<span class=\"p\">R1(config-rtr)#</span> default-information originate always</pre>","exPlain":"R1(config)# ipv6 router ospf 1\nR1(config-rtr)# router-id 1.1.1.1\nR1(config-rtr)# passive-interface default\nR1(config-rtr)# no passive-interface g0/0\nR1(config-rtr)# default-information originate always","neg":"no ipv6 router ospf 1","kind":"cmd"},{"i":344,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"show ipv6 ospf neighbor | show ipv6 ospf interface brief","synPlain":"show ipv6 ospf neighbor | show ipv6 ospf interface brief","mode":"Privileged EXEC","modeCls":"m-pexec","ar":"التحقق من جيران OSPFv3. ستلاحظ أن عناوين الجيران المعروضة هي <b>Link-Local</b> (FE80::) وليس العناوين العامة — وهذا سلوك طبيعي وصحيح في OSPFv3.","en":"Verifies OSPFv3 adjacencies and their current states.","ex":"<pre><span class=\"p\">R1#</span> show ipv6 ospf neighbor\nNeighbor ID   Pri  State    Dead Time  Interface ID  Interface\n2.2.2.2       1    FULL/ -  00:00:36   4             GigabitEthernet0/0</pre>","exPlain":"R1# show ipv6 ospf neighbor\nNeighbor ID   Pri  State    Dead Time  Interface ID  Interface\n2.2.2.2       1    FULL/ -  00:00:36   4             GigabitEthernet0/0","neg":"","kind":"cmd"},{"i":345,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"interface tunnel <i>n</i> | tunnel mode ipv6ip","synPlain":"interface tunnel n | tunnel mode ipv6ip","mode":"Global Config","modeCls":"m-gconf","ar":"<b>IPv6 over IPv4 (6in4) يدوي:</b> يغلّف حزم IPv6 داخل IPv4 لعبور شبكة IPv4 قديمة. يتطلب عنوان IPv4 عاماً ثابتاً على الطرفين — لذلك لا يصلح للاتصالات المنزلية ذات العنوان المتغيّر.","en":"Creates a manual 6in4 tunnel carrying IPv6 over an IPv4 transport.","ex":"<pre><span class=\"p\">R1(config)#</span> interface tunnel 0\n<span class=\"p\">R1(config-if)#</span> ipv6 address 2001:db8:100::1/64\n<span class=\"p\">R1(config-if)#</span> tunnel source g0/0\n<span class=\"p\">R1(config-if)#</span> tunnel destination 203.0.113.2\n<span class=\"p\">R1(config-if)#</span> tunnel mode ipv6ip\n<span class=\"p\">R1(config)#</span> ipv6 route ::/0 2001:db8:100::2</pre>","exPlain":"R1(config)# interface tunnel 0\nR1(config-if)# ipv6 address 2001:db8:100::1/64\nR1(config-if)# tunnel source g0/0\nR1(config-if)# tunnel destination 203.0.113.2\nR1(config-if)# tunnel mode ipv6ip\nR1(config)# ipv6 route ::/0 2001:db8:100::2","neg":"no interface tunnel 0","kind":"cmd"},{"i":346,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"tunnel mode ipv6ip 6to4","synPlain":"tunnel mode ipv6ip 6to4","mode":"Tunnel Config","modeCls":"m-iconf","ar":"<b>6to4:</b> نفق تلقائي لا يحتاج عنوان الطرف الآخر — يُشتق من عنوان IPv4 المدمج في البادئة <code>2002:V4ADDR::/48</code>. مثال: عنوان <code>192.0.2.1</code> يعطي البادئة <code>2002:c000:0201::/48</code>. عيبه: يحتاج IPv4 عاماً، ولا يدعمه كل الشبكات.","en":"Automatic 6to4 tunnel that derives the IPv4 endpoint from the 2002::/16 prefix.","ex":"<pre><span class=\"p\">R1(config-if)#</span> tunnel mode ipv6ip 6to4\n<span class=\"p\">R1(config-if)#</span> ipv6 address 2002:c000:0201:1::1/64\n<span class=\"p\">R1(config)#</span> ipv6 route 2002::/16 tunnel 0</pre>","exPlain":"R1(config-if)# tunnel mode ipv6ip 6to4\nR1(config-if)# ipv6 address 2002:c000:0201:1::1/64\nR1(config)# ipv6 route 2002::/16 tunnel 0","neg":"no tunnel mode","kind":"cmd"},{"i":347,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"tunnel mode ipv6ip isatap | tunnel mode gre ip","synPlain":"tunnel mode ipv6ip isatap | tunnel mode gre ip","mode":"Tunnel Config","modeCls":"m-iconf","ar":"<b>ISATAP</b> يمنح أجهزة داخل شبكة IPv4 عنواناً يبدأ بـ <code>FE80::5EFE:</code> ثم IPv4. و<b>GRE</b> نفق عام يدعم Multicast والتوجيه (بخلاف 6in4 الذي يدعم Unicast فقط) — لذلك يُستخدم مع OSPFv3/EIGRPv6 عبر شبكة IPv4.","en":"ISATAP gives IPv4-only hosts IPv6 addresses; GRE tunnels also carry multicast and routing protocols.","ex":"<pre><span class=\"p\">R1(config-if)#</span> tunnel mode ipv6ip isatap\n<span class=\"p\">R1(config-if)#</span> tunnel mode gre ip\n<span class=\"p\">R1(config-if)#</span> tunnel protection ipsec profile VPN-PROFILE</pre>","exPlain":"R1(config-if)# tunnel mode ipv6ip isatap\nR1(config-if)# tunnel mode gre ip\nR1(config-if)# tunnel protection ipsec profile VPN-PROFILE","neg":"no tunnel mode","kind":"cmd"},{"i":348,"sec":"ipv6","no":"24","secAr":"IPv6 المتقدم","secEn":"Advanced IPv6","grp":"modern","syn":"nat64 enable | nat64 prefix <i>64:ff9b::/96</i>","synPlain":"nat64 enable | nat64 prefix 64:ff9b::/96","mode":"Global / Interface","modeCls":"m-gconf","ar":"<b>NAT64</b> يسمح لأجهزة IPv6 فقط بالوصول إلى خوادم IPv4 عبر ترجمة العناوين (مع DNS64). البادئة القياسية <code>64:ff9b::/96</code>. الصيغة تختلف بين IOS-XE وإصدارات ASR، فراجع دعم المنصّة في وثائق الإصدار قبل التطبيق.","en":"Translates between IPv6 and IPv4 (with DNS64) using the well-known 64:ff9b::/96 prefix.","ex":"<pre><span class=\"p\">R1(config)#</span> nat64 prefix 64:ff9b::/96\n<span class=\"p\">R1(config)#</span> interface g0/1\n<span class=\"p\">R1(config-if)#</span> nat64 enable\n<span class=\"p\">R1#</span> show nat64 translations</pre>","exPlain":"R1(config)# nat64 prefix 64:ff9b::/96\nR1(config)# interface g0/1\nR1(config-if)# nat64 enable\nR1# show nat64 translations","neg":"no nat64 enable","kind":"cmd"}];
